/* مولَّد: node tools/build-mom-guide.mjs — لا يُحرَّر يدوياً */
const MOM = {"units":[{"id":"U01","zh":"方位与模型","ar":"التوجيه والنماذج"},{"id":"U02","zh":"运动：骨骼、关节和肌肉","ar":"الحركة: عظام ومفاصل وعضلات"},{"id":"U03","zh":"心脏、血液和血管","ar":"القلب والدم والأوعية"},{"id":"U04","zh":"呼吸：空气和肺","ar":"التنفس: الهواء والرئتان"},{"id":"U05","zh":"能量的桥梁：细胞","ar":"جسر الطاقة والخلية"},{"id":"U06","zh":"食物：从一口饭到血液","ar":"الطعام: من اللقمة إلى الدم"},{"id":"U07","zh":"肾脏和水","ar":"الكليتان والماء"},{"id":"U08","zh":"大脑、神经和感官","ar":"الدماغ والأعصاب والحواس"},{"id":"U09","zh":"皮肤、防御、体温和疫苗","ar":"الجلد والدفاع والحرارة واللقاحات"},{"id":"U10","zh":"成长、青春期、隐私与界限","ar":"النمو والبلوغ والخصوصية والحدود"},{"id":"U11","zh":"综合议题","ar":"قضايا التكامل"}],"lessons":[{"id":"U01.L01","unit":"U01","ar":"جسمي على الخريطة: أجزاء ومناطق ونموذج","zh":"我的身体地图：部位、区域和模型","point":"为了准确地描述身体，我们用大家公认的名称来称呼身体的各个区域和方向；同时要记住：任何一幅身体图都只是模型，它显示一个想法，也隐藏了很多细节。","objectives":[{"zh":"能在图上指出主要区域：头、颈、躯干（胸部、腹部、背部）、上肢（上臂、前臂、手）、下肢（大腿、小腿、脚）；能分清区域名称和区域里的器官名称（腹部不等于胃）。"},{"zh":"能用方向词描述一个部位的位置：上/下、前/后、靠近中线/远离中线。"},{"zh":"知道图画是模型：它显示一个想法，也隐藏细节（大小、颜色、数量、动作），并能说出某个模型显示了什么、没显示什么。"},{"zh":"面对一幅身体图时能分清图中人的左右（图的右边在我的左边），并以身体主人为准使用前/后、上/下、左/右这些词。","b":true}],"terms":[{"ar":"الجذع","zh":"躯干","py":"qūgàn","en":"Trunk"},{"ar":"الصدر","zh":"胸部","py":"xiōngbù","en":"Chest"},{"ar":"البطن","zh":"腹部","py":"fùbù","en":"Abdomen"},{"ar":"الأطراف","zh":"四肢","py":"sìzhī","en":"Limbs"},{"ar":"النموذج","zh":"模型","py":"móxíng","en":"Model"}],"do":"“用测量画出我的身体地图”：孩子背靠墙量身高，再张开双臂量两手指尖之间的距离（臂展），比较两个数字；把脚放在前臂上比较脚长和前臂长；在本子上画一个简单的人形，标出头、颈、胸、腹、背、上臂、前臂、手、大腿、小腿、脚，并写下这幅图没有显示的一件事。","safety":["只量自己，或在同学同意后再量；不经允许不量别人。","不比较孩子们的身高，也不评论别人的身体；每个人不一样是正常的。"],"explain":"可以这样说：“我们把身体分成几大块：头在最上面，用脖子连着身体；中间最大的一块叫躯干，前面上半部是胸，下面是肚子（腹部），后面是背。两边是手臂，下面是腿。手臂分三段：上臂、前臂、手；腿也分三段：大腿、小腿、脚。肚子是一个区域的名字，不是一个器官——肚子里面有胃、肠子等很多器官。说位置要用方向：上、下、前、后、靠近中间、远离中间。还有，书上的图不是真的身体，它是模型：有的地方放大了，有的上了颜色，很多细节省略了。看每一幅图都要问两个问题：它告诉我什么？它没告诉我什么？”","mis":[{"says":"“肚子就是胃。”","answer":"肚子是一个大区域，里面有胃、肠子、肝脏等。胃只是其中一个器官，在肚子的左上方。说“肚子疼”是在说一个区域。"},{"says":"“图上的手指是彩色的，骨头是白色分开的，所以真的就是那样。”","answer":"图画是模型：为了说明而放大、上色。我们要一直问：它显示了什么？隐藏了什么？"},{"says":"“图的右边就是我的右边。”","answer":"当一个人面对你时，他的右边在你的左边。和同学握手试试：你的右手碰到他的右手，两只手是相对的，不是重合的。"},{"says":"“手就是整条手臂”/“手臂就是上臂”。","answer":"手是手腕以后的最后一段；手臂是整条上肢，分为上臂、前臂和手。要说清楚你指的是哪一段。"}],"dinner":{"q":"如果你肚子疼，你怎么向医生准确描述疼的位置？肚子就是胃吗？","listen":"肚子是一个区域，里面有很多器官，胃只是其中一个。描述位置要用方向：偏上还是偏下，靠前还是靠后，靠近中间还是远离中间。"},"faith":[]},{"id":"U01.L02","unit":"U01","ar":"كيف نعرف؟ ألاحظ وأصف وأقيس","zh":"我们怎么知道？观察、描述和测量","point":"我们通过仔细观察、重复测量和公平比较来认识事物，还借助仪器看到眼睛看不到的东西；猜测在被检验之前不算知识。","objectives":[{"zh":"能分清观察（我看到或量到的）和推测、猜测（我认为的），并能写出不含猜测的描述。"},{"zh":"能用简单工具（尺子、计数、计时器）测量并记录，重复三次取中间数，并解释为什么一次不够。"},{"zh":"知道一些仪器（显微镜、X光、听诊器、超声波）能显示眼睛看不到的东西，看不到的东西也可能存在。"},{"zh":"能设计公平测试：只改变一件事，其余保持不变；并能认出不公平的比较。","b":true}],"terms":[{"ar":"الملاحظة","zh":"观察","py":"guānchá","en":"Observation"},{"ar":"القياس","zh":"测量","py":"cèliáng","en":"Measurement"},{"ar":"المقارنة العادلة","zh":"公平测试","py":"gōngpíng cèshì","en":"Fair test"},{"ar":"الأداة الكاشفة","zh":"仪器","py":"yíqì","en":"Instrument"}],"do":"“用尺子测反应时间”：孩子把手肘放在桌上，拇指和食指张开；同伴竖着拿尺子，零刻度在两指之间，不打招呼突然松手，孩子尽快抓住，读出手指处的数字（下落距离）。先练两次不记，再正式量三次，把三个数排好取中间数，再查表换算成反应时间。","safety":["不在大家面前比较孩子；每个孩子只和自己比。","尺子是松手让它落下，不是扔；远离脸部。"],"explain":"可以这样说：“看这两张图：一张孩子的手举着，一张放下。我们能说'手举着'——这是观察，看得见。可他为什么举手？也许想提问，也许在打招呼——这是猜测，看不见。科学家把看到的和想到的分开，对猜测会说'我还不知道'。观察加上数字就更有力：'尺子掉了很多'不清楚，'掉了18厘米'才是测量。量三次可能得到15、21、18，取中间的18。一次可能是碰巧，三次更接近真实。有些东西眼睛看不见：显微镜让我们看到细胞，X光能看到皮肤下的骨头，听诊器能听到心跳，超声波能看到妈妈肚子里的宝宝。仪器不是制造事实，而是把事实显示出来。比较时只改变一件事，其他都一样，这叫公平测试。”","mis":[{"says":"“看不见的东西就不存在（细菌、细胞）。”","answer":"眼睛只能看到大于十分之一毫米的东西。显微镜让人看到了一直存在的整个世界。细胞单元会讲到。"},{"says":"“我试了一次就知道了。”","answer":"再试第二次、第三次，看看数字是不是一样。一次测量可能只是碰巧。"},{"says":"“我看到同学举手，所以他想提问。”","answer":"看到的是：手举起来了。想到的是：他想提问。前者是观察，后者是猜测，可能对也可能不对。我们记录前者，检验后者。"}],"dinner":{"q":"如果你的兄弟姐妹说他的反应比你快，我们怎样公平地检验？","listen":"用工具量（落下的尺子或计时器），每人量三次取中间数，因为一次不够。还要分清自己看到、量到的和自己猜的。"},"faith":[]},{"id":"U02.L01","unit":"U02","ar":"الهيكل: دعم وحماية وعظم حي","zh":"骨骼：支撑、保护和活的骨头","point":"骨头是活的：它支撑身体、保护器官，和肌肉一起让身体运动；它会生长、会愈合，里面还能造血。人出生时大约有300块骨头和软骨，随着成长逐渐愈合，成年人有206块骨头。","objectives":[{"zh":"能说出骨骼的三个作用：支撑身体并给它形状；保护器官（颅骨保护大脑，胸廓保护心脏和肺，脊柱保护脊髓）；和肌肉一起完成运动。"},{"zh":"能在骨骼图上指出颅骨、脊柱、胸廓、骨盆、肱骨（上臂骨）、股骨（大腿骨），并能在自己身上摸到皮下的骨头（头骨、锁骨、肋骨、膝盖骨）。"},{"zh":"知道骨头是活的组织：会生长，骨折后会愈合，里面有血管，中间的骨髓能制造血细胞；它不是干木棍。"},{"zh":"知道婴儿出生时约有300块骨头和很多软骨，长大后愈合成206块；骨头通过运动和营养（钙和维生素D）变强，缺少活动会变弱。","b":true}],"terms":[{"ar":"الهيكل العظمي","zh":"骨骼","py":"gǔgé","en":"Skeleton"},{"ar":"الجمجمة","zh":"颅骨","py":"lúgǔ","en":"Skull"},{"ar":"العمود الفقري","zh":"脊柱","py":"jǐzhù","en":"Spine"},{"ar":"القفص الصدري","zh":"胸廓","py":"xiōngkuò","en":"Rib cage"},{"ar":"نخاع العظم","zh":"骨髓","py":"gǔsuǐ","en":"Bone marrow"}],"do":"“摸摸我的骨骼，数数手骨”：孩子摸头顶的颅骨、动动下巴（颅骨里唯一能动的骨头）、摸颈下的锁骨、深呼吸时感觉肋骨在动、摸膝盖上的膝盖骨；再数一根手指有几节骨头（三节，拇指两节），算出五根手指一共有几块骨头，记在本子上。","safety":["只轻轻摸自己的身体；不经允许不摸别人。","不按压脊柱和脖子，不测试柔韧性，不弯折别人的身体。","受伤或打着石膏的孩子可以在图上观看和计数。"],"explain":"可以这样说：“这是你的骨骼，由很多骨头连在一起，成年人有206块，你现在还多一些，因为有些还没长在一起。骨骼有三个作用：第一是支撑，没有骨头身体就像一个站不起来的口袋；第二是保护，颅骨像盒子一样保护大脑，十二对肋骨围着心脏和肺，脊柱像一根管子保护里面的脊髓；第三是运动，骨头自己不会动，是肌肉在关节处拉动它。最重要的是：骨头是活的！外面是硬的，里面软软的部分叫骨髓，那里能制造血细胞。骨头里有血管和神经，所以骨折时会流血、会疼，几周后身体会在断处长出新骨头。博物馆里的骨头已经死了、干了；你的骨头正在工作。”","mis":[{"says":"“骨头是干的、死的，像博物馆里的骨头。”","answer":"骨头是活的：会长大，骨折后会愈合，断了会流血会疼，里面还有造血的“工厂”。你见过的干骨头是已经死去的。"},{"says":"“骨头不长，我们长高是因为肉多了。”","answer":"长骨在整个童年都从两端生长，所以腿和手臂会变长；长完以后就停止。"},{"says":"“骨头越重越结实，运动不会改变骨头。”","answer":"骨头和肌肉一样会对使用做出反应：跳跃和走路让它变强，缺少活动会让它变弱。童年时期打下一辈子的骨头基础。"},{"says":"“肋骨围着肚子和胃。”","answer":"胸廓围着胸部，保护心脏和肺；它的下缘遮住腹部上方（肝、脾和一部分胃）；腹部下面没有骨头，这样才能扩张和活动。"},{"says":"“骨髓就是脊髓。”","answer":"两个名字很像，但是不同的东西：骨髓是骨头里造血的物质；脊髓是脊柱里面的一束神经。"},{"says":"“男人比女人少一根肋骨。”","answer":"不对，每个人都是12对。可以在X光片上数一数。这是一个流传的说法，要靠观察来检验，而不是靠听说。"}],"dinner":{"q":"你手臂里的骨头是活的，还是像一根干木棍？你怎么知道的？","listen":"骨头是活的：会生长，骨折后会愈合，里面有血管，中间的骨髓能制造血细胞。它还保护器官：颅骨保护大脑，肋骨保护心脏和肺。"},"faith":[]},{"id":"U02.L02","unit":"U02","ar":"المفاصل: حيث تلتقي العظام","zh":"关节：骨头相遇的地方","point":"关节是两块骨头相接的地方；关节的形状决定它怎样活动，韧带把它连住，软骨使它光滑，而且它有活动极限，不能强迫。","objectives":[{"zh":"知道关节是两块骨头相接的地方，能在自己身上和图上指出肩、肘、手腕、髋、膝、踝和手指关节。"},{"zh":"能按活动方式给关节分类：屈戌关节（肘和膝，像门一样只朝一个方向）、球窝关节（肩和髋，可以朝很多方向）、不动关节（颅骨的骨头不能动）。"},{"zh":"知道韧带在关节处把骨头连在一起，软骨盖在骨头末端使它光滑、防止摩擦，关节不能被强迫做它不允许的动作。"},{"zh":"能解释关节形状和活动的关系（球在窝里可以转动；屈戌关节只能在一个平面上弯曲），说明身体为什么两种都需要，并认识“半活动”关节（椎骨之间）。","b":true},{"zh":"能解释为什么不同资料里关节的数目不同（有的说“约350个”，有的多或少），这取决于怎样定义关节；用两种定义数自己手上的关节，得到两个都正确的不同数字。","b":true}],"terms":[{"ar":"المفصل","zh":"关节","py":"guānjié","en":"Joint"},{"ar":"المفصل الرزّي","zh":"铰链关节","py":"jiǎoliàn guānjié","en":"Hinge joint"},{"ar":"المفصل الكروي","zh":"球窝关节","py":"qiúwō guānjié","en":"Ball-and-socket joint"},{"ar":"الرباط","zh":"韧带","py":"rèndài","en":"Ligament"},{"ar":"الغضروف","zh":"软骨","py":"ruǎngǔ","en":"Cartilage"}],"do":"“关节大检查”：孩子依次活动肘（能弯能伸，能不能转一整圈？）、肩（慢慢把手臂转一整圈）、膝（能不能往侧面弯？不要硬掰）、髋（腿向前、向侧抬起，再稍微转动）、手指（中间关节只朝一个方向，指根关节还能稍微左右分开）、头（左右转头，再摸摸头顶：颅骨本身会动吗？），每一项都记录下来。","safety":["只活动自己的关节，慢慢来，只做它自己能做到的范围；不要硬掰，也不要用另一只手推。","不测试同学的柔韧性，不弯折别人的四肢，这样会拉伤韧带。","有关节受伤或疼痛的孩子只在图上记录。"],"explain":"可以这样说：“两块骨头相遇的地方就有一个关节。在你身上数一数：肩、肘、手腕、手指关节、髋、膝、踝。没有关节，骨骼就是一整块，弯不了。看肘部：一块骨头的末端套在另一块骨头上，像门的合页，所以只能朝一个方向弯和伸，不能转一整圈，这叫屈戌关节，膝盖也是这样。肩膀不一样：骨头的头是一个球，放在圆形的窝里，所以手臂可以朝各个方向转，这叫球窝关节，髋关节也是。有些关节完全不动，比如颅骨的骨头长在一起保护大脑。是什么让两块骨头不分开？结实的带子，叫韧带。是什么让它们不互相摩擦？骨头末端光滑的软骨和中间滑滑的液体。韧带有极限：硬把关节往不该去的方向掰，韧带就会撕裂。所以玩耍和开玩笑时都不能强迫别人的关节。”","mis":[{"says":"“所有关节的活动方式都一样。”","answer":"试一试：肩膀能转一整圈，再试着让前臂绕着肘转一整圈——做不到。关节的形状决定它怎样活动。"},{"says":"“柔软的关节只要用力推就能往任何方向弯。”","answer":"不能。韧带阻止超出范围的动作，强迫它会撕裂韧带（扭伤）。无论玩耍还是开玩笑，都绝不强掰关节。"},{"says":"“掰手指出声会得关节炎。”","answer":"那个响声是关节液里的气泡；研究没有发现它会导致关节炎。这是一个被科学检验过的流行说法。"}],"dinner":{"q":"为什么你的手臂能从肩膀转一整圈，而肘只能朝一个方向弯？","listen":"肩是球窝关节，可以朝很多方向动；肘是屈戌关节，像门的合页。关节不能被强迫做它不允许的动作。"},"faith":[]},{"id":"U02.L03","unit":"U02","ar":"العضلات تسحب ولا تدفع","zh":"肌肉只拉不推","point":"肌肉收缩时通过肌腱拉动骨头，从来不推；所以肌肉在关节两边成对地、相对地工作。","objectives":[{"zh":"能解释肌肉收缩时变短，通过肌腱在关节处拉动骨头，肌肉从不推。"},{"zh":"知道肌肉成对相对地工作：一块使关节弯曲，另一块使它伸直；一块收缩时另一块放松。"},{"zh":"能区分三种肌肉：骨骼肌（随意肌，拉动骨头）、平滑肌（不随意肌，在胃、肠和血管里）、心肌。"},{"zh":"能解释肌肉越用越强，不用就变弱，休息和睡眠也是肌肉成长的一部分；并分清肌腱和韧带（肌腱连接肌肉和骨头，韧带连接骨头和骨头）。","b":true}],"terms":[{"ar":"العضلة","zh":"肌肉","py":"jīròu","en":"Muscle"},{"ar":"الوتر","zh":"肌腱","py":"jījiàn","en":"Tendon"},{"ar":"الانقباض","zh":"收缩","py":"shōusuō","en":"Contraction"},{"ar":"الزوج المتقابل","zh":"拮抗肌","py":"jiékàngjī","en":"Antagonistic pair"}],"do":"“感受手臂的两块肌肉轮流工作”：孩子把一只手放在另一只手臂上臂的前面，慢慢弯肘把书举向肩膀，感觉前面的肌肉变粗变短（收缩）；再把手放到上臂后面，把书向桌面压、慢慢伸直手臂，感觉后面的肌肉收缩。重复三次并记录：弯曲时哪块工作，伸直时哪块工作。","safety":["只用很轻的东西；不举重，不比力气。","每个孩子只在自己身上做，不比较孩子们的手臂。","感到任何疼痛就停下。"],"explain":"可以这样说：“肌肉只会做一件事：收缩。收缩时它变短、变粗。肌肉通过一根结实的绳子连在骨头上，这根绳子叫肌腱。肌肉变短时拉肌腱，肌腱拉骨头，骨头就在关节处动起来。只有拉，肌肉从来不推！那手臂怎么伸直呢？靠另一边的另一块肌肉。前面的肌肉把前臂拉上来，肘就弯了；后面的肌肉从后面拉，手臂就伸直了。一块工作，另一块就放松。身体里每个关节都有这样一对或更多。肌肉也不只在手臂上，一共有三种：你能控制的、拉动骨头的骨骼肌；在胃、肠和血管壁里自己工作的平滑肌；还有永不停歇的心肌。你睡觉时它们都在工作。”","mis":[{"says":"“伸直手臂时是肌肉在推骨头。”","answer":"肌肉只会拉。伸直手臂时，是后面的肌肉（肱三头肌）从后面拉前臂。伸手臂时把手放在上臂后面，就能感觉到它在收缩。"},{"says":"“不运动了，肌肉就会变成肥肉。”","answer":"肌肉和脂肪是两种不同的组织，不会互相变化。不用肌肉它会萎缩，吃得比需要多脂肪会增加，这是两件不同的事。"},{"says":"“心脏和胃里没有肌肉，肌肉只在手臂上。”","answer":"心脏整个就是肌肉，胃和肠靠你控制不了的平滑肌蠕动。随意肌只是三种肌肉中的一种。"}],"dinner":{"q":"肌肉只拉不推，那你弯起手臂以后怎么把它伸直？","listen":"靠两块相对的肌肉：前面的收缩让手臂弯曲，后面的收缩让手臂伸直，一块工作时另一块放松。"},"faith":[]},{"id":"U02.L04","unit":"U02","ar":"قضية الوحدة: أبني ذراعاً تتحرك","zh":"单元项目：做一只会动的手臂","point":"这一课没有新知识：用骨头、关节、肌肉和肌腱来做一个模型、检查模型、解释生活中的情况，并留下一个开放的问题：是谁命令肌肉动？肌肉的力量从哪里来？","objectives":[{"zh":"用硬纸板做一只手臂模型：一个屈戌关节和两根线（一对肌肉），只靠拉来活动，并在模型上标出骨头、关节、肌肉和肌腱。"},{"zh":"在一个错误的模型里找出本单元的错误（肌肉在推、只有一块肌肉、关节朝错误方向转、肌腱只连着一块骨头、骨头是实心的没有骨髓）并改正。"},{"zh":"用本单元的三个概念解释一个日常情况（跳跃、背书包、打石膏的骨折、扭伤脚踝）。"},{"zh":"说出纸模型的局限（显示了什么、没显示什么），并写出下一单元的开放问题：谁命令肌肉？肌肉的能量从哪里来？","b":true}],"terms":[{"ar":"نموذج الحركة","zh":"运动模型","py":"yùndòng móxíng","en":"Movement model"}],"do":"“做一只有两块肌肉的纸手臂”：两条硬纸板分别写上“上臂骨”和“前臂骨”，用纸钉把一端连起来，让前臂只能朝一个方向弯（这是哪种关节？）；把两根线分别贴在前面和后面，代表前后两块肌肉；拉前面的线手臂弯曲，拉后面的线手臂伸直。也可以在大人陪同下观察煮熟的鸡翅里的肌肉、肌腱和关节。","safety":["小心使用纸钉；没有大人在场不用锋利的剪刀。","鸡翅要煮熟，并在大人监督下进行：前后洗手，活动中不吃东西，桌面铺好并在结束后清洁，剩余物装进封好的袋子；手上有伤口的戴手套；过敏或不想做的孩子不勉强。","不要拿同学的手臂拉扯来试模型。"],"explain":"可以这样说：“今天没有新内容。我们学过三条规则：骨头硬，起支撑作用；关节决定运动方向；肌肉通过肌腱拉，不会推，所以成对工作。今天用这些规则做一个模型，再检查一个做错的模型，然后解释生活中的事情。做好以后你会发现，纸模型缺一样东西：是谁在拉线？在你身体里，是谁命令肌肉去拉？力量又从哪里来？把这个问题记在本子上，这是下一单元的开放问题。”","mis":[{"says":"（同时拉两根线，或想“推”线）","answer":"线不能推，肌肉也一样。拉一根，放松另一根。"},{"says":"（把肘关节做成可以朝各个方向转）","answer":"肘是屈戌关节，只朝一个方向。你身上哪个关节才能这样转？"},{"says":"（把模型的骨头画成实心的，“因为它是棍子”）","answer":"真正的骨头里面有什么？"}],"dinner":{"q":"你跳起来时，身体里什么在工作？说出一些骨头、关节和肌肉。","listen":"大腿和小腿的肌肉收缩，通过肌腱在髋、膝、踝关节处拉动骨头。能把本单元的三个概念联系起来就够了。"},"faith":[]},{"id":"U03.L01","unit":"U03","ar":"القلب: مضخة لا تتوقف","zh":"心脏：永不停歇的泵","point":"心脏是位于胸部中间的空心肌肉，它不停地收缩，把血液通过血管送到全身；身体需要更多运输时，它会跳得更快。","objectives":[{"zh":"能在新的图上指出心脏的位置：胸部中间稍偏左，在两肺之间、胸骨后面。"},{"zh":"能解释心脏是空心的肌肉，收缩时把血液推进血管，送到身体各个部分。"},{"zh":"能数自己的脉搏，并解释脉搏是每次心脏收缩推出的一股血流；能观察到运动后脉搏变快，休息后恢复。"},{"zh":"能分清❤符号和真正的心脏形状，并说出课本图画没有显示的一件事。"},{"zh":"知道心脏有四个腔（上面两个心房，下面两个心室）和防止血液倒流的瓣膜，“扑通”声是瓣膜关闭的声音。","b":true},{"zh":"知道心脏右侧把血送到肺，左侧把血送到全身其他部分。","b":true},{"zh":"能解释运动时脉搏为什么加快：工作的肌肉需要更多氧气和养分，也产生更多废物，所以心脏加快运输。","b":true}],"terms":[{"ar":"القلب","zh":"心脏","py":"xīnzàng","en":"Heart"},{"ar":"الوعاء الدموي","zh":"血管","py":"xuèguǎn","en":"Blood vessel"},{"ar":"النبض","zh":"脉搏","py":"màibó","en":"Pulse"},{"ar":"الصدر","zh":"胸部","py":"xiōngbù","en":"Chest"},{"ar":"الأُذين","zh":"心房","py":"xīnfáng","en":"Atrium"},{"ar":"البُطين","zh":"心室","py":"xīnshì","en":"Ventricle"},{"ar":"الصِّمام","zh":"瓣膜","py":"bànmó","en":"Valve"}],"do":"“数我的脉搏：休息、运动、再休息”：孩子安静坐两分钟，把食指和中指（不用拇指）轻按在手腕内侧拇指根下方，数15秒的跳动再乘以4，记在“休息”下；原地快走或轻跳一分钟后马上坐下再数一次；休息两分钟后数第三次；比较三个数字：什么变多了？什么又恢复了？","safety":["这不是比赛；不比较孩子们的数字，每个人不一样是正常的。","如果感到头晕、疼痛或喘不过气，马上停下坐好，并告诉大人。","只有负责的大人可以摸脖子的脉搏，要坐着、轻按、只按一侧；孩子只数手腕的脉搏。按压脖子可能使心跳变慢或晕倒。","已知有心脏或呼吸方面问题的孩子，经家长同意只做坐着的部分（数休息时的脉搏）。","不憋气，不比赛跑步。","任何心脏或呼吸方面的情况，要在上课前（不是上课中）向家长了解清楚。","孩子在运动中晕倒、胸痛或心跳得很厉害，要马上停止并去看医生，而不只是“告诉大人”。","天气炎热或长时间空腹（如封斋后）时不做这个实验；用哮喘喷雾的孩子要带在身边。"],"explain":"可以这样说：“这是胸部，有胸廓保护着。在胸骨后面、胸部中间，心脏稍微偏左，夹在两肺之间，大小像你自己的拳头。心脏是一块空心的肌肉，和所有肌肉一样会收缩和放松。收缩时把里面的血挤出去，放松时又装满血。收缩、放松、收缩……从不停止。血从心脏出来，在叫血管的管子里流到头、手、脚和每一个地方，然后再回到心脏。血给身体送去氧气和养分，带走二氧化碳和其他废物。每收缩一次，就有一股血流过血管；在手腕这样大动脉靠近皮肤的地方，用手指就能摸到，这就是脉搏。还有，❤只是表达感情的符号，不是真正的心脏形状。”","mis":[{"says":"“心脏在左边，形状像❤。”","answer":"把拳头放在胸部中间，再稍微往左移：这就是心脏的位置和大小。❤是表达感情的古老符号，不是解剖图。"},{"says":"“是心在爱、在害怕。”","answer":"是大脑处理情绪，并发出信号让心跳加快。不过心脏也把自己的状态告诉大脑，大脑用这些信息形成感受，所以我们会在胸口感到害怕。"},{"says":"“心脏制造血液。”","answer":"心脏只负责推动血液。血细胞是在骨头里（骨髓）制造的，第3课会讲到。"},{"says":"“静脉里的血是蓝色的。”","answer":"血永远是红色的：氧气多时鲜红，氧气少时暗红。图上的蓝色只是表示含氧少的血，不是它的颜色；皮肤下的静脉看起来发蓝是因为皮肤和光线。"},{"says":"“我跑步时，肺直接把氧气送到腿上。”","answer":"肺到不了你的腿。氧气在肺里进入血液，再由心脏把血推到肌肉。所以跑步时心跳会加快，而不只是呼吸加快。"},{"says":"“心脏像图上那么大。”","answer":"我们把它画大是为了看清楚。它真正的大小就像你自己的拳头。"}],"dinner":{"q":"把手放在你心脏的位置。你跑步时它为什么跳得更快？","listen":"心脏在胸部中间稍偏左。它是泵血的肌肉，我们运动时肌肉需要更多血，所以它跳得更快，休息后又会慢下来。"},"faith":[]},{"id":"U03.L02","unit":"U03","ar":"طرق الدم: شرايين وأوردة وشعيرات","zh":"血液的道路：动脉、静脉和毛细血管","point":"血液在一个封闭的血管循环里流动：动脉把血带离心脏，很细的毛细血管在那里和细胞交换物质，静脉把血送回心脏；在所有这些道路里，血都是红色的。","objectives":[{"zh":"能区分三种血管：动脉把血带离心脏，静脉把血送回心脏，两者之间是很细的毛细血管。"},{"zh":"能解释物质交换（氧气和养分送进细胞，废物从细胞出来）发生在毛细血管，因为它的管壁非常薄。"},{"zh":"能解释血永远是红色的，图上的蓝色只是标记；静脉在皮肤下看起来发蓝是光线和皮肤造成的，不是血的颜色。"},{"zh":"能说出两个循环：肺循环（右心→肺→左心）和体循环（左心→全身→右心），并知道它们是同时进行的。","b":true},{"zh":"能解释为什么动脉壁厚而有弹性、静脉里有瓣膜，并知道肺动脉是一条运送含氧少的血的动脉。","b":true}],"terms":[{"ar":"الشريان","zh":"动脉","py":"dòngmài","en":"Artery"},{"ar":"الوريد","zh":"静脉","py":"jìngmài","en":"Vein"},{"ar":"الشعيرة الدموية","zh":"毛细血管","py":"máoxì xuèguǎn","en":"Capillary"},{"ar":"الدورة الرئوية","zh":"肺循环","py":"fèi xúnhuán","en":"Pulmonary circulation"},{"ar":"الدورة الجهازية","zh":"体循环","py":"tǐ xúnhuán","en":"Systemic circulation"}],"do":"“手上的静脉会消失又出现”：孩子把手臂垂在椅子旁半分钟，看手背上的静脉是否鼓起；再把手举过头顶半分钟，看静脉有什么变化；放下手看静脉重新出现。还可以做“哈维实验”：在前臂或手背选一条直的静脉，用两根手指按住它的两端，观察血液流动的方向。","safety":["只轻轻按；不勒、不在手臂上绑东西。","不用热水。","静脉看不清楚的孩子，可以在同学同意后看同学的手或看课本图片；每个人皮肤不同，静脉明显程度不同是正常的。"],"explain":"可以这样说：“上一课看到心脏推血，今天我们沿着血的道路走。血从心脏出来，走在结实的血管里，叫动脉。动脉把血带离心脏，送到头、手臂、腿和每一个器官。离心脏越远，动脉分得越细，最后变成比头发还细的毛细血管。毛细血管的壁很薄，只有一层细胞。只有在这里，氧气和养分才从血里出来进入细胞，细胞的废物才进入血里，毛细血管是交换站。之后血管又汇合变粗，成为静脉，静脉把血送回心脏。动脉去、毛细血管交换、静脉回：这是一个不停的封闭循环。你手上的静脉看起来发蓝，但里面的血是暗红色的，是光线和皮肤让它看起来发蓝。”","mis":[{"says":"“静脉里的血是蓝的，我在手上看见了。”","answer":"你看到的是透过皮肤反射的光的颜色，不是血的颜色。静脉被划破时流出的是暗红色的血。书上的蓝色只是表示含氧少的血。"},{"says":"“氧气从大动脉直接出来进入肌肉。”","answer":"动脉壁很厚，什么都穿不过去。交换只发生在毛细血管，因为它的壁只有一层细胞。"},{"says":"“血先去肺，再等着回来才去全身。”","answer":"两个心室在同一时刻一起收缩：每跳一次，一股血去肺，一股血去全身。两个循环是连在一起同时转的，不是轮流的。"},{"says":"“有氧气的是动脉，有废物的是静脉。”","answer":"动脉是按方向定义的：离开心脏。肺动脉是动脉，却把含氧少的血送到肺。所以规则看方向，不看里面装的是什么。"}],"dinner":{"q":"你手腕上的血管看起来是蓝的。里面的血是蓝色的吗？","listen":"血永远是红的，发蓝是光线和皮肤造成的。动脉把血从心脏带出来，静脉把血送回心脏，在它们之间细小的毛细血管里，血留下氧气、带走废物。"},"faith":[]},{"id":"U03.L03","unit":"U03","ar":"ماذا في الدم؟ فريق النقل والدفاع والإصلاح","zh":"血液里有什么？运输、防御和修补的团队","point":"血液是一种液体（血浆），里面漂着三种细胞，各有各的工作：红细胞运送氧气，白细胞负责防御，血小板堵住伤口；它们都是在骨髓里制造的。","objectives":[{"zh":"知道血液不是一种单一的液体，而是血浆里漂着细胞：红细胞、白细胞和血小板。"},{"zh":"能把每种成分和它的工作联系起来：红细胞运氧气，白细胞抵御微生物，血小板堵伤口，血浆运送养分、废物和细胞。"},{"zh":"知道血细胞是在骨头里（骨髓）制造的，不是在心脏里；红细胞大约活四个月，然后被替换。"},{"zh":"能解释伤口是怎样被堵住的：血小板聚集在破口处粘在一起，形成纤维网把细胞网住，形成血块，然后结痂。","b":true},{"zh":"能把红细胞和血液循环联系起来：它在肺的毛细血管装上氧气，在全身的毛细血管卸下氧气，颜色在鲜红和暗红之间变化。","b":true}],"terms":[{"ar":"البلازما","zh":"血浆","py":"xuèjiāng","en":"Plasma"},{"ar":"الكريّة الحمراء","zh":"红细胞","py":"hóngxìbāo","en":"Red blood cell"},{"ar":"الخلية البيضاء","zh":"白细胞","py":"báixìbāo","en":"White blood cell"},{"ar":"الصفيحة الدموية","zh":"血小板","py":"xuèxiǎobǎn","en":"Platelet"},{"ar":"نخاع العظم","zh":"骨髓","py":"gǔsuǐ","en":"Bone marrow"}],"do":"“杯子里的血液模型”：孩子在杯子里倒一大半偏黄的果汁或水（血浆），加一大把红扁豆（红细胞），看整杯颜色的变化；再放一两颗白色鹰嘴豆（白细胞，数量很少），撒一点粗粒小麦粉（血小板，又小又多）；搅拌后静置一分钟，观察各种“细胞”怎样分开。","safety":["这个模型只看不吃。","不用真的血，也不为了看血而划伤任何人。","活动后把桌子擦干净。"],"explain":"可以这样说：“我们知道血永远是红的。可是有个惊喜：血里的液体并不是红的！在实验室里把一管血快速旋转，它会分成两层：上面是淡黄色的液体，叫血浆；下面是细胞。血浆大部分是水，运送养分和废物，细胞就漂在里面。数量最多的是红细胞，像中间凹下去的小圆盘，每一滴血里有几百万个，是它们让血变红。它们在肺里抓住氧气，在身体的毛细血管里放下氧气，是氧气的运输车。还有个头更大但少得多的白细胞，负责抵御微生物，生病时它们会变多。最后是很小的血小板：血管破了，它们就聚到破口处堵住它，所以小伤口会自己止血。这些细胞都是在骨头里的骨髓制造的，不是在心脏。”","mis":[{"says":"“心脏制造血液。”","answer":"心脏只负责推动血液。造血的“工厂”在你的骨头里：骨髓每秒制造几百万个细胞。"},{"says":"“血是像果汁一样的红色液体。”","answer":"血是淡黄色的液体（血浆），里面充满了极小的红色圆盘，是它们给血上了颜色。如果把它们分出来，就会看到液体是黄色的。"},{"says":"“白细胞是一支会计划、会进攻的军队。”","answer":"没有谁在做计划。白细胞按一定的机制工作：有的吞掉碰到的微生物，有的认出微生物表面的标记。防御单元会详细讲。我们说它们“防御”，不用打仗来比喻。"},{"says":"“红细胞放下氧气后变成蓝色。”","answer":"它变成暗红色，不是蓝色。无论什么时候，血都是红的。"}],"dinner":{"q":"小伤口为什么会自己止血？是谁制造血液的？","listen":"血小板把伤口堵住。血液是血浆，里面有运氧气的红细胞和负责防御的白细胞。血细胞是在骨髓里制造的，不是在心脏里。"},"faith":[]},{"id":"U03.L04","unit":"U03","ar":"قضية الوحدة: أفحص نموذج الدورة الدموية","zh":"单元项目：检查血液循环模型","point":"这一课没有新知识：用前三课学到的内容来检查模型、解释生活中的情况，并写出下一单元的开放问题。","objectives":[{"zh":"在一个血液循环模型里找出前三课的错误并改正（心脏的位置、血管的方向、交换的地方、血的颜色、造血的地方）。"},{"zh":"跟踪一个红细胞从肺到小腿肌肉再回来，说出每一段是哪种血管，以及在毛细血管里发生了什么。"},{"zh":"用本单元至少三个概念解释一个日常情况（小伤口、爬楼梯、玩耍后静脉鼓起）。"},{"zh":"能分几步解释：为什么血液需要两个分开的循环，为什么左心室更强壮，并说出循环模型的一个局限。","b":true},{"zh":"能分清本单元哪些已有证据（血液在循环、毛细血管存在），哪些还是开放问题（氧气是怎样进入血液的），并为下一单元写出这个问题。","b":true}],"terms":[{"ar":"نموذج الدورة الدموية","zh":"血液循环模型","py":"xuèyè xúnhuán móxíng","en":"Circulation model"}],"do":"“教会另一个人”：孩子从三个问题中选一个（跑步时心脏为什么跳得更快？静脉为什么看起来发蓝？小伤口为什么会自己止血？），用本子上的画两分钟内讲给家人听，不看书；请对方提一个问题，知道就回答，不知道就说“我还不知道，我会在某一课里找答案”，并把问题记下来。","safety":["不要求任何人为了证明什么去划伤自己或跑步；只用图画和语言来讲解。"],"explain":"可以这样说：“今天不讲新东西。需要的我们都学过了：心脏在哪里、做什么；血管有哪几种、在哪里交换；血里有什么、从哪里来。好的检查员不是背下正确的图，而是知道它为什么正确。我们再跟一个红细胞走一遍：肺里的毛细血管，左心，动脉，小腿肌肉里的毛细血管，静脉，右心，再回到肺。只有两个地方发生交换。一边走一边说出每一段是什么血管。”","mis":[{"says":"（在错误的模型里，没发现心脏画在肚子里）","answer":"把拳头放在胸部中间。"},{"says":"（没注意到从大动脉直接指向肌肉的“氧气”箭头）","answer":"薄薄的管壁在哪里？"},{"says":"（接受模型里“蓝色的血”这种说法）","answer":"划破静脉流出来的血是什么颜色？"},{"says":"（接受从心脏出来的“造血”箭头）","answer":"造血的工厂在哪里？"},{"says":"（把两个循环排成轮流进行）","answer":"两个心室是同时收缩的。"}],"dinner":{"q":"想象你是肺里的一个红细胞。给我讲讲你到小腿肌肉再回来的旅程。","listen":"在肺里装上氧气，到心脏，进动脉，到小腿的毛细血管放下氧气、带走废物，再由静脉送回心脏。"},"faith":[]},{"id":"U04.L01","unit":"U04","ar":"التنفس: كيف يدخل الهواء ويخرج؟","zh":"呼吸：空气怎样进出？","point":"空气进入肺，是因为横膈膜和肋间肌使胸腔扩大；它们放松时空气就出来。鼻子和气管是空气的通道，大脑根据身体的需要调节呼吸的快慢。","objectives":[{"zh":"能在新的图上指出：鼻子和嘴、气管、胸廓里的两个肺、肺下面的横膈膜；并能在自己身上指出肺的位置。"},{"zh":"能解释：吸气时横膈膜收缩下降、肋骨抬起，胸腔变大，空气进来；呼气时肌肉放松，胸腔变小，空气出去。肺自己不会吸气。"},{"zh":"能数自己一分钟呼吸几次，观察到运动后变快、休息后恢复，并把这和身体需要更多空气联系起来。"},{"zh":"知道鼻子能温暖、湿润空气并挡住灰尘；空气经过气管，气管分成两条支气管，再在肺里分成越来越细的管子。"},{"zh":"知道大脑会根据身体需要自动调节呼吸快慢；我们可以稍微控制它（憋气、唱歌），但大脑最后会重新接管。","b":true},{"zh":"能做“气球和瓶子”的横膈膜模型，并说出它显示了什么、没显示什么（只有一个肺，没有肋骨，没有气体交换）。","b":true}],"terms":[{"ar":"التنفس","zh":"呼吸","py":"hūxī","en":"Breathing"},{"ar":"الرئتان","zh":"肺","py":"fèi","en":"Lungs"},{"ar":"الحجاب الحاجز","zh":"横膈膜","py":"hénggémó","en":"Diaphragm"},{"ar":"القصبة الهوائية","zh":"气管","py":"qìguǎn","en":"Windpipe (trachea)"},{"ar":"الشهيق والزفير","zh":"吸气与呼气","py":"xīqì yǔ hūqì","en":"Inhale and exhale"}],"do":"“数呼吸，感觉横膈膜”：孩子安静坐两分钟，把手放在肚脐上方，数一分钟内肚子起伏几次（一吸一呼算一次），不要故意改变呼吸，记在“休息”下；观察手随吸气升起、随呼气落下；然后轻跳或快走一分钟，马上坐下再数一分钟，记在“运动后”下。还可以用塑料瓶、气球和橡皮膜做横膈膜模型。","safety":["不比憋气，不故意快速呼吸；感到头晕的孩子要坐下并告诉大人。","有哮喘或呼吸困难的孩子只数休息时的呼吸，运动部分要经允许才参加。","剪开的瓶口要用胶带包好；剪瓶子由大人来做。"],"explain":"可以这样说：“这是你胸腔的里面。胸廓里有两个粉红色、像海绵一样的器官，一边一个，就是肺。两肺之间是心脏，它偏左，所以左肺小一点。肺每分钟充气、放气大约二十次，你根本不用去想。空气从鼻子或嘴进来，用鼻子更好：它能把空气变暖、变湿，用鼻毛和鼻涕挡住灰尘。然后空气经过脖子里的喉咙，进入一根叫气管的管子；摸摸脖子前面，能摸到一圈圈硬硬的环，让它保持张开。到了胸腔，气管分成两条，每个肺一条，再分成越来越细的管子，像一棵倒过来的树。那么是谁让空气动起来的？不是肺，肺里没有能鼓起它的肌肉。肺下面有一块像圆顶一样的宽肌肉，叫横膈膜。它收缩往下拉，肋骨也往上抬，胸腔变大，空气就进来了；它们放松，空气就出去了。”","mis":[{"says":"“肺像风箱一样自己把空气吸进去。”","answer":"肺里没有能让它动的肌肉。是横膈膜和肋间肌让胸腔变大，肺跟着扩张，空气就进来。试试瓶子模型：把下面的橡皮膜往下拉，气球就鼓起来。"},{"says":"“肺能制造氧气。”","answer":"氧气来自外面的空气；肺只是把它送进血液，并不制造它。所以我们不能在水下呼吸。"},{"says":"“吞咽时是小舌头把气道关上。”","answer":"是会厌（喉咙上方的一个小盖子）在吞咽时盖住气管入口；所以边吃边说话的人会“呛到”。"},{"says":"“先呼吸，再心跳，再肌肉动，一个接一个。”","answer":"这些都在同一时刻同时发生；身体是一张网，不是排队。"}],"dinner":{"q":"你现在不用想就在呼吸。是谁把空气吸进来的：是肺，还是别的什么？","listen":"肺下面的横膈膜收缩下降，肋骨抬起，胸腔变大，空气就进来了。肺自己不会吸气。运动后我们呼吸得更快。"},"faith":[]},{"id":"U04.L02","unit":"U04","ar":"الرئتان من الداخل: من الهواء إلى الدم","zh":"肺的里面：从空气到血液","point":"在数亿个很薄的肺泡里，氧气从空气进入血液，二氧化碳从血液进入空气；把氧气送到每一个细胞的是血液，不是肺。","objectives":[{"zh":"知道肺像海绵，是因为里面有数亿个小肺泡，每个肺泡外面都围着毛细血管。"},{"zh":"能解释肺泡里的交换：氧气穿过薄薄的壁从空气进入血液，二氧化碳从血液进入空气，随呼气排出。"},{"zh":"能跟踪氧气：空气→肺泡→血液→心脏→经毛细血管到脚上的肌肉；并能指出“肺直接把氧气送到肌肉”是错的。"},{"zh":"能从实验推断呼出的气里有水（镜子起雾），呼出的空气和吸进的不一样；并说出肺泡图的一个局限。"},{"zh":"知道红细胞靠一种红色物质（血红蛋白）在肺的毛细血管里抓住氧气，在身体的毛细血管里放下它；回到肺的血带着二氧化碳。","b":true},{"zh":"能解释为什么烟雾和大量灰尘有害：它们伤害细小的管道和肺泡，使交换变难；并知道肺泡的总面积非常大，因为交换需要面积。","b":true}],"terms":[{"ar":"الحويصلات الهوائية","zh":"肺泡","py":"fèipào","en":"Alveoli (air sacs)"},{"ar":"تبادل الغازات","zh":"气体交换","py":"qìtǐ jiāohuàn","en":"Gas exchange"},{"ar":"الأكسجين","zh":"氧气","py":"yǎngqì","en":"Oxygen"},{"ar":"ثاني أكسيد الكربون","zh":"二氧化碳","py":"èryǎnghuàtàn","en":"Carbon dioxide"},{"ar":"الهيموغلوبين","zh":"血红蛋白","py":"xuèhóngdànbái","en":"Hemoglobin"}],"do":"“我呼出了什么？镜子和气球”：孩子对着冰凉的镜子轻轻呼气，看到雾气，摸一摸——是水；再用鼻子呼吸后比较雾气多少。然后把气球拉软，吸一口普通的气，把这一口气全部吹进气球并捏住口子，看看一口气有多大。","safety":["没吹起的气球和破气球碎片有窒息危险：不能含在嘴里，破了马上收起来，在大人在场时吹；对乳胶过敏的孩子用纸袋代替。","只吹一口，然后正常呼吸；不连续快速地吹（会头晕），头晕的孩子要坐下。","孩子之间不交换气球和镜子（有口水）；每人用自己的，或用完洗干净。","有哮喘的孩子经允许才吹气球。"],"explain":"可以这样说：“我们走进肺里看看。气管不断分叉、变细，最后是一串串很小很小的袋子，叫肺泡。你的肺里有几亿个肺泡，所以肺像海绵，不是空口袋。每个肺泡外面都包着一张毛细血管网，管壁只有一层细胞。最重要的事就发生在这里：吸进来的空气里氧气多，从身体回来的血里氧气少，于是氧气穿过薄薄的壁进入血液；同时，身体细胞产生的二氧化碳从血液进入肺泡，随着呼气出去。没有管子，也没有泵，只有两层薄壁和两种气体朝两个方向穿过。那氧气怎么到脚上的肌肉呢？不是肺直接送过去，肺和肌肉之间没有管子。氧气是搭着血液走的：从肺泡到毛细血管，到左心，进大动脉，到脚上的毛细血管，再进入肌肉细胞。”","mis":[{"says":"“肺制造并储存氧气。”","answer":"氧气来自外面的空气，肺只是把它送进血液。所以我们不能长时间待在密闭的房间里，也不能在水下呼吸。"},{"says":"“肺直接把氧气送到肌肉。”","answer":"肺和肌肉之间没有管子，氧气搭着血液走：肺泡→毛细血管→心脏→动脉→肌肉里的毛细血管。"},{"says":"“带着二氧化碳的血是蓝色的。”","answer":"永远是暗红色；图上的蓝色只是表示含氧少的血。"},{"says":"“肺泡就像图上那么大。”","answer":"图是放大了几千倍的模型；肺泡用眼睛是看不见的。"}],"dinner":{"q":"空气进了你的肺。氧气是怎样到达你脚上的肌肉的？","listen":"氧气穿过肺泡薄薄的壁进入毛细血管里的血液，再由心脏把血推到脚上。肺不会直接把它送到肌肉。二氧化碳随着呼气出去。"},"faith":[]},{"id":"U04.L03","unit":"U04","ar":"قضية الوحدة: الهواء الذي أتنفسه","zh":"单元项目：我呼吸的空气","point":"气道用黏液、纤毛、咳嗽和喷嚏保护自己；烟雾会破坏这种保护、伤害肺泡，而且会被房间里的每一个人吸进去。","objectives":[{"zh":"能解释咳嗽和打喷嚏是气道里的感受器发起的快速反应，用力把空气推出去，排出刺激物（灰尘、烟、痰）；并知道鼻子用鼻毛和鼻涕挡住灰尘，纤毛把黏液扫出去。"},{"zh":"能检查一个错误的呼吸模型，用前两课学到的知识找出它的五个错误。"},{"zh":"知道烟雾——无论香烟还是水烟——都伤害气道和肺泡，水烟里的水并不能净化烟雾，坐在烟里的人也会吸进去；能说出一个有礼貌地保护自己呼吸的做法。"},{"zh":"能做到打喷嚏和咳嗽的礼仪（用手肘或纸巾挡住，然后洗手），并解释为什么用手肘而不是手掌。"},{"zh":"能在一个情境里联系三个系统：跑步时肌肉需要更多，大脑让呼吸和心跳一起加快；并解释为什么吸烟的人爬楼梯时比别人更喘。","b":true}],"terms":[{"ar":"السعال والعطاس","zh":"咳嗽与打喷嚏","py":"késou yǔ dǎ pēntì","en":"Cough and sneeze"},{"ar":"دفاع مجاري الهواء","zh":"气道防御","py":"qìdào fángyù","en":"Airway defenses"},{"ar":"ضرر الدخان","zh":"烟雾危害","py":"yānwù wēihài","en":"Smoke harm"}],"do":"“检查家里的空气，教会别人打喷嚏的礼仪”：孩子在家里走一圈，在本子上记下哪里空气清新（窗户开着、没有烟），哪里不好（烟、很多灰尘、刺鼻的气味）；选一件这周能有礼貌地改变的事（开窗、请人到外面抽烟、擦灰）；练习把手肘抬到口鼻前打喷嚏，直到成为习惯，再教给兄弟姐妹或朋友；然后用肥皂洗手二十秒。","safety":["孩子不要直接闻胡椒，也不要在脸附近撒；只由老师演示，有哮喘的孩子离远一点。","不为了试验而靠近烟雾；了解烟雾，但不吸它。","对大人提要求要有礼貌、尊重；不责备，不说教。"],"explain":"可以这样说：“今天没有新的科学内容，我们用学过的知识。记得吗？空气从鼻子进来，被加温、加湿、清洁。怎么清洁？鼻子和气道里有黏黏的黏液，粘住灰尘和微生物，还有很细的纤毛——像睫毛，但只有在显微镜下才看得见——像扫帚一样把黏液往外扫，或者扫到喉咙里，我们不知不觉就咽下去了。如果进来的东西太多，比如很多灰尘、烟，或者东西卡在喉咙里，气道壁上的感受器就给大脑发信号，大脑命令呼吸肌：先深吸一口气，喉咙突然关上，再猛地把气推出去，把刺激物赶出来，这就是咳嗽。打喷嚏也一样，只是刺激物在鼻子里。不是你决定的，是大脑在你想到之前就保护了你。咳嗽是保护，生病是因为刺激物。香烟和水烟的烟会让纤毛瘫痪，伤害肺泡，旁边坐着的人也会吸进去。”","mis":[{"says":"“水烟比香烟害处小，因为烟经过了水。”","answer":"水不能把烟里的有害物质过滤掉，而且一次水烟会吸进大量的烟。世界卫生组织说它是有害的。"},{"says":"“咳嗽是一种病，必须止住。”","answer":"咳嗽是保护肺的反应，把刺激物排出去；病是由刺激物引起的，咳嗽是信号也是保护。"},{"says":"“咳嗽或用喷雾的人是不努力或软弱。”","answer":"谁都会生病，哮喘不是缺点，也不传染。我们去帮助，不去嘲笑。"},{"says":"“肺直接把氧气送到肌肉。”","answer":"只能通过血液。"}],"dinner":{"q":"如果有人坐在你旁边抽烟，你会怎么做？为什么打喷嚏要用手肘而不是手掌？","listen":"烟雾伤害气道和肺，香烟和水烟都一样，坐在旁边的人也会吸进去，所以要有礼貌地离开。用手肘打喷嚏，是因为手掌会碰到别人和东西，把微生物传过去，之后还要洗手。"},"faith":[]},{"id":"U05.L01","unit":"U05","ar":"الخلية: اللبنة الحية التي لا تراها","zh":"细胞：看不见的活砖块","point":"你身体的每一部分都是由非常小、只有用显微镜才能看到的细胞构成的。每个细胞都有细胞膜和细胞质，大多数有细胞核；细胞各有分工，形状适合它们的工作，大多数细胞里有线粒体，从食物中释放能量。","objectives":[{"zh":"知道自己的身体由数万亿个很小的细胞构成，眼睛看不见，用显微镜才能看见，而且所有生物都由细胞构成。"},{"zh":"能在细胞图上说出：细胞膜（包住细胞，控制什么进出）、细胞质（发生各种反应的胶状液体）、细胞核（保存建造和工作的指令）。"},{"zh":"知道细胞各有分工：红细胞是运氧气的圆盘，肌肉细胞长长的会收缩，神经细胞有分支能传信号，皮肤细胞扁平能覆盖；形状适合工作。"},{"zh":"明白细胞图是放大、简化的模型，能说出它的一个局限；并知道细胞最早是用显微镜看到的。"},{"zh":"知道细胞里有叫线粒体的小东西，产生细胞需要的大部分能量，工作越多的细胞（如肌肉）线粒体越多。","b":true},{"zh":"能把层次联系起来：相似的细胞组成组织，组织组成器官，器官组成系统，系统组成身体。","b":true}],"terms":[{"ar":"الخلية","zh":"细胞","py":"xìbāo","en":"Cell"},{"ar":"غشاء الخلية","zh":"细胞膜","py":"xìbāomó","en":"Cell membrane"},{"ar":"السيتوبلازم","zh":"细胞质","py":"xìbāozhì","en":"Cytoplasm"},{"ar":"النواة","zh":"细胞核","py":"xìbāohé","en":"Nucleus"},{"ar":"الميتوكوندريا","zh":"线粒体","py":"xiànlìtǐ","en":"Mitochondria"},{"ar":"النسيج والعضو","zh":"组织与器官","py":"zǔzhī yǔ qìguān","en":"Tissue and organ"}],"do":"“做一个细胞，看看胡克的小格子”：孩子在密封袋里装半袋果冻（细胞质），中间放一颗葡萄（细胞核），撒几粒米（线粒体），拉好拉链（袋子就是细胞膜），轻轻按一按：膜保持形状，不让里面的东西出来；在模型下写：我的模型显示了什么、没显示什么。可选：在大人指导下用显微镜看一片很薄的洋葱皮。","safety":["袋子保持封好，不用牙齿咬开；摸过的果冻不要吃。","显微镜和洋葱皮要在大人监督下使用；不要通过镜头看太阳或强光。","接触鸡蛋后要洗手。","葡萄和米粒要远离五岁以下的弟弟妹妹（有窒息危险）。"],"explain":"可以这样说：“我们一起放大看看：先是你的手指，再是它的皮肤，然后是眼睛看不到的东西：一个个紧挨着的小格子，每一个都是活的，这就是细胞。你身体的每一部分——皮肤、肌肉、骨头、大脑——都是由细胞构成的，就像房子用砖砌成，只不过这里每一块砖都是活的：会吃、会呼吸、会工作。你身体里有几万亿个细胞。所有生物——蚂蚁、树、大象——也都由细胞构成。放大一个细胞看：外面有一层薄薄的细胞膜，保护它，并控制氧气、养分进来，废物出去。里面是胶状的细胞质，细胞的工作都在这里进行。中间有一个大一点的细胞核，里面是告诉细胞做什么的指令，像一本食谱，而不是会思考的大脑。细胞都一样吗？不一样。红细胞是凹下去的圆盘，适合运氧气、钻过毛细血管；肌肉细胞长长的，会收缩；神经细胞有很多分支，能传信号。”","mis":[{"says":"“所有细胞都一样。”","answer":"细胞的形状和功能各有分工：红细胞是圆盘，肌肉细胞长长的，神经细胞有分支，皮肤细胞扁平。形状适合工作。"},{"says":"“细胞就像图上那么大、那么彩色。”","answer":"图是放大并上了色的模型；细胞用眼睛看不见，它的各部分大多是透明的。"},{"says":"“身体是连成一整块的，像面团；细胞只在血液里。”","answer":"身体每一部分——皮肤、肌肉、骨头、大脑——都由细胞构成。我们见过血细胞是因为它们单独漂着；其他部位的细胞是紧挨在一起的。"},{"says":"“细胞核是会思考的小大脑。”","answer":"细胞核里写着告诉细胞做什么的指令；它不像大脑那样思考或做决定。比作食谱比比作大脑更贴切。"}],"dinner":{"q":"你的身体是由什么构成的？你所有的细胞都一样吗？","listen":"由几万亿个要用显微镜才能看到的小细胞构成。它们各有分工，每种细胞的形状适合它的工作：红细胞是运氧气的圆盘，神经细胞有分支能传递信息，肌肉细胞长长的会收缩。"},"faith":[]},{"id":"U05.L02","unit":"U05","ar":"الطاقة: لماذا تحتاج الخلية الأكسجين؟","zh":"能量：细胞为什么需要氧气？","point":"细胞用氧气从糖里释放能量，同时产生二氧化碳、水和热量；所以我们要吃饭、要呼吸，所以跑步时呼吸和心跳会加快，身体会变暖。","objectives":[{"zh":"能解释细胞用氧气从食物（糖）中释放能量，同时产生二氧化碳和水，这就是我们需要呼吸的原因。"},{"zh":"能把几个单元联系起来：食物提供糖，肺提供氧气，血液把它们送到细胞，细胞释放能量，产生的二氧化碳随血液回到肺。"},{"zh":"能解释跑步时呼吸和心跳为什么一起加快：工作的细胞需要更多氧气和糖，也产生更多二氧化碳；身体为什么变暖：一部分能量变成了热。"},{"zh":"明白“缓慢燃烧”这个比喻有局限：没有火焰，没有烟，能量是一小步一小步地释放的。"},{"zh":"知道能量释放大多发生在线粒体里，能量储存在一种小分子（ATP）中，细胞用它来收缩、建造和传递信号。","b":true},{"zh":"能解释身体即使在睡觉时也不停地工作（心跳、呼吸、大脑、生长），所以一直需要能量，运动会增加需要。","b":true}],"terms":[{"ar":"الطاقة","zh":"能量","py":"néngliàng","en":"Energy"},{"ar":"السكر (الجلوكوز)","zh":"葡萄糖","py":"pútáotáng","en":"Glucose (sugar)"},{"ar":"التنفس الخلوي","zh":"细胞呼吸","py":"xìbāo hūxī","en":"Cellular respiration"},{"ar":"حرارة الجسم","zh":"体温","py":"tǐwēn","en":"Body heat"}],"do":"“蜡烛需要空气，我工作时会变暖”：由大人点燃蜡烛，用杯子倒扣罩住，孩子在一米外数几秒熄灭——少了什么？为什么还有蜡就灭了？孩子坐着摸摸额头和手心，再原地跳或快走两分钟，再摸一次：更暖了吗？出汗了吗？再数呼吸和脉搏；坐三分钟后再感觉一次。","safety":["跳跃或快走：已知有心脏或呼吸问题的孩子，经家长同意只做坐着的部分；用哮喘喷雾的孩子要带在身边；天气炎热或长时间空腹后不做。","如果感到头晕、疼痛或喘不过气，马上停下坐好，并告诉大人。孩子在运动中晕倒、胸痛或心跳得很厉害，要停下并去看医生。","蜡烛和杯子只由大人操作；孩子离一米远；远离头发、纸和窗帘；观察后马上熄灭。","不故意快速呼吸，不憋气；头晕的孩子要坐下。","不量体内温度，也不比较孩子之间的数字。"],"explain":"可以这样说：“你做的每件事——走路、思考、长大，连睡觉——都需要能量。能量从哪里来？从食物。面包、米饭、水果在身体里变成一种简单的糖，叫葡萄糖，血液把它送到每个细胞，这是细胞的燃料。可是只有燃料还不够，就像蜡烛只有蜡不够一样。细胞把糖和氧气放在一起，从糖里释放出能量，同时产生二氧化碳和水。这叫细胞呼吸：糖＋氧气→能量＋二氧化碳＋水。所以你要呼吸：不是因为空气里有能量，而是因为氧气能把食物里的能量释放出来；所以你要呼出二氧化碳：那是释放能量后剩下的。这有点像蜡烛燃烧，但细胞里没有火焰也没有烟，能量是一小步一小步出来的，一部分变成热，这就是你身体的温暖。跑步时细胞要更多能量，所以呼吸、心跳都加快，身体也更热。”","mis":[{"says":"“氧气就是能量，我们呼吸是为了从空气里拿能量。”","answer":"能量在食物里，不在空气里；氧气是在细胞里把糖的能量释放出来的那个东西，就像蜡烛需要空气才能把蜡里的能量释放出来。"},{"says":"“细胞里的燃烧就是我们身体里有一团小火。”","answer":"这个比喻有局限：没有火焰，没有烟；能量是一小步一小步平静地释放的，一部分变成温和的热，就是你身体的温暖。"},{"says":"“肺直接把氧气送到肌肉。”","answer":"只能通过血液；血液和呼吸单元都学过。"},{"says":"“先呼吸，然后心跳加快，然后细胞工作，一个接一个。”","answer":"这些都是同时发生的：细胞提出需要，大脑同时命令肺和心脏。"}],"dinner":{"q":"我们到底为什么需要氧气？跑步时为什么会变暖？","listen":"细胞用氧气从糖里释放能量，产生二氧化碳和水，一部分能量变成热。氧气本身不是能量。"},"faith":[]},{"id":"U05.L03","unit":"U05","ar":"قضية الوحدة: من لقمة الخبز إلى القفزة","zh":"单元项目：从一口面包到一次跳跃","point":"一口面包在血液里变成糖，空气在肺里提供氧气，心脏把两者送到肌肉细胞；细胞释放能量，肌肉收缩拉动骨头，于是你跳起来；二氧化碳随呼气回到外面——五个系统在一条链上一起工作。","objectives":[{"zh":"能沿着一条链跟踪一口面包直到一次跳跃：消化提供糖→血液运送→肺提供氧气→心脏把两者推到毛细血管→肌肉细胞释放能量→肌肉收缩，在关节处拉动骨头→二氧化碳回来，随呼气排出。"},{"zh":"能检查一个错误的旅程模型，找出五个错误并说明理由改正。"},{"zh":"能用一个原因解释同一情境里的三个现象（喘气、心跳快、身体变暖）：工作的细胞需要更多能量。"},{"zh":"能用自己的话和图画把这段旅程讲给没学过的人（弟弟妹妹或家人）听，并用检查表评价自己讲得怎样。"},{"zh":"能推断链条上某一站出问题时会怎样（没有食物、空气少、心跳慢、肌肉不能收缩）。","b":true},{"zh":"明白身体会储存一些燃料，所以两餐之间不会倒下，而且所有站点是同时工作的，不是一个接一个。","b":true}],"terms":[{"ar":"سلسلة الطاقة","zh":"能量链","py":"néngliàng liàn","en":"Energy chain"},{"ar":"محطة","zh":"站","py":"zhàn","en":"Station"}],"do":"“在我的身体上画出旅程，并教给别人”：孩子在纸上画出自己身体的轮廓（或用课本的人体图），把七个站点贴在正确位置：嘴和肠、肺、心脏、腿上的毛细血管、肌肉细胞、关节（膝盖）、再回到肺呼气；用一种颜色画出糖的路线（嘴→肠→血液→心脏→腿上的毛细血管），用另一种颜色画氧气的路线；然后讲给家人听。","safety":["不在狭小的地方真的跳；课上的跳跃是象征性的，或者在安全的院子里。","不比较孩子们画得好不好看；标准是科学上对不对。"],"explain":"可以这样说：“第一站：一口面包。你嚼碎它，咽到胃里，再到肠子里。在那里面包被分解成很小很小的东西，其中有糖（葡萄糖），它穿过肠壁进入血液。大约一小时后，面包就变成了你血里的糖，这是燃料。第二站：呼吸。同时你在呼吸，空气到了肺泡，氧气进入毛细血管，搭上红细胞。现在血里有了细胞需要的两样东西：糖和氧气。第三站：心脏。左心把装着糖和氧气的血推进主动脉，再进越来越细的动脉，一直到大腿肌肉细胞之间的毛细血管，从肺到腿不到一分钟。然后肌肉细胞用氧气从糖里释放能量，肌肉收缩，拉动骨头，你就跳起来了；产生的二氧化碳随血回到肺，被你呼出去。这些站点不是一个等一个，而是同时在工作。”","mis":[{"says":"“能量来自空气。”","answer":"来自食物；空气提供的是释放能量的氧气。"},{"says":"“肺把空气送到肌肉。”","answer":"是血液运送氧气；肺以外没有空气。"},{"says":"“肌肉推骨头。”","answer":"肌肉只会拉，所以成对工作。"},{"says":"“各站像火车一样一个接一个地工作。”","answer":"它们同时不停地工作；跳跃不用等消化完，因为身体储存着燃料。"},{"says":"“今天不吃饭，我就完全不能动了。”","answer":"身体储存了一些燃料，所以还能活动几个小时，但会越来越没力气；燃料每天都需要。"}],"dinner":{"q":"早上你吃了一口面包，中午你跳了起来。在这一口面包和这一跳之间发生了什么？","listen":"消化提供糖，血液运送它，肺提供氧气，心脏把两者推到肌肉，细胞释放能量，肌肉收缩拉动骨头。然后二氧化碳随呼气出去。"},"faith":[]},{"id":"U06.L01","unit":"U06","ar":"الفم: أول محطة في الطريق","zh":"嘴巴：消化之路的第一站","point":"消化从嘴里开始：不同形状的牙齿负责切、撕、磨，唾液把食物弄湿，并开始把淀粉分解成糖；舌头把食团往后推去吞咽，同时会厌关上空气的通道。","objectives":[{"zh":"能说出四种牙齿（切牙、尖牙、前磨牙、磨牙），并把每种牙的形状和工作联系起来：切断、撕裂、压碎、磨碎。"},{"zh":"能解释消化从嘴里开始：咀嚼让食物变小，唾液把它弄湿，并开始把淀粉变成糖。"},{"zh":"能描述吞咽：舌头把食团推向后方，会厌关上空气的通道，所以食团进入食道而不是气管。"},{"zh":"明白牙齿为什么会蛀：黏黏的牙菌斑里的细菌用糖制造酸，酸溶解牙釉质里的矿物质；只要给牙齿时间，唾液和氟化物能把矿物质补回来。"},{"zh":"能解释为什么两餐之间频繁吃糖比吃糖的量更伤牙，为什么晚上刷牙后再吃糖更危险：睡觉时唾液少，修复也少。","b":true},{"zh":"知道乳牙（20颗）会脱落，被恒牙（最后32颗）代替；乳牙对保住恒牙的位置、咀嚼和说话都很重要。","b":true}],"terms":[{"ar":"الهضم","zh":"消化","py":"xiāohuà","en":"Digestion"},{"ar":"اللعاب","zh":"唾液","py":"tuòyè","en":"Saliva"},{"ar":"المينا","zh":"牙釉质","py":"yáyòuzhì","en":"Enamel"},{"ar":"لسان المزمار","zh":"会厌","py":"huìyàn","en":"Epiglottis"}],"do":"“变甜的面包和醋里的蛋壳”：孩子把一小块面包整整嚼两分钟不咽下，注意味道有什么变化；对着镜子数牙齿，找出四种形状（前面扁平的切牙、尖尖的尖牙、后面两个尖的前磨牙、宽宽的磨牙；前磨牙10到12岁才长全，没找全没关系）；用切牙咬苹果，再试着用切牙磨碎它；在大人监督下把蛋壳泡在醋里，观察酸怎样溶解它，就像酸溶解牙釉质。","safety":["蛋壳和醋要在大人监督下使用，之后洗手；醋不能喝。","镜子和手指不要伸进嘴里太深。","对面包或鸡蛋过敏的孩子观看同学做。","有松动牙齿的孩子不要用它咬苹果，用另一边咬或者观看。"],"explain":"可以这样说：“上个单元我们说过要弄清楚面包怎样变成糖，旅程就从你嘴里开始。第一批工人是牙齿，它们不都一样：前面扁平的切牙像刀，把食物切断；旁边尖尖的尖牙抓住、撕开；后面有两个尖的前磨牙把食物压碎；最后面宽宽的磨牙像磨盘一样把食物磨碎。不同的工作需要不同的工具。第二个工人你看不见：唾液。三对腺体往嘴里分泌唾液，一天大约一升，还没吃东西就开始了，闻到饭香嘴里就流口水。唾液把食物弄湿，让它好滑下去，里面还有一种物质能把面包里的淀粉变成糖，所以面包嚼久了会变甜。这就是消化：把食物分解得越来越小，它从嘴里就开始了。吞咽时舌头把食团往后推，会厌盖住气管，所以边吃边笑容易呛到。蛀牙不是糖直接弄坏的，是细菌吃糖产生酸，酸溶解了牙釉质。”","mis":[{"says":"“食物原样进入胃里，消化都在胃里。”","answer":"消化从嘴里开始：牙齿把食物变小，唾液开始分解淀粉；到胃里的是湿润的糊，不是一整口。"},{"says":"“糖本身会把牙弄坏。”","answer":"糖是细菌的食物，是细菌制造的酸溶解了牙釉质；所以刷牙去除细菌，氟化物帮助修复。"},{"says":"“乳牙反正要掉，刷不刷无所谓。”","answer":"乳牙要用好几年，用来咀嚼、说话，并保住恒牙的位置；蛀了会疼，还会伤害下面的恒牙。"},{"says":"“食物和空气在喉咙里走同一条路。”","answer":"它们在会厌处分开：吞咽的那一刻，会厌关上空气的通道；所以边吞边笑会呛到。"}],"dinner":{"q":"为什么面包嚼久了会有一点甜？真正让牙齿蛀坏的是什么？","listen":"唾液开始把淀粉变成糖。蛀牙是细菌用糖制造酸，酸溶解了牙釉质；糖本身不会把牙弄坏。"},"faith":[]},{"id":"U06.L02","unit":"U06","ar":"الطريق: المريء والمعدة","zh":"通道：食道和胃","point":"消化管的肌肉用一波一波的收缩（蠕动）推动食物，而不是靠重力；胃是一个肌肉袋，把食物和胃酸、消化液混合，然后慢慢放出去，黏液保护着它；饱的信号来得晚，所以慢慢吃更好。","objectives":[{"zh":"能解释食物不是靠重力掉下去的，而是消化管的肌肉一波接一波地收缩把它推下去（蠕动），所以倒着也能吞咽。"},{"zh":"能描述胃是一个肌肉袋，把食物和胃酸、消化液混合，开始分解蛋白质，把食物变成稠稠的糊，再慢慢放进肠子。"},{"zh":"能解释胃为什么不会消化自己：有一层黏液保护胃壁，胃壁细胞也不断更新。"},{"zh":"明白饱的信号要过几分钟才到达大脑，所以吃得快的人在感觉到饱之前已经吃多了；慢慢吃、不吃到撑，适合自己的身体。"},{"zh":"知道胃有两道肌肉“阀门”守着：上面的一道防止胃酸回到食道，下面的一道把食物一小股一小股地放进肠子。","b":true},{"zh":"了解我们是怎样知道胃里发生了什么的：长期观察一个胃上有“窗口”的人（博蒙特，1822年），以及这个故事里的伦理教训。","b":true}],"terms":[{"ar":"الحركة الدودية","zh":"蠕动","py":"rúdòng","en":"Peristalsis"},{"ar":"المعدة","zh":"胃","py":"wèi","en":"Stomach"},{"ar":"حمض المعدة","zh":"胃酸","py":"wèisuān","en":"Stomach acid"},{"ar":"الشبع","zh":"饱足感","py":"bǎozúgǎn","en":"Fullness (satiety)"}],"do":"“倒着吞咽，做一个袋子里的胃”：在大人陪同下，孩子身体前倾、头低于胃（比如在沙发上头稍微垂下），用吸管喝一小口水——水到了吗？说明什么？把小球放进袜子里，用手指在后面一节一节地挤，直到它从另一头出来——这就是蠕动；再把袜子倒过来试。最后把两块饼干和一点水放进密封袋，用手揉一分钟，像胃一样混合。","safety":["低头喝水必须有大人在场：只喝一小口，然后坐直；不要重复，咳嗽、感冒或吞咽困难的孩子不做。","不要整个倒立，也不要手倒立；稍微前倾就够了，头晕的孩子要坐下。","如果呛到：坐直并咳嗽。如果咳不出、说不出话或无法呼吸，这是气道堵塞，需要大人立即急救。","醋不能喝；实验后袋子扔掉，并洗手。","不比较孩子们的肚子和大小。"],"explain":"可以这样说：“你把一口饭咽下去，它进入食道：一根大约一拃半长的肌肉管子，在气管后面。注意：食物不是掉下去的。管壁是肌肉，食物后面的肌肉收缩把它往前挤，前面的肌肉放松让路，然后下一段、再下一段，像一道波浪往前走，这叫蠕动。所以弯着腰也能吞咽，宇航员没有重力也能吃饭。它是不随意的，你停不下来，就像停不下心跳。几秒钟后食物到了胃：在肚子左上方、肋骨下面，空的时候像拳头那么大，装满时会撑大。胃壁有三层肌肉，从各个方向揉搓、搅拌，小腺体往里分泌很强的酸和消化液。酸帮助分解蛋白质（肉、蛋、豆类），还能杀死很多随食物进来的微生物。几个小时后，吃下去的东西变成稠稠的糊。酸那么强，为什么胃不消化自己？因为胃壁上有一层黏液保护它。还有，饱的感觉要过几分钟才到大脑，所以要慢慢吃。”","mis":[{"says":"“食物像掉进管子一样靠重力掉进胃里。”","answer":"是肌肉波推动它；所以倒着也能吞，宇航员没有重力也能吃饭。"},{"says":"“什么都是胃消化的，肠子只是装废物的管子。”","answer":"胃只是搅拌并开始分解蛋白质；大部分消化和吸收在小肠里，后面第二课会讲。"},{"says":"“胃空着的时候会把自己溶化。”","answer":"无论空的还是满的，黏液都保护着它；空肚子咕咕叫是肌肉的波动，不是在溶化。"},{"says":"“胃一满我马上就知道自己饱了。”","answer":"信号要晚几分钟到；所以吃得快的人在感觉到饱之前已经吃多了。"}],"dinner":{"q":"你倒着身子能吞咽吗？胃为什么不会消化自己？","listen":"能，因为是食道的肌肉一波一波地推动食物，不是重力。有一层黏液保护着胃壁。如果问为什么要慢慢吃：因为饱的信号要晚几分钟才到大脑。"},"faith":[]},{"id":"U06.L03","unit":"U06","ar":"الأعضاء المساعدة: الكبد والبنكرياس والمرارة","zh":"辅助器官：肝脏、胰腺和胆囊","point":"有三个器官，食物不经过它们，却制造着消化离不开的东西：胰腺分泌能分解三类营养的消化液，肝脏制造把脂肪分散开的胆汁，胆囊储存胆汁；从肠子来的血液先经过肝脏，肝脏储存糖并处理进入血液的东西。","objectives":[{"zh":"能指出肝脏（腹部右上方、肋骨下面）、胰腺（胃的后面）和胆囊（肝脏下面）的位置，并知道食物不经过它们，它们通过管道把消化液送进肠子。"},{"zh":"能解释胰腺制造的消化液含有能分解三类营养（淀粉、蛋白质、脂肪）的物质，通过一根管子到达小肠。"},{"zh":"能解释肝脏制造胆汁，把脂肪分散成小油滴（就像肥皂和油），胆囊储存胆汁并在吃饭时放出来。"},{"zh":"明白从肠子来的血液先经过肝脏，肝脏把多余的糖储存起来，在两餐之间释放，并处理进入血液的东西——所以血糖不会用完，也不能在没有家长的情况下自己吃药。"},{"zh":"知道胰腺还会向血液发出一种“信号”（激素），控制糖进入细胞；肝脏是体内最大的器官，有几百种工作，还能再生。","b":true},{"zh":"了解克洛德·贝尔纳（1849–1855）是怎样发现肝脏能制造糖而不只是让糖通过：他测量进出肝脏的血液里的糖，即使动物没有吃糖也是这样，后来又做了其他实验。","b":true}],"terms":[{"ar":"الكبد","zh":"肝脏","py":"gānzàng","en":"Liver"},{"ar":"البنكرياس","zh":"胰腺","py":"yíxiàn","en":"Pancreas"},{"ar":"الصفراء","zh":"胆汁","py":"dǎnzhī","en":"Bile"},{"ar":"المرارة","zh":"胆囊","py":"dǎnnáng","en":"Gallbladder"}],"do":"“肥皂和油：胆汁做什么？肝脏的仓库”：孩子在两个瓶子里各装水和一点油，摇一摇等半分钟，看油怎样了；只在一个瓶子里加一滴洗洁精，再摇两个瓶子，比较哪个瓶子里的小油滴分散得更久——肥皂代表胆汁；油是消失了还是只是被打散了？可选：把海绵浸在有颜色的水里（一顿饭），再在几分钟里一点一点挤出来，像肝脏在两餐之间放出糖。","safety":["洗洁精不能喝，也不要碰到眼睛；做完洗手。","指位置时不要用力按肚子。","如果孩子或亲人有糖尿病或肝病，热情地回应他的问题，但不谈医疗细节。"],"explain":"可以这样说：“胃把食物一股一股地送进小肠的开头。在头一米的地方，有三个食物从来不进去的器官，往食物上倒进改变一切的东西。肝脏是你身体里最大的器官，在肚子右上方肋骨下面，下面有一个小袋子叫胆囊；胃的后面有一个长长的软软的器官，叫胰腺。它们通过细管子把消化液送进肠子，所以叫辅助器官：食物不经过它们，但没有它们，消化就完成不了。胃液只开始分解蛋白质，唾液只开始分解淀粉，而胰液什么都能分解：淀粉、蛋白质、脂肪，还能中和胃酸，不让它烧伤肠子。肝脏制造胆汁，胆汁像肥皂一样把大油滴打散成小油滴，方便胰液去分解；胆囊平时把胆汁存起来，吃饭时再放出来。从肠子来的血先流过肝脏，肝脏把多余的糖存起来，饭与饭之间再放出来。”","mis":[{"says":"“食物要经过肝脏去清洗。”","answer":"食物从不进入肝脏；经过肝脏的是从肠子来的血液，肝脏通过管子把胆汁送进肠子。"},{"says":"“肝脏像茶叶过滤网一样挡住脏东西。”","answer":"肝脏是用化学方法处理：分解有害的东西、把它转化，并储存有用的东西；它不是一张有洞的网。"},{"says":"“我两个小时不吃东西，血里的糖就会用完。”","answer":"肝脏在饭后储存糖、在两餐之间释放；储存少了时它会用别的物质制造新的糖，身体也会用脂肪，所以健康的人即使饿得久，血糖也不会用完。饿是提醒吃饭的信号，不是危险。"},{"says":"“胆汁像胃酸消化蛋白质一样消化脂肪。”","answer":"胆汁只是把脂肪打散（增加表面）；真正分解它的是胰液。"}],"dinner":{"q":"食物不经过肝脏和胰腺。那它们在消化中做什么？","listen":"胰腺往肠子里倒进能分解淀粉、蛋白质和脂肪的消化液。肝脏制造打散脂肪的胆汁，胆囊储存它。肝脏还储存多余的糖，在两餐之间释放。"},"faith":[]},{"id":"U06.L04","unit":"U06","ar":"الامتصاص ونهاية الطريق","zh":"吸收和道路的尽头","point":"吸收发生在小肠：消化好的营养穿过布满几百万个绒毛的薄壁进入血液；然后大肠吸收水分，把剩下的变成粪便排出。","objectives":[{"zh":"能解释吸收发生在小肠：小的颗粒（糖、氨基酸、脂肪的小部分）穿过它的薄壁进入毛细血管里的血液。"},{"zh":"能解释小肠为什么很长，内壁布满几百万个突起（绒毛）：是为了增加营养穿过的表面积，就像肺里的肺泡。"},{"zh":"能描述大肠的工作：从剩下的东西里吸收水分，把其余的变成粪便，储存在直肠里直到排出；排出的是没有消化的东西、水、微生物和脱落的细胞。"},{"zh":"能把喝水、膳食纤维和运动与排便顺畅、规律联系起来，并知道身体提醒时及时去厕所、之后保持清洁，是爱护身体。"},{"zh":"知道从肠子来的血先经过肝脏，脂肪则走另一条路（淋巴管）再进入血液。","b":true},{"zh":"了解人们怎样测量一个看不见的表面（皱褶、绒毛和更细的突起），以及为什么随着工具改进，这个数字也变了。","b":true}],"terms":[{"ar":"الامتصاص","zh":"吸收","py":"xīshōu","en":"Absorption"},{"ar":"الأمعاء الدقيقة","zh":"小肠","py":"xiǎocháng","en":"Small intestine"},{"ar":"الخملات","zh":"绒毛","py":"róngmáo","en":"Villi"},{"ar":"الأمعاء الغليظة","zh":"大肠","py":"dàcháng","en":"Large intestine"}],"do":"“毛巾和纸，和我肠子一样长的线”：孩子把一张纸和一条毛巾并排放，近看毛巾表面有许多小线圈——一样大小，哪个表面实际更大？在两者上滴同样多的水，哪个吸得更快更多？这就是绒毛的道理。再用线量自己的身高，然后拉开5米长的线：这大约是成年人小肠最长的长度，是你身高的几倍？最后把线绕成一团，看它怎样装进肚子里。","safety":["不要把线绕在脖子或手指上。","不在全班面前问孩子上厕所的习惯；谈论身体要平和、一般化。","实验后洗手。"],"explain":"可以这样说：“食物从胃里出来，在小肠开头被倒进了胰液和胆汁，现在它在小肠里了：一根像手指一样细、却很长很长的管子，成年人有3到5米，是你身高的两到四倍，像水管一样盘在肚子里。叫'小'肠是因为它细，不是因为它短。在这里，几个小时里消化完成了：淀粉变成了糖，蛋白质变成了小块，脂肪变成了更小的部分，一切都准备好穿过去了。穿过去就是吸收，这是食物变成你身体一部分的时刻。小肠壁非常薄，后面紧挨着管壁很薄的毛细血管，就像在肺里看到的那样，糖和小颗粒穿过管壁进入血液。小肠里面还布满了几百万个小突起，叫绒毛，让表面积变得很大。早上吃的那口饭，现在已经变成你血里的糖了。剩下的东西到大肠，大肠吸收水分，把其余的变成粪便排出去。”","mis":[{"says":"“肠子只是装废物的管子。”","answer":"小肠是消化和吸收的中心；食物在那里变成你身体的一部分。"},{"says":"“我吃的所有东西都变成血和肉，粪便是吃多了的食物。”","answer":"被吸收的变成你的一部分；排出来的是没有消化的东西（纤维）、水、微生物和肠壁脱落的细胞。"},{"says":"“肠子很短，因为肚子很小。”","answer":"肠子非常长，像水管装在箱子里一样盘起来；长是为了表面积。"},{"says":"“憋着不去厕所没关系。”","answer":"大肠会继续吸收水分，粪便变干变硬，更难排出；及时去厕所是爱护身体。"}],"dinner":{"q":"你的小肠为什么那么长、盘成一团？最后排出来的是什么？","listen":"为了增大营养进入血液的表面积，肠壁上还布满了几百万个绒毛。大肠吸收水分，排出来的是没有消化的东西、水、微生物和脱落的细胞。"},"faith":[]},{"id":"U06.L05","unit":"U06","ar":"سكان الأمعاء، وقضية الوحدة: كيف صار الخبز سكراً؟","zh":"肠道居民和单元项目：面包是怎样变成糖的？","point":"大肠里住着数万亿个有益的微生物，它们分解膳食纤维、制造维生素、守住地盘；植物性食物喂养它们，过多的糖和不必要的抗生素会伤害它们。面包沿着整条路变成了糖：唾液、搅拌、胰液、绒毛、肝脏、细胞。","objectives":[{"zh":"知道大肠里有数万亿个微生物（细菌等）和我们和平相处，大多数是有益的，是从出生起就获得的。"},{"zh":"能解释它们做什么：分解我们消化不了的纤维，制造维生素（包括维生素K），占住地方，让有害微生物找不到落脚处。"},{"zh":"能把食物和肠道居民联系起来：蔬菜、水果和全谷物里的纤维喂养它们，过多的糖和加工食品会减少它们的种类；抗生素会把有益的和有害的一起杀死，所以只能按处方、按医嘱使用。"},{"zh":"能完成单元项目：跟踪面包从嘴（唾液）到胃（搅拌）到小肠（胰液分解淀粉，肠壁完成转化成糖，绒毛把它吸收进血液）到肝脏（储存）再到细胞，并和第五单元联系起来。"},{"zh":"能检查一个有五个错误的消化模型并改正，分清什么进入血液、什么被排出。","b":true},{"zh":"了解我们是怎样知道肠道微生物有益而不只是“乘客”的：把无菌长大的动物和正常动物作比较。","b":true}],"terms":[{"ar":"الميكروب","zh":"微生物","py":"wēishēngwù","en":"Microbe"},{"ar":"سكان الأمعاء (الميكروبيوم)","zh":"肠道微生物组","py":"chángdào wēishēngwù zǔ","en":"Gut microbiome"},{"ar":"الألياف","zh":"膳食纤维","py":"shànshí xiānwéi","en":"Fiber"},{"ar":"المضاد الحيوي","zh":"抗生素","py":"kàngshēngsù","en":"Antibiotic"}],"do":"“喂养我的肠道居民，完成单元项目”：孩子写下昨天吃了什么，在含纤维的食物（蔬菜、带皮水果、全麦面包、燕麦、扁豆、蚕豆、菜豆）前打✓，在甜点、含糖饮料和薯片前画○；数一数昨天喂得更多的是肠道居民还是牙齿上的细菌（不和别的孩子比）；为这一周选一个小改变；最后沿着面包的路线完成整个单元的总结。","safety":["不比较孩子们的食物清单，也不评论他们的身体；改变由孩子自己为自己选择。","不因为这一课而改变任何药物或抗生素；正在吃药的孩子按医生的嘱咐吃完。","不给节食建议，也不推荐任何产品。"],"explain":"可以这样说：“肠道居民，也叫微生物组，就是住在肠子里的一大群微小生物。数量有几万亿个，差不多和你全身细胞一样多，有几百种，大多是细菌。它们不都一样：嘴里有的细菌会产生伤害牙齿的酸，防御单元里还会讲到会让人生病的微生物；可是肠子里的大多数居民从你出生那天起就和你和平相处——最早的一批来自妈妈——你的防御系统把它们当作朋友。它们做三件事：第一，吃你消化不了的东西——蔬菜、水果和全谷物里的纤维——并用它制造营养肠壁的物质；第二，制造维生素，其中一种帮助伤口处的血液凝固；第三，占住地方，有益微生物住着的地方，有害的就找不到位置。所以我们多吃植物性食物喂养它们，不在没必要时吃抗生素。整个单元的答案也在这里：面包在嘴里开始分解，在胃里搅拌，在小肠被胰液分解、变成糖、被绒毛吸收进血液，经过肝脏，最后到达细胞。”","mis":[{"says":"“所有微生物都是病，必须全部杀死。”","answer":"有些会让人生病（防御单元会讲），但你肠子里的大多数是有益的，和你一起生活、保护你；所以没有必要时不用抗生素。"},{"says":"“纤维没有用，因为我们消化不了它。”","answer":"它是肠道居民的食物，它们用它制造营养我们肠子的物质，它还让排便顺畅。"},{"says":"“抗生素能治感冒，我吃到觉得好些就停。”","answer":"感冒是病毒引起的，抗生素对它没有作用；抗生素只能按处方、按规定的剂量和天数吃；没必要时使用，会帮助细菌产生抵抗力。"},{"says":"“面包在胃里变成糖。”","answer":"从嘴里开始，在小肠里靠胰液完成；胃只是搅拌。"}],"dinner":{"q":"你的肠子里有几万亿个微生物。我们要把它们全杀死吗？吃什么能喂养有益的那些？","listen":"不要，大多数是有益的：它们分解纤维、制造维生素、占住地方，让有害的找不到位置。蔬菜、水果和全谷物里的纤维喂养它们。抗生素只能按处方使用。"},"faith":[]},{"id":"U06.L06","unit":"U06","ar":"ماذا آكل؟ الطبق المتوازن","zh":"我吃什么？均衡餐盘","point":"食物里有不同的营养素，每一种在身体里都有作用，没有哪一种食物能提供全部；均衡餐盘的一半是蔬菜和水果，另一半是谷物和蛋白质，配上白开水，添加糖要少吃。","objectives":[{"zh":"知道食物里的营养素各有作用：淀粉和糖提供能量，蛋白质用于建造，脂肪储存能量并构成细胞膜，维生素和矿物质需要的量很少，还有水和膳食纤维。"},{"zh":"能搭配一个均衡餐盘：一半蔬菜和水果，另一半谷物和蛋白质，喝白开水；并知道多样化比某一种“神奇”食物更重要。"},{"zh":"知道添加糖和果汁会让糖很快变多，对儿童的建议是每天添加糖少于六小勺；能和大人一起读饮料的标签。"},{"zh":"能通过林德的实验解释科学家怎样发现食物里缺少某种东西会让人生病：在生病的水手中做公平比较，每两人给一种不同的治疗。"},{"zh":"能解释为什么健康的食物不能只用一种营养素来衡量：身体需要它们一起，缺了一种不能用多吃另一种来弥补；并会读标签上的每日营养素参考值百分比（5%算少，20%算多）。","b":true}],"terms":[{"ar":"المادة الغذائية","zh":"营养素","py":"yíngyǎngsù","en":"Nutrient"},{"ar":"الطبق المتوازن","zh":"均衡餐盘","py":"jūnhéng cānpán","en":"Balanced plate"},{"ar":"السكر المضاف","zh":"添加糖","py":"tiānjiā táng","en":"Added sugar"},{"ar":"ملصق الغذاء","zh":"食品标签","py":"shípǐn biāoqiān","en":"Food label"},{"ar":"نقص الغذاء","zh":"营养缺乏","py":"yíngyǎng quēfá","en":"Nutrient deficiency"}],"do":"“我的饮料里有几勺糖？”：孩子和大人一起读每个饮料盒上的每份分量和糖的克数，用克数除以4，大约就是几小勺糖；在干净的盘子里，在每个盒子旁放上相应勺数的糖（不吃）；和六勺比一比——这是同龄孩子一整天添加糖的上限；然后写下明天午饭想选什么饮料，为什么。","safety":["盘子里的糖只用来看，不吃，实验后倒掉。","饮料盒是空的、干净的，和大人一起读。","不评论别人在家里喝什么；我们学习的是为自己做选择。"],"explain":"可以这样说：“这个单元你跟着一口饭一直走到它进入血液。那么进去的是什么呢？食物里有身体用来工作和成长的不同物质，叫营养素。面包、米饭、面条和水果里的淀粉和糖提供能量，因为身体把它们分解成细胞使用的糖。肉、鱼、蛋、奶、扁豆和蚕豆里的蛋白质用来建造和更新肌肉和器官。油、坚果和鱼里的脂肪储存能量，细胞膜也是用它做的。还有一些营养素身体只需要一点点，但离不开：维生素和矿物质，比如奶和绿叶菜里的钙让骨头结实，肉、鸡、豆子和绿叶菜里的铁。还有水和纤维。没有哪一种食物什么都有，所以要吃得多样。一个简单的办法是均衡餐盘：一半蔬菜和水果，另一半谷物和蛋白质，喝白开水，添加的糖要少。”","mis":[{"says":"“吃得健康就是吃得少，不让自己吃任何甜食。”","answer":"健康饮食是多样、均衡，并留意饥饿和饱足的感觉；甜食可以偶尔适量吃，不要让身体缺少它需要的东西。"},{"says":"“天然果汁和水果一样，想喝多少就喝多少。”","answer":"果汁里有水果全部的糖，却没有纤维，大多数果汁糖很多；整个水果更好，果汁最多一小杯。"},{"says":"“脂肪都有害，不能吃。”","answer":"身体需要脂肪来储存能量、构成细胞膜和保护神经；我们选择坚果、橄榄和鱼这样的来源。"},{"says":"“维生素片可以代替蔬菜水果。”","answer":"获得维生素和矿物质最好的方法是吃多样的食物，食物里还有纤维和水；维生素片是需要时由医生开的，不能代替食物。"}],"dinner":{"q":"均衡餐盘的一半是什么？你读的饮料标签上有几勺糖？","listen":"餐盘的一半是蔬菜和水果，另一半是谷物和蛋白质，喝白开水；标签上的糖是用克表示的，大约每四克一小勺，同龄孩子一整天的添加糖要少于六小勺。"},"faith":[]},{"id":"U07.L01","unit":"U07","ar":"الكليتان: مصفاتان تعيدان ما ينفع","zh":"肾脏：把有用的东西送回去的两个过滤器","point":"肾脏在背部，过滤血液：水和溶在水里的小东西先穿过去，然后大部分又回到血液里（重吸收），只有多余的水和盐，加上废物（最主要的是尿素）变成尿排出去。","objectives":[{"zh":"能指出肾脏的位置：在背部最下面的肋骨下方，脊柱两侧各一个，每个约有拳头大，形状像一颗菜豆。"},{"zh":"能解释过滤：水和溶在水里的小东西（糖、盐、尿素）穿过肾脏的“筛子”，血细胞和大的蛋白质留在血液里。"},{"zh":"能解释重吸收：大部分水、糖和需要的盐回到血液里，所以每天大约150升滤液中只有一两升变成尿；肾脏的工作是保持平衡，而不只是“清洁”。"},{"zh":"能把尿和血液、饮食联系起来：喝下的水被吸收进血液，再由肾脏过滤；尿素是肝脏分解蛋白质产生的，由肾脏排出。"},{"zh":"知道每个肾有大约一百万个肾单位，每个都有一个负责过滤的小球和一根负责送回、排出的小管；休息时肾脏接收心脏泵出血液的大约四分之一。","b":true},{"zh":"能解释我们怎样知道尿来自肾脏（盖伦扎住输尿管的实验），以及尿先过滤再重吸收（韦恩和理查兹：小管前有糖，尿里没有糖），并分清他们看到的和推断的。","b":true}],"terms":[{"ar":"الكلية","zh":"肾脏","py":"shènzàng","en":"Kidney"},{"ar":"الترشيح","zh":"过滤","py":"guòlǜ","en":"Filtration"},{"ar":"إعادة الامتصاص","zh":"重吸收","py":"chóngxīshōu","en":"Reabsorption"},{"ar":"اليوريا","zh":"尿素","py":"niàosù","en":"Urea"},{"ar":"النفرون","zh":"肾单位","py":"shèndānwèi","en":"Nephron"}],"do":"“肾脏的筛子和一百颗豆子”：孩子双手叉腰，拇指转到后面摸到最后一根肋骨——肾脏就在这里深处，握拳就是它的大小；在第一个杯子里混合水、一滴色素和一些米粒（“血液”：水、溶解的小东西和大细胞），慢慢倒进放在第二个杯子上的筛子，看什么穿过去了、什么留下了；再用一百颗豆子演示：大部分“送回血液”，只有一两颗“变成尿”。","safety":["实验的混合物不能喝也不能尝。","色素会染衣服和桌子：杯子下面垫纸。","实验后洗手，豆子和米粒不要放进嘴里或鼻子里。"],"explain":"可以这样说：“双手叉腰，拇指往后、稍微往上，摸到最后一根肋骨。就在拇指下面、你背部深处，是两个肾，脊柱两边各一个，每个大约拳头大，形状像一颗大菜豆。下面的肋骨、肌肉和一层脂肪保护着它们。注意：肾不在肚子前面的下方，那里是另一个器官，下一课会讲。血从心脏来的大动脉进入肾，分成很细很细的毛细血管，绕成像小线团一样的一团。这个线团的壁是很细的筛子：水和溶在水里的小东西——糖、盐、小的废物——能穿过去，血细胞和大的蛋白质不能，留在血里。这叫过滤。可是如果滤过去的都变成尿，几个小时身体就会没水了。所以滤液流过一根长长的小管，大部分水、糖和需要的盐又被送回血液，这叫重吸收。最后只剩多余的水、盐和废物变成尿。肾的工作是保持平衡。”","mis":[{"says":"“肾在我肚子前面的下方。”","answer":"那里是膀胱。肾在背部最下面的肋骨下方，脊柱两侧各一个。"},{"says":"“肾过滤的东西全部变成尿。”","answer":"每天大约过滤150升，约百分之九十九又回到血液；如果全部排出，身体几个小时就会失去水分。"},{"says":"“肾只是把血里的脏东西清洗掉。”","answer":"它先把所有小东西都滤过去，再把有用的送回来，只排出多余的和废物；它的工作是平衡，还有别的工作。"},{"says":"“我喝的水直接流进膀胱。”","answer":"水先在肠子里被吸收进血液，再由肾脏过滤，多出来的部分变成尿流到膀胱。"}],"dinner":{"q":"你的两个肾在哪里？为什么它们过滤的东西不全部变成尿？","listen":"在背部最下面的肋骨下方、脊柱两侧。它们过滤血液，再把大部分水、糖和需要的盐送回血液，所以大约150升里只有一两升排出去。"},"faith":[]},{"id":"U07.L02","unit":"U07","ar":"طريق البول: الحالبان والمثانة والعاصرة","zh":"尿的道路：输尿管、膀胱和括约肌","point":"尿走一条有四个站的路：肾脏制造它，输尿管用肌肉的波动把它推下去，膀胱储存它并在满的时候发出信号，括约肌让出口一直关着，直到我们决定打开；尿的颜色是关于喝水多少的简单信息。","objectives":[{"zh":"能排出尿的路线：肾脏制造，输尿管运送，膀胱储存，尿道排出体外；并能指出膀胱在腹部前面的下方。"},{"zh":"能解释输尿管是两根肌肉管，用一波一波的收缩把尿推到膀胱，所以躺着时尿也能到达膀胱，就像食道推动食物一样。"},{"zh":"能描述膀胱是一个会扩张的肌肉袋，满了会给大脑发信号；括约肌是一圈肌肉，一直关着，直到我们决定；控制排尿是大脑在童年学会的技能。"},{"zh":"会把尿的颜色当作喝水多少的简单线索（浅色：通常喝够了；深色：需要喝水），知道食物、维生素和药物也可能改变颜色，并养成保护膀胱的习惯。"},{"zh":"能解释为什么第一次信号在膀胱远没满的时候就出现，知道长期反复憋尿可能使膀胱肌肉变弱，并知道哪些情况要告诉家长（疼痛或烧灼感、有血、发烧、比平常频繁得多）。","b":true},{"zh":"能比较我们文明中的医生（凯鲁万的伊沙克·以色列里、拉齐）观察尿的方法和今天的检查（先看，再用试纸，再用显微镜）：仔细观察是开始，但单靠观察不够。","b":true}],"terms":[{"ar":"الحالب","zh":"输尿管","py":"shūniàoguǎn","en":"Ureter"},{"ar":"المثانة","zh":"膀胱","py":"pángguāng","en":"Bladder"},{"ar":"العاصرة","zh":"括约肌","py":"kuòyuējī","en":"Sphincter"},{"ar":"الإحليل","zh":"尿道","py":"niàodào","en":"Urethra"}],"do":"“袜子、气球和颜色杯”：孩子把小球放进袜子，把袜子竖起来，在球后面一下一下地挤，球能往上走吗？这就是输尿管用波动推尿。在托盘上把漏斗插进气球口，慢慢倒水，看气球怎样随着装满而撑大——这是膀胱；用夹子或两根手指捏住气球口，拿开漏斗，水会出来吗？这是括约肌，只有决定了才打开。最后用水和色素调出深浅不同的几杯“颜色表”。","safety":["在托盘或水池上方做，不要把气球装得太满，以免在脸附近爆开。","实验不用真的尿；杯子里只是水和色素，不能喝。","对乳胶过敏的孩子用小塑料袋代替气球。","实验后洗手。"],"explain":"可以这样说：“上一课看到肾脏日夜不停地一滴一滴制造尿。尿去哪里呢？每个肾下面有一根细管子，叫输尿管，大人的输尿管差不多有一把学生尺那么长，沿着背部往下，再转到前面，通到肚子下面的一个袋子，叫膀胱。膀胱把尿储存几个小时，然后尿从最后一根管子——尿道——排出体外。四个站：肾制造，输尿管运送，膀胱储存，尿道排出。注意：膀胱不制造尿，只储存。尿在输尿管里是怎么往下走的？你可能以为是自己掉下去的，其实输尿管壁是肌肉，一波接一波地收缩，把尿一小股一小股地推进膀胱，就像食道推动食物一样，所以你躺在床上，甚至倒立，尿也能到膀胱。膀胱满了会给大脑发信号，出口的括约肌一直关着，等你决定去厕所。尿的颜色告诉我们喝水够不够。”","mis":[{"says":"“尿从肾流到膀胱，是因为水往低处流。”","answer":"输尿管是两根肌肉管，用波动把尿推下去，所以躺着时尿也能到膀胱，就像食道推动食物一样。"},{"says":"“每天憋尿好几个小时没关系。”","answer":"第一次信号来得早，所以可以稍微等一等，但长期反复憋尿可能使膀胱肌肉变弱；要在合适的时候去，慢慢排空。"},{"says":"“尿的颜色没有意义。”","answer":"颜色首先随喝水变化：喝够时浅，需要水时深；食物、维生素或药物也可能改变它，所以它是线索，不是结论。"},{"says":"“膀胱制造尿。”","answer":"膀胱只是储存；肾用血液制造尿，输尿管把它送到膀胱。"}],"dinner":{"q":"肾一整天都在制造尿，为什么尿不会一直滴出来？","listen":"膀胱储存尿并会撑大，满了就给大脑发信号；括约肌是一圈肌肉，一直关着，直到我们决定。浅色的尿通常说明喝的水够了。"},"faith":[]},{"id":"U07.L03","unit":"U07","ar":"الماء في جسمي: الميزان والعطش","zh":"我身体里的水：平衡和口渴","point":"水大约占身体重量的一半或更多，通过喝水和食物进入，通过尿、汗、呼气和皮肤排出；大脑保持平衡：让我们感到口渴，并给肾脏发消息，让肾脏把水送回血液或把多余的排出。","objectives":[{"zh":"知道身体重量的一半左右或更多是水（婴儿更多），大部分在细胞里；身体不储存多余的水，而是由肾脏排出，所以每天都需要新的水。"},{"zh":"能平衡水的来路（饮水、食物、身体自己产生的少量水）和去路（尿、汗、呼气、皮肤、粪便），并知道有些排出是看不见的。"},{"zh":"能解释身体怎样保持平衡：缺水时血液变浓，大脑感觉到，就让我们口渴，并给肾发消息，让它们送回更多水（尿少而深）；水多时肾脏把多余的排出。"},{"zh":"能大致估计自己每天需要的量（8岁以下约5杯饮品，更大的孩子约7到8杯，天热和运动时更多），选择白开水而不是含糖饮料，并分几次喝。"},{"zh":"能解释大脑里的感受器测量血液的浓度，释放抗利尿激素，让肾送回更多水；这是一个反馈调节的平衡，让水分保持在一个范围内，而不是完全不变。","b":true},{"zh":"能解释桑托里奥怎样用秤发现身体会失去看不见的水，并设计一个简单的测量，测出随呼气或皮肤流失的水。","b":true}],"terms":[{"ar":"ماء الجسم","zh":"体内水分","py":"tǐnèi shuǐfèn","en":"Body water"},{"ar":"توازن الماء","zh":"水平衡","py":"shuǐ pínghéng","en":"Water balance"},{"ar":"العطش","zh":"口渴","py":"kǒukě","en":"Thirst"},{"ar":"الجفاف","zh":"脱水","py":"tuōshuǐ","en":"Dehydration"},{"ar":"الهرمون المضاد لإدرار البول","zh":"抗利尿激素","py":"kànglìniào jīsù","en":"Antidiuretic hormone (ADH)"}],"do":"“冰镜子、透明袋和一天的记录表”：孩子对着冰凉的镜子或勺子哈一口热气，看到水；把手放进透明塑料袋，用另一只手在手腕处轻轻拢住袋口十分钟（不勒不绑），看袋壁上出现什么；把平常用的杯子倒进量杯，看能装多少毫升；然后用一整天记录每杯水、奶或果汁，以及早、中、晚尿的颜色（对照颜色表）。","safety":["袋子只套在手上，不在手腕处勒紧或绑住，绝对不能套在头上或脸上，不舒服就取下。","勺子从冰箱冷藏室拿，不从冷冻室拿，不要贴在舌头或嘴唇上。","有医生规定饮水的孩子（心脏或肾脏疾病）按医生说的做，不按表格。","不在全班面前比较同学喝了多少水或尿的颜色；表格只给你和家人看。"],"explain":"可以这样说：“如果只称你身体里的水，大约是你体重的一半或更多！婴儿大约四分之三是水，大人大约一半。这些水在哪里？大部分在细胞里，其余在血液和细胞之间。血里的水运送养分，红细胞在里面游，它把废物送到肾，通过出汗给身体降温，还让细胞装满水好好工作。所以我们每天都需要水：身体不会把多余的水存起来备用，而是由肾排掉。想象一架有两个秤盘的天平：一边是进来的水——喝的最多，食物里也有，蔬菜、水果、汤里有很多水，还有细胞释放能量时自己产生的一点；另一边是出去的水——尿最多，还有汗，呼出的每一口气里都有看不见的水汽，皮肤也会悄悄蒸发，粪便里也有。缺水时大脑让你口渴，并通知肾少排尿，尿就会变少变深；水多了，肾就多排一些。”","mis":[{"says":"“水只通过尿排出身体。”","answer":"还通过汗、呼气、不出汗时的皮肤和粪便排出；有些是看不见的。"},{"says":"“果汁和汽水和水一样解渴，甚至更好。”","answer":"它们里面有水，但也有很多糖，伤害牙齿和身体；日常解渴白开水最好。"},{"says":"“身体会储存多余的水，所以一次喝很多就够了。”","answer":"肾在几个小时内就会把多余的水排出，所以每天都需要新的水，要分几次喝。"},{"says":"“身体里的水一直不变。”","answer":"它会稍微上下波动然后回到范围内：少了我们就口渴、肾就送回水，多了肾就排出多余的。"}],"dinner":{"q":"除了尿，水还从你身体的哪里出去？你的身体怎么知道它需要水？","listen":"还通过汗、呼气、皮肤和粪便出去。缺水时大脑感觉到，我们就口渴，肾送回更多水，尿就少而深。白开水比含糖饮料好，要分几次喝。"},"faith":[]},{"id":"U08.L01","unit":"U08","ar":"الدماغ والأعصاب: شبكة الرسائل","zh":"大脑和神经：信息网络","point":"神经系统是一张信息网：感官通过神经和脊髓把信息送到大脑，大脑做决定并命令肌肉；信息是快速的电信号，但需要时间；有些反应是反射，不等大脑做决定。","objectives":[{"zh":"知道神经系统包括颅骨里的大脑、脊柱里的脊髓和通到身体每个部位的神经，并能分清脊髓和骨髓。"},{"zh":"能描述信息的旅程：感官→神经传到大脑→大脑做决定→神经传到肌肉→动作；并知道信息是快速的电信号，但需要时间。"},{"zh":"能解释反射：不经决定的快速反应，保护身体，很多反射由脊髓在大脑感觉到之前就作出回应；能把它和我们自己决定的动作区分开。"},{"zh":"知道大脑主要部分的工作：最大的有褶皱的部分（思考、感觉、我们决定的动作），小脑（平衡和动作协调），脑干（不用想的呼吸和心跳）；并能指出“我们只用了十分之一的大脑”“大脑只用来思考”是错的。"},{"zh":"能描述神经细胞（细胞体、接收信息的短突起、发送信息的长尾巴）和两个细胞之间的小缝隙，知道大脑里大约有860亿个神经细胞，不同神经传递信息的速度不同。","b":true},{"zh":"能解释科学家怎样发现神经里的信息需要时间（亥姆霍兹，1850年）以及神经细胞是彼此分开的（卡哈尔），并设计一个公平比较：简单的接尺子和需要做决定的接尺子。","b":true}],"terms":[{"ar":"الدماغ","zh":"脑","py":"nǎo","en":"Brain"},{"ar":"الحبل الشوكي","zh":"脊髓","py":"jǐsuǐ","en":"Spinal cord"},{"ar":"العصب","zh":"神经","py":"shénjīng","en":"Nerve"},{"ar":"المنعكس","zh":"反射","py":"fǎnshè","en":"Reflex"},{"ar":"الخلية العصبية","zh":"神经元","py":"shénjīngyuán","en":"Neuron"}],"do":"“膝跳和尺子：反射还是决定？”：孩子坐在桌边，腿自由垂下，同伴用手掌边缘轻敲膝盖骨下面的肌腱，看腿怎样动；再试一次并努力不让腿动——做得到吗？然后做接尺子：同伴从上面拿着尺子，零刻度在拇指和食指之间，不打招呼松手，孩子尽快接住；先练两次，再正式量三次。最后试一个“需要做决定”的版本，比较哪种更快。","safety":["敲膝盖要非常轻，用手掌边缘，不用硬东西，只敲两次；受伤或疼痛的膝盖不做。","尺子是松手让它落下，不是扔，要远离脸和眼睛。","不在全班面前比较孩子们的数字；每个孩子只和自己比。","不能坐高桌子的孩子可以坐在椅子上，把一条腿架在另一条腿上。"],"explain":"可以这样说：“你身体里有一张日夜不停的信息网。头上颅骨里是大脑，是指挥中心。从它下面有一根软软的索子沿着背部的椎骨往下走，叫脊髓。从大脑和脊髓分出许多神经，像细线一样分叉，一直通到你身体的每个部位：指尖、全身皮肤、肌肉、心脏和肠子。颅骨保护大脑，椎骨保护脊髓。注意：脊髓不是骨髓，骨髓在骨头里造血，脊髓是传递信息的道路。想象一个球朝你飞来：眼睛看见它，一条信息沿着神经跑到大脑；大脑认出是球，决定：接住它！于是沿着另一条神经给手臂和手的肌肉发命令，手就动了。神经里的信息是很小的电信号，非常快，但不是一瞬间，需要一点时间。有些反应根本不等大脑决定，比如手碰到烫锅马上缩回，这叫反射，是脊髓直接作出的回应，先缩手，后感到疼。”","mis":[{"says":"“骨髓就是脊髓。”","answer":"脊髓是脊柱里传递信息的一束神经；骨髓在骨头里制造血细胞。名字相似，工作不同。"},{"says":"“我们只用了十分之一的大脑，其余的不工作。”","answer":"现代脑部影像显示大脑各部分都在工作，每部分负责自己需要的任务；大脑消耗全身五分之一的能量，任何一部分受伤都会显出影响。"},{"says":"“没有大脑的决定，身体就不会动。”","answer":"反射不经决定就会发生，很多由脊髓在大脑感觉到之前就作出回应：先缩回手，然后才感到疼。"},{"says":"“大脑只用来思考和学习。”","answer":"大脑还管理呼吸、心跳、平衡、感觉和动作，我们睡觉时它也在工作。"},{"says":"“神经里的信息一瞬间就到，不需要任何时间。”","answer":"它非常快，但需要可以测量的时间：在快的神经里，从脚到大脑大约百分之一秒，在慢的神经里更久。"}],"dinner":{"q":"如果你碰到一个很烫的锅，你会在说“哎呀”之前就缩回手。这是怎么发生的？","listen":"这是反射：一个快速的信息，由脊髓在大脑感觉到之前就作出回应，保护身体。脊髓在脊柱里面，和骨髓不是一回事。"},"faith":[]},{"id":"U08.L02","unit":"U08","ar":"العين: كيف نرى؟","zh":"眼睛：我们怎样看见？","point":"我们能看见，是因为光从物体进入眼睛：晶状体把光聚在视网膜上，视网膜把它变成视神经里的信息，大脑用这些信息形成图像；瞳孔会通过反射放大和缩小，每只眼睛都有一个盲点，由大脑把它补上。","objectives":[{"zh":"能说出眼睛外面看得到的部分和它们的作用：有颜色的虹膜，虹膜中间的开口瞳孔，前面透明的角膜，以及保护眼睛的眼皮、睫毛和眼泪。"},{"zh":"能描述光的路线：从物体到角膜、瞳孔、晶状体、视网膜，然后信息沿视神经到大脑，大脑形成图像；并能指出“眼睛发出光线才能看见”是错的。"},{"zh":"能解释瞳孔在暗处放大、在亮处缩小是一种反射，让进入的光刚好够用并保护视网膜；知道看太阳会伤害视网膜，即使不觉得疼。"},{"zh":"能解释盲点（视神经离开的地方没有感光细胞）以及大脑补全图像的作用，并能指出“只靠眼睛就能看见”是错的。"},{"zh":"能区分视杆细胞（弱光、黑白和形状，每只眼约1.2亿个）和视锥细胞（光线充足时的颜色，约700万个），知道晶状体会为看近和看远改变厚度，视网膜上的像是倒的。","b":true},{"zh":"能解释伊本·海赛姆怎样用实验证明光是进入眼睛的，开普勒又补充了视网膜成像的认识；并用证据判断关于眼睛的流行说法（弱光、眼镜、屏幕）。","b":true}],"terms":[{"ar":"القزحية","zh":"虹膜","py":"hóngmó","en":"Iris"},{"ar":"البؤبؤ","zh":"瞳孔","py":"tóngkǒng","en":"Pupil"},{"ar":"العدسة","zh":"晶状体","py":"jīngzhuàngtǐ","en":"Lens"},{"ar":"الشبكية","zh":"视网膜","py":"shìwǎngmó","en":"Retina"},{"ar":"العصب البصري","zh":"视神经","py":"shìshénjīng","en":"Optic nerve"}],"do":"“瞳孔和盲点”：孩子在明亮的房间里站在镜子前，看镜子里自己的眼睛（不要看灯），瞳孔有多大？用手掌盖住双眼（不按压）数到三十，拿开手马上看镜子里的瞳孔：头几秒它怎样变化？再在卡片左边画一个“+”，右边约8厘米处画一个大黑点，闭上左眼，用右眼盯着“+”，慢慢把卡片移近，黑点会在某个距离突然消失——那就是盲点。","safety":["不要直接看太阳或强光，哪怕一瞬间，也不要透过墨镜或放大镜看。","用手掌盖住眼睛时不要按压眼睛。","玻璃镜子要放在稳固的地方，或由大人拿着。","戴眼镜的孩子戴或不戴都可以，怎么舒服怎么来。"],"explain":"可以这样说：“靠近看看家人的眼睛：有颜色的那一圈叫虹膜，有棕色、黑色、绿色或蓝色；中间的黑圆圈叫瞳孔，它不是画上去的点，而是让光进去的开口，看起来黑是因为眼睛里面是暗的。上面盖着一层透明发亮、像玻璃一样的膜，叫角膜。眼皮和睫毛挡住灰尘，每眨一次眼，眼皮就把眼泪抹在眼睛上，把它洗干净、不让它干。你现在怎么看到这个字？光从纸上反射过来进入你的眼睛：穿过角膜，从瞳孔进去，瞳孔后面透明的晶状体把光聚到眼睛后面的视网膜上。视网膜很薄，里面有几百万个感光细胞，把光变成电信号，沿着视神经送到大脑，大脑用它们形成你看到的东西。所以眼睛不会发出光线，不然在完全黑暗中我们也能看见了。从暗处走到亮处，瞳孔会缩小；从亮处走进暗处，它会慢慢放大。”","mis":[{"says":"“我们能看见，是因为眼睛向物体发出光线。”","answer":"如果眼睛能发出光线，我们在完全黑暗中也能看见。光是从物体来的（或从物体反射过来），进入眼睛；伊本·海赛姆用实验支持了这一点。"},{"says":"“只有眼睛在看，大脑和看东西无关。”","answer":"眼睛收集光并把它变成信息，大脑用这些信息形成我们看到的东西；所以我们注意不到盲点：大脑把它补上了。"},{"says":"“在暗光下看书会永远伤害眼睛。”","answer":"会让眼睛疲劳，可能引起暂时的头疼，但没有证据说明会伤害眼睛；不过光线充足会更舒服。"},{"says":"“戴眼镜会让眼睛变弱，越戴越离不开。”","answer":"眼镜在光进入眼睛之前改变它的路线，让它清楚地落在视网膜上，并不改变眼睛本身；度数随时间变化，戴不戴眼镜都会发生。"}],"dinner":{"q":"在完全黑暗的房间里你什么也看不见。缺少的是什么？真正“看见”的是眼睛还是大脑？","listen":"缺少光。光进入眼睛到达视网膜，然后信息沿视神经到大脑，由大脑形成图像。眼睛不会发出光线。我们不看太阳。"},"faith":[]},{"id":"U08.L03","unit":"U08","ar":"السمع والتوازن والشم والذوق واللمس","zh":"听觉、平衡、嗅觉、味觉和触觉","point":"每一种感觉都是感受器，把外界的某种东西变成神经里的信息：耳朵转换振动，鼻子和嘴转换物质，皮肤转换触碰；大脑把它们汇总起来，所以风味是味觉和嗅觉一起产生的，平衡来自内耳。","objectives":[{"zh":"能描述声音的路线：外耳收集声音，耳道把它送到鼓膜使它振动，三块听小骨传递振动，耳蜗把它变成听神经里的信息送到大脑；并能指出“只靠外耳就能听见”是错的。"},{"zh":"知道内耳的半规管用随头部移动的液体保持平衡，并能解释转圈后为什么会头晕。"},{"zh":"知道长时间的大声会伤害听觉细胞，而且伤害不能恢复；能遵守安全收听的规则（调低音量，耳机每天少于一小时，让耳朵休息）。"},{"zh":"能描述味觉（味蕾能分辨五种味道：甜、咸、酸、苦和鲜味）和嗅觉（鼻子上部的感受器），解释风味来自味觉和嗅觉一起；并能指出“舌头味觉分区图”是错的。"},{"zh":"能用感受器的数量解释皮肤不同部位触觉灵敏度的差别：指尖的感受器大约是背部皮肤的一百倍，所以在手指上相距2–3毫米的两个点能分辨出来，在手臂上要相距35–40毫米。","b":true},{"zh":"能解释科学家怎样知道耳蜗里发生了什么（贝凯希）和我们怎样闻到气味（巴克和阿克塞尔），以及错误的舌头分区图怎样从一张被不准确地重画的图表流传开来。","b":true}],"terms":[{"ar":"طبلة الأذن","zh":"鼓膜","py":"gǔmó","en":"Eardrum"},{"ar":"القوقعة","zh":"耳蜗","py":"ěrwō","en":"Cochlea"},{"ar":"القنوات الهلالية","zh":"半规管","py":"bànguīguǎn","en":"Semicircular canals"},{"ar":"براعم التذوق","zh":"味蕾","py":"wèilěi","en":"Taste buds"},{"ar":"المستقبِل الحسّي","zh":"感受器","py":"gǎnshòuqì","en":"Sensory receptor"}],"do":"“鼻子和味道，皮肤上的两个点”：孩子闭上眼睛、用两根手指捏住鼻子，同伴把苹果或梨中的一种小块放进他嘴里，不说是哪种；嚼一嚼说出：苹果还是梨？按同伴决定的顺序试三次，记下猜对几次；再松开鼻子试三次，这次猜对几次？然后同伴把回形针掰开，两端相距约一厘米，在孩子闭眼时轻碰指尖，有时用一端、有时用两端，孩子说“一个”还是“两个”；再在手臂上试。","safety":["对其中任何一种水果过敏的孩子不尝，也不强迫任何人尝；可以当同伴或只做触觉部分。","水果切成小块、嚼碎，每个孩子用自己的叉子和盘子，实验前洗手。","回形针只轻轻碰皮肤，不用力，远离脸和眼睛。"],"explain":"可以这样说：“声音是在空气中传播的振动。你看到的耳朵把它接住，引到耳道里，耳道尽头有一层绷紧的薄膜，叫鼓膜，声音一到它就振动，像鼓皮一样。鼓膜后面有三块小骨头，把振动传过去并放大，最后一块叫镫骨，是你身体里最小的骨头。然后振动到达耳蜗，一个装着液体、像蜗牛壳一样的部分，液体波动，让特殊细胞上的小毛弯曲，产生电信号，听神经把它送到大脑，大脑才知道是什么声音：妈妈的声音还是学校的铃声。耳屎不是脏东西，是耳道用来清洁自己的。内耳还有另一项工作：平衡。耳蜗旁边有三根连在一起的小管子，叫半规管，里面的液体随着头动而流动，告诉大脑头的位置。转圈后停下，液体还会继续流动一会儿，所以会头晕。尝味道时，香味会从嘴里升到鼻子，所以感冒鼻子塞时，吃东西没有味道。”","mis":[{"says":"“舌头分区：甜在舌尖，苦在舌根，咸和酸在两边。”","answer":"每个有味蕾的地方都能尝出全部五种味道，差别非常小。这张分区图来自一张被不准确地重画的图表。"},{"says":"“我们用外耳听，其他部分没用。”","answer":"外耳只是收集声音；听觉要靠鼓膜、听小骨、耳蜗、听神经和大脑才能完成。"},{"says":"“只要耳朵不疼，大声就没有害处，听力总会恢复。”","answer":"长时间的大声通常在不疼的情况下伤害听觉细胞，受伤的细胞不会恢复。"},{"says":"“味道只来自舌头，鼻子只管气味。”","answer":"风味是味觉和嗅觉一起：咀嚼时气味从嘴里升到鼻子；所以感冒时味道会变淡。"}],"dinner":{"q":"你感冒时，为什么吃东西没什么味道？","listen":"风味来自味觉和嗅觉一起，感冒把鼻子堵住了。这一课还讲到：耳机要调低音量、缩短时间，因为长时间的大声会伤害听觉细胞，而且不能恢复。"},"faith":[]},{"id":"U08.L04","unit":"U08","ar":"ماذا يحدث في جسمي حين أخاف؟","zh":"我害怕时身体里发生了什么？","point":"大脑感到危险时会发出警报，几秒钟内让全身加速，准备逃跑或自卫：肾上腺素让心跳和呼吸加快、肌肉绷紧、消化暂停；危险过去后，“平静刹车”让身体恢复。真有危险时警报是有用的，故意吓别人开玩笑时它是有害的。","objectives":[{"zh":"能描述害怕时身体里发生的事：大脑发出警报，肾脏上面的两个腺体（肾上腺）释放肾上腺素，于是心跳和呼吸加快，肌肉绷紧，瞳孔放大，口干，消化变慢，糖从储存处释放出来。"},{"zh":"能解释应对危险的反应有什么用：几秒钟内让身体准备好逃跑或自卫，它甚至可能在我们弄明白看到了什么之前就开始；知道警报也可能在没有真正危险时响起，并能指出“害怕是丢脸的，勇敢的人不害怕”是错的。"},{"zh":"知道危险过去后，神经系统里的“刹车”让身体回到平静，这需要时间；呼气长的慢呼吸，以及和信任的大人谈一谈都有帮助。"},{"zh":"能从科学和品德两方面分析“吓人的恶作剧”：突然的惊吓对身体的影响和危险；先知禁止恐吓穆斯林，即使是开玩笑；伤害任何人都是不允许的；并能指出“恶作剧只是玩笑，没有害处”是错的。"},{"zh":"知道大脑里的杏仁核负责发出警报，肾上腺分泌肾上腺素，生气时也会启动同样的反应，平静下来的方法能减轻怒气，而不是靠打东西“发泄”；并能指出“是心在害怕”是错的。","b":true},{"zh":"能解释坎农怎样用X光观察到害怕和生气会让胃停止蠕动（1915年的书），设计一个公平比较：运动后慢呼吸和普通坐着哪个恢复得快，并知道为什么不能为了测量去吓别人。","b":true}],"terms":[{"ar":"استجابة الخطر","zh":"战斗或逃跑反应","py":"zhàndòu huò táopǎo fǎnyìng","en":"Fight-or-flight response"},{"ar":"الأدرينالين","zh":"肾上腺素","py":"shènshàngxiànsù","en":"Adrenaline"},{"ar":"مكابح الهدوء","zh":"休息与消化反应","py":"xiūxi yǔ xiāohuà fǎnyìng","en":"Rest-and-digest response"},{"ar":"اللوزة الدماغية","zh":"杏仁核","py":"xìngrénhé","en":"Amygdala"},{"ar":"الغدتان الكظريتان","zh":"肾上腺","py":"shènshàngxiàn","en":"Adrenal glands"}],"do":"“脉搏升高又降下：什么让它更快平静？”：孩子安静坐两分钟，数手腕脉搏30秒再乘以2，这是休息时的脉搏；原地跳一分钟后马上再数；第一种方法：坐两分钟正常呼吸，再数脉搏；休息五分钟让脉搏接近开始的数字，再跳一分钟马上数；第二种方法：坐两分钟慢慢呼吸（用鼻子吸气数到四，用嘴慢慢呼气数到六），再数脉搏；比较哪种方法让脉搏降得更快。","safety":["不为了测量去吓任何人，也不突然用声音或动作吓人；用跳跃代替惊吓来提高脉搏。","这不是比赛；不比较孩子们的数字，每个人不一样是正常的。","感到头晕、疼痛或喘不过气就马上停下坐好，并告诉大人；晕倒或胸痛要去看医生。","已知有心脏或呼吸问题的孩子，经家长同意只做坐着的部分（休息时的脉搏和慢呼吸）；用哮喘喷雾的孩子要带在身边。","天气炎热或长时间空腹后不做；数手腕的脉搏，不数脖子的。"],"explain":"可以这样说：“你走在人行道上，突然一辆自行车飞快地从你身边擦过，你还没弄清楚看到的是什么就跳到一边去了！在你大脑深处有一个小小的部分，像警铃一样。它从眼睛看到、耳朵听到的东西里捕捉到危险，很快拉响警报，有时在大脑还没完全看懂之前。所以你先跳开，后来才知道是自行车。警报一响，神经就发出信息，肾脏上面的两个小腺体往血里释放一种物质，叫肾上腺素。几秒钟内全身都变了：心跳加快、跳得更有力，呼吸加快，肌肉绷紧准备行动，肝脏放出储存的糖提供能量，瞳孔放大让更多光进来，嘴巴发干，消化变慢，所以肚子里感觉怪怪的，皮肤上的汗毛也会竖起来起鸡皮疙瘩。这一切都是为了在几秒钟内逃跑或保护自己。危险过去后，身体会慢慢平静下来，慢慢呼吸、呼气长一点会有帮助。害怕不是丢脸的事。可是故意吓唬别人，即使是开玩笑，也会给对方的身体拉响整套警报，所以是不可以的。”","mis":[{"says":"“是心在害怕、在爱。”","answer":"警报从大脑开始，心脏是在神经和肾上腺素的命令下加快的；我们感觉到它在怦怦跳，就以为害怕在心里。"},{"says":"“害怕是丢脸的，勇敢的人从不害怕。”","answer":"害怕是保护身体的警报；勇敢的人也会害怕，然后明智地行动。强烈的情绪是正常的。"},{"says":"“吓人的恶作剧是无害的玩笑，大家事后都会笑。”","answer":"突然的惊吓会在被吓的人身上拉响整套警报，可能让他摔倒，极少数情况下还会伤到心脏；先知禁止恐吓穆斯林，即使是开玩笑。"},{"says":"“生气时就打枕头或大喊，把气发泄出来。”","answer":"一项综合了154项研究的分析发现，“发泄”并不能减轻怒气，反而可能让它增加；深呼吸、平静下来和暂停一下才能减轻它。"}],"dinner":{"q":"你突然害怕时身体里发生了什么？用恶作剧吓人是无害的玩笑吗？","listen":"大脑发出警报，释放肾上腺素，心跳和呼吸加快，肌肉绷紧。害怕不丢脸，呼气长的慢呼吸能帮助平静。恐吓别人，即使是开玩笑，也是不允许的伤害。"},"faith":[]},{"id":"U08.L05","unit":"U08","ar":"الذاكرة والنوم","zh":"记忆和睡眠","point":"记忆分三个阶段形成：我们专心学习，然后大脑巩固记忆（很多是在睡眠中完成的），然后我们把它提取出来。遗忘是正常的，学完后马上忘得最快；提取练习、间隔复习和充足的睡眠（孩子每天9到12小时）能减少遗忘。","objectives":[{"zh":"能描述记忆形成的三个阶段：专心时学习，然后大脑在几分钟、几小时、几天里巩固记忆，需要时再提取出来；并知道专心是开始的前提。"},{"zh":"能解释遗忘是正常的，学完后马上忘得最快，然后变慢；大脑是用碎片重建记忆的，所以可能出错；并能指出“记忆像照相机，把一切照原样记下来”是错的。"},{"zh":"知道大脑在睡眠中工作，重新激活白天的记忆并巩固它们；6到12岁的孩子每天需要9到12小时睡眠，睡眠不足会削弱注意力和学习；并能指出“睡觉时大脑关机了”“熬夜复习比睡觉更有用”是错的。"},{"zh":"能运用有证据支持的记忆方法：用提取代替重读，隔几天复习一次，睡足觉；以及健康的睡眠习惯：睡前一小时不看屏幕，固定作息；并能指出“反复重读是最好的记忆方法”是错的。"},{"zh":"知道海马体在形成新记忆中的作用；一夜是由深睡眠和做梦睡眠组成的几个周期，第一个周期大约在90分钟后；做梦睡眠时手臂和腿的肌肉会暂时放松；巩固记忆两种睡眠都需要。","b":true},{"zh":"能解释艾宾浩斯怎样用无意义音节在自己身上测量遗忘（1885年），为什么这个实验后来被重做（2015年），设计一个提取练习和重读之间的公平比较，并知道只在一个人身上做实验的局限。","b":true}],"terms":[{"ar":"الذاكرة","zh":"记忆","py":"jìyì","en":"Memory"},{"ar":"الاسترجاع","zh":"提取练习","py":"tíqǔ liànxí","en":"Retrieval practice"},{"ar":"تثبيت الذاكرة","zh":"记忆巩固","py":"jìyì gǒnggù","en":"Memory consolidation"},{"ar":"الحُصين","zh":"海马体","py":"hǎimǎtǐ","en":"Hippocampus"},{"ar":"نوم الأحلام","zh":"快速眼动睡眠","py":"kuàisù yǎndòng shuìmián","en":"REM sleep"}],"do":"“考自己还是重读？”：孩子准备两张单词表。第一张读四遍，每遍一分钟，然后折起来；第二张读一遍一分钟，然后盖住，用一分钟写出记得的，再核对，这样“写—核对”再做两次，两张表各用四分钟。之后不再看，按时睡觉。第二天不看表，先写出第一张记得的，再写第二张的，数一数哪张记得多。","safety":["不为了测试熬夜的影响而熬夜，也不剥夺任何人的睡眠；按时睡觉。","这不是比赛；不比较孩子们的数字，每个人不一样是正常的。","写字有困难的孩子可以把单词说给大人，由大人写下。","实验时不用屏幕；坐在安静、明亮的地方。"],"explain":"可以这样说：“想想妈妈的脸、椰枣的味道、去学校的路：它们都存在你的大脑里。这就是记忆：大脑把我们学到和经历的东西存起来，需要时再拿出来的能力。形成一个记忆要经过三个阶段：先专心地学，然后大脑在几分钟、几小时、几天里把记忆加固，最后在需要时把它拿出来。不专心，记忆根本开始不了：你在忙别的事时经过你身边的东西，大多会丢掉。可是我们会忘记。大约140年前，一位叫艾宾浩斯的德国科学家测量自己的遗忘，发现学完后头几个小时忘得最多，然后越来越慢。所以遗忘是正常的，有时还有用：把不需要的东西放下。记忆也不是照相机：回忆时大脑用碎片重建发生的事，可能会混进别的东西。怎样少忘一些？一是提取：合上书考自己，再核对，每次自己把知识拿出来，它就比重读一遍更牢固；二是间隔：隔几天复习一次；三是睡觉：大脑在睡眠中巩固白天学的东西，所以孩子要睡9到12小时，睡前一小时不看屏幕。”","mis":[{"says":"“睡觉时大脑整个关机休息了。”","answer":"大脑在睡眠中工作：重新激活白天的记忆并巩固它们，还会经历深睡眠和做梦睡眠的几个周期。"},{"says":"“考试前一晚熬夜复习比睡觉更有用。”","answer":"学习后的睡眠能巩固记忆，熬夜会削弱考试时的注意力；分几天复习比只用一个晚上更有用。"},{"says":"“记忆像照相机，把一切照原样记下来。”","answer":"回忆时大脑用碎片重建记忆，可能会混进别的东西；所以两个人讲同一件事，细节可能不一样。"},{"says":"“把课文反复重读很多遍是最好的记忆方法。”","answer":"提取练习（合上书问自己，再核对）比重读和划重点更有用，间隔复习效果更好。"}],"dinner":{"q":"想记住一样东西，最好的办法是反复重读，还是不看书试着回想？考试前为什么不熬夜？","listen":"不看书试着回想，并隔几天复习一次。大脑在睡眠中巩固学到的东西，所以睡足觉（9到12小时）比熬夜更有用。"},"faith":[]},{"id":"U08.L06","unit":"U08","ar":"مشاعري وجسمي","zh":"我的情绪和我的身体","point":"所有情绪都是正常的，并且会影响身体，因为大脑会给心脏、肠胃和肌肉发信息；我们可以通过停下来、呼吸、活动和说出来让情绪平静，也可以寻求帮助。欺凌是反复的故意伤害，告诉一个大人就能制止它。屏幕上修过的照片不是衡量我们身体的标准。","objectives":[{"zh":"知道所有情绪都是正常的——快乐、生气、伤心和焦虑，而且会影响身体：焦虑可能让肚子疼，生气让心跳加快，因为大脑给全身发信息。"},{"zh":"会用平静下来的方法：停下来离开一会儿，慢呼吸和数数，活动或画画，和信任的人说说；知道表达感受是可以的，伤害人或东西是不可以的。"},{"zh":"知道什么是欺凌：反复的故意伤害，双方力量不对等，可以是语言、排挤、身体或屏幕上的；知道自己遇到或看到时该怎么做：告诉能制止它的大人，不沉默，不参与。"},{"zh":"知道屏幕上很多照片都用滤镜修过，拿自己的身体和它们比会让人心累；看重身体能做的事，而不只是外表。"},{"zh":"知道科学家研究过大脑和肠道之间的联系，九世纪的艾布·宰德·巴勒希写过关于恐惧、悲伤、强迫念头以及用思考和预防来治疗它们的著作。","b":true}],"terms":[{"ar":"المشاعر","zh":"情绪","py":"qíngxù","en":"Emotions"},{"ar":"التهدئة","zh":"冷静下来","py":"lěngjìng xiàlái","en":"Calming down"},{"ar":"التنمر","zh":"欺凌","py":"qīlíng","en":"Bullying"},{"ar":"صورة الجسم","zh":"身体意象","py":"shēntǐ yìxiàng","en":"Body image"},{"ar":"طلب العون","zh":"寻求帮助","py":"xúnqiú bāngzhù","en":"Help-seeking"}],"do":"“我身体里的情绪地图”：孩子回想一次感到焦虑的情境（比如考试前或第一次出远门），用蓝色在人体图上涂出当时有感觉的地方：肚子、胸口、手……；再用红色画一次生气的情境，用黄色画一次快乐的情境；然后试试慢呼吸：吸气数到四，呼气数到六，做三次，写下有没有变化；最后和同学或家人的地图比一比，哪里相同、哪里不同。","safety":["不要求任何人向全班讲自己的经历；地图是他自己的，愿意才分享。","回想起让自己很难受的事情时，可以停下来，和信任的大人说说。","不评论任何人的画，也不评论任何人的身体。"],"explain":"可以这样说：“在害怕那一课里你知道了，大脑感到危险时会给心脏和肺发信息。害怕是情绪的一种，情绪就是我们心里的感受，像快乐、生气、伤心、焦虑。所有情绪都是正常的，每一种都会影响身体。在大脑里传递情绪信息的物质，在肠子里也起作用，所以很多孩子考试前或开学第一天会肚子疼。这种疼是真的，不是装的，但新出现的或很厉害的疼要去看医生。每个人有时都会生气、伤心、担心。说出自己的感受是可以的，但对人大喊、打人或摔东西是不可以的。那该怎么办？让身体和心平静下来：停下来，走开一会儿，数数，像害怕那一课那样慢慢呼吸，吸气数到四、呼气数到六；或者活动一下，把感受画出来，和信任的人说说。如果有人反复故意欺负比他弱的人，这就是欺凌，要告诉大人，让大人来制止。”","mis":[{"says":"“生气和伤心是坏情绪，哭的人很软弱。”","answer":"所有情绪都是正常的，哭不是软弱；重要的是怎样对待这种感受：表达它但不伤害别人，太重了就寻求帮助。"},{"says":"“考试前肚子疼是装的或撒谎。”","answer":"大脑和肠子互相传递信息，同样的物质调节情绪和消化；所以疼是真的，呼吸和说出来能减轻它，新出现的或很厉害的疼要看医生。"},{"says":"“欺凌只是开玩笑，告诉大人的人是告密者。”","answer":"玩笑是大家一起笑，别人要求停下就会停；欺凌是强的一方反复伤害别人。告诉大人是在保护同伴，不是告密。"},{"says":"“屏幕照片上的脸和身体是真的，我的身体应该像它们一样。”","answer":"很多照片是挑选过、用滤镜修过的；和它们比会让人心累。看重你的身体能做的事。"}],"dinner":{"q":"你在身体的哪里感觉到焦虑？如果看到同学被欺凌，你会怎么做？","listen":"焦虑可能在肚子里感觉到，因为大脑和肠子互相传信息；可以用停下来、慢呼吸和说出来让它平静。欺凌是强的一方反复伤害别人；不跟着笑也不参与，而是找一个能制止它的大人，并站在被欺负的人一边。"},"faith":[]},{"id":"U08.L07","unit":"U08","ar":"الشاشات وجسمي","zh":"屏幕和我的身体","point":"长时间坐在屏幕前会给身体带来好几件事：眼睛需要休息和到户外玩耍，肌肉不活动，睡前看屏幕会推迟入睡；很多应用程序是故意设计成让人停留更久的；所以指南建议减少娱乐屏幕时间，用活动打断久坐，并在家里定一个屏幕使用计划。","objectives":[{"zh":"能把长时间坐在屏幕前对身体的影响放在一起：眼睛需要20-20-20的休息和户外玩耍（眼睛一课），肌肉不活动，睡前看屏幕会推迟入睡（记忆和睡眠一课）。"},{"zh":"知道相关建议：减少久坐，特别是娱乐屏幕时间；加拿大的指南建议每天娱乐屏幕时间最多两小时，不要长时间坐着不动；会用活动打断久坐。"},{"zh":"知道一些应用和游戏是设计来吸引注意力、让人停留更久的：自动播放、无限滑动、快速奖励、弹出的广告；所以很难停下来，并不是因为孩子意志弱。"},{"zh":"能和家人一起定一个家庭屏幕计划：不用屏幕的时间（吃饭时和睡前一小时）、不用屏幕的地方（晚上的卧室），以及屏幕与活动、玩耍和睡眠之间的平衡。"},{"zh":"能区分一条建议的强度和支持它的证据的确定程度：世界卫生组织减少久坐的建议是强建议，尽管证据的确定性较低；中国的一项课外户外活动试验显示了中等程度的效果。","b":true}],"terms":[{"ar":"الجلوس الطويل","zh":"久坐行为","py":"jiǔzuò xíngwéi","en":"Sedentary behaviour"},{"ar":"شاشة الترفيه","zh":"娱乐屏幕时间","py":"yúlè píngmù shíjiān","en":"Recreational screen time"},{"ar":"التصميم الجاذب","zh":"说服式设计","py":"shuōfúshì shèjì","en":"Persuasive design"},{"ar":"خطة الشاشات","zh":"家庭媒体计划","py":"jiātíng méitǐ jìhuà","en":"Family media plan"},{"ar":"يقين الدليل","zh":"证据确定性","py":"zhèngjù quèdìngxìng","en":"Certainty of evidence"}],"do":"“用圆圈画出我的一天：屏幕、活动和睡眠”：孩子记录普通的一天，把睡眠时间涂蓝色，学校涂黄色，娱乐屏幕涂红色，活动和玩耍涂绿色；数一数红、绿、蓝各几个小时，和建议比较（娱乐屏幕最多两小时，活动至少一小时，睡眠9到11小时）；再画一个想要的一天，里面每二十分钟让眼睛休息一次，坐着的时间之间穿插活动；最后和家人一起写下三条家庭规则。","safety":["记录只看这一天，不评判任何人；不和别人比较自己的一天。","活动要在安全的地方。","不提任何应用或游戏的名字；只谈时间，不谈内容。"],"explain":"可以这样说：“这个单元你认识了眼睛和睡眠，现在我们把它们和肌肉放在一起，看看在屏幕前坐几个小时会怎样。眼睛：长时间看近处会累，所以用20-20-20规则：每二十分钟看二十秒大约六米远的东西，眨眨眼，屏幕离开一臂远。肌肉：长时间坐着肌肉就不工作，而肌肉是越用越强的。睡眠：睡前看屏幕会让人更清醒，屏幕的光还可能推迟睡眠激素。久坐是醒着的时候长时间坐着或躺着、几乎不动，这和身体需要的休息和睡眠不一样。娱乐屏幕时间是为了消遣看屏幕的时间，不包括学习。世界卫生组织建议你这个年龄的孩子减少久坐，尤其是娱乐屏幕；加拿大的指南是每天最多两小时。很难停下来不是因为你不够努力，而是很多应用故意用自动播放、无限滑动、快速奖励来留住人，大人也很难停下来。所以我们一起定一个家庭计划。”","mis":[{"says":"“只要坐着就是在休息，在屏幕前坐几个小时是让身体放松。”","answer":"身体需要的是休息和睡眠；长时间坐着时肌肉停止工作，眼睛也会累；要不时起来活动一下来打断它。"},{"says":"“我停不下游戏，说明我意志薄弱。”","answer":"很多应用是用精心设计的技巧来让人停留更久的；了解这些技巧并定一个计划会有帮助，大人也很难停下来。"},{"says":"“睡前看屏幕帮我入睡。”","answer":"屏幕可能让我们更清醒、心跳加快，它的光还可能干扰睡眠激素；睡前一小时放下屏幕。"},{"says":"“所有屏幕都有害，我永远不应该用。”","answer":"屏幕是工具：用来学习、交流和获取知识是有益的；需要的是平衡：有屏幕的时间，有活动和玩耍的时间，还要睡足觉。"}],"dinner":{"q":"游戏有哪些让人很难停下来的技巧？你建议我们家的屏幕计划有哪三条规则？","listen":"自动播放、无限滑动、快速奖励和广告；规则比如：吃饭时不用屏幕，睡前一小时不用屏幕、手机放在卧室外面，每天一小时户外活动和玩耍，每二十分钟让眼睛休息一次。"},"faith":[]},{"id":"U09.L01","unit":"U09","ar":"الجلد: درع حي يتجدد","zh":"皮肤：会自我更新的活屏障","point":"皮肤是由两层构成的活器官：外面的表皮大约四周全部更新一次，里面的黑色素能防晒；下面的真皮有血管、神经、汗腺和毛根；它是一道屏障，能保护、能感觉，小擦伤后还能自己修复。","objectives":[{"zh":"能指出皮肤的两层：外面是表皮，最上面的细胞是死的、扁平的，会不断脱落，下面是会分裂的活细胞，整个表皮大约四周更新一次；表皮下面是真皮，里面有血管、神经、汗腺和毛根。"},{"zh":"能解释皮肤是一道屏障，不让身体的水分渗出、不让微生物进入，能感觉触碰、温暖、寒冷和疼痛，下面还有一层脂肪保护它。"},{"zh":"能用黑色素解释肤色：黑色素由表皮里的细胞制造，能防止有害的阳光；人们制造它的细胞数量差不多，只是制造的量不同，所以肤色不代表力量或价值；并能做到防止晒伤。"},{"zh":"能描述擦伤怎样愈合：血液凝固止血，干成痂保护下面，周围红几天，然后下面长出新皮肤；并能做到：用水和温和的肥皂洗、盖好，不抠痂，红肿或疼痛加重、或血止不住时告诉大人。"},{"zh":"知道表皮细胞在往表面走的途中充满角蛋白而变硬，肘部和脚底的表皮厚度不同，深的伤口可能留下比原来皮肤弱的疤痕。","b":true}],"terms":[{"ar":"البشرة","zh":"表皮","py":"biǎopí","en":"Epidermis"},{"ar":"الأدمة","zh":"真皮","py":"zhēnpí","en":"Dermis"},{"ar":"الميلانين","zh":"黑色素","py":"hēisèsù","en":"Melanin"},{"ar":"قشرة الجرح","zh":"痂","py":"jiā","en":"Scab"},{"ar":"الكيراتين","zh":"角蛋白","py":"jiǎodànbái","en":"Keratin"}],"do":"“两个苹果：果皮能保护下面吗？”：两个苹果各放一个盘子，分别写上“完好”和“划伤”；由大人用牙签在第二个苹果皮上划三四道（不切开）；把两个苹果并排放在同一个地方，避开阳光直射；三到五天里每天看一看但不碰，记录哪里先变棕色或变软。","safety":["由大人用牙签或叉子划，不用刀。","实验后的苹果不吃，装进封好的袋子扔掉，碰过要洗手。","对某种水果过敏的孩子换一种水果，或只观察。"],"explain":"可以这样说：“看看你的手背。包着你全身、从头顶到脚底的这层东西就是皮肤。它是你身体最大的器官：一个大人的皮肤摊开来差不多能盖住一张单人床。可它不是包着我们的死口袋，而是活的，能感觉、会工作、会自己修复。用显微镜看很薄的一片皮肤，能看到两层：外面是表皮，最上面的细胞是死的、扁平的，像小鳞片，每天都在悄悄脱落，下面的活细胞不断分裂、往上补，所以你的表皮大约四周全部换一遍。表皮下面是真皮，里面有细小的血管、能感觉的神经、汗腺、毛根，还有让皮肤结实、能伸缩的纤维。再下面是一层保暖的脂肪。皮肤首先是一道屏障，不让身体里的水跑出去，也不让微生物和脏东西进来，所以你游泳几个小时水也进不了身体。肤色来自黑色素，它能挡住有害的阳光；每个人制造黑色素的细胞差不多一样多，只是做出来的量不同，所以肤色不会让任何人比别人更好。”","mis":[{"says":"“皮肤是不会变的死外壳，从出生就是同一层。”","answer":"表皮最外面确实是死细胞，但它们每天都在脱落，下面的活细胞分裂补上；整个表皮大约四周更换一次。"},{"says":"“皮肤浅（或深）的人更强、更好。”","answer":"肤色只取决于黑色素的多少，人们制造黑色素的细胞数量差不多；它和力量、价值都没有关系。"},{"says":"“伤口露着、把痂抠掉会好得更快。”","answer":"痂是天然的盖子，保护下面直到新皮肤长好；抠掉会让愈合变慢、留下更明显的痕迹。要把擦伤洗干净并盖好。"},{"says":"“我看不到皮肤在脱落，所以它不会脱落。”","answer":"细胞太小，单凭眼睛看不见；用胶带、放大镜和显微镜就能看到。"}],"dinner":{"q":"你游泳时水为什么进不了身体？人们的肤色为什么不一样？","listen":"皮肤是一道挡住水和微生物的屏障，能感觉，表皮大约四周更新一次。肤色来自防晒的黑色素的多少，不会让任何人比别人更好；每个人都要防晒。"},"faith":[]},{"id":"U09.L02","unit":"U09","ar":"الحرارة: كيف يبقى جسمي دافئاً لا حاراً؟","zh":"体温：我的身体怎样保持温暖而不过热？","point":"身体内部的温度接近37摄氏度，大脑底部有一个部位测量并调节它：热的时候皮肤出汗，靠蒸发降温，皮肤血管扩张；冷的时候皮肤血管收缩，起鸡皮疙瘩，肌肉发抖产生热量；感染时大脑会把体温调高，这就是发烧。","objectives":[{"zh":"知道身体内部的温度接近37摄氏度，一天中会稍有变化，人与人之间也稍有不同，运动时会升高；大脑里有一个部位测量体温并和合适的数值比较，然后命令身体降温或保暖。"},{"zh":"能解释身体在热的时候怎么做：汗腺排出汗水，汗水蒸发让皮肤变凉；皮肤血管扩张，脸变红，把热散出去；能解释为什么潮湿的天气降温效果差；并能指出“出汗能排毒”是错的。"},{"zh":"能解释身体在冷的时候怎么做：皮肤血管收缩，皮肤变白，热量留在里面；毛根旁的小肌肉收缩，起鸡皮疙瘩；肌肉快速发抖产生热量；衣服能留住温暖的空气。"},{"zh":"能解释发烧是大脑在身体对付感染时把体温调高，大多数情况下发烧本身无害，病人的状态比数字更重要；知道中暑衰竭的征兆；能明智地应对：告诉大人、喝水、在阴凉处休息、不自己吃药。"},{"zh":"知道调节体温的部位叫下丘脑；体温可以在口腔、耳朵、额头或腋下测量，读数稍有不同；37这个数字来自十九世纪的数百万次测量，一项新的研究发现今天成年人的平均体温稍低一些。","b":true}],"terms":[{"ar":"غدة العرق","zh":"汗腺","py":"hànxiàn","en":"Sweat gland"},{"ar":"الارتجاف","zh":"发抖","py":"fādǒu","en":"Shivering"},{"ar":"الحمّى","zh":"发烧","py":"fāshāo","en":"Fever"},{"ar":"الإنهاك الحراري","zh":"热衰竭","py":"rè shuāijié","en":"Heat exhaustion"},{"ar":"تحت المهاد","zh":"下丘脑","py":"xiàqiūnǎo","en":"Hypothalamus"}],"do":"“蒸发会降温：湿纸巾和干纸巾”：孩子把一张纸巾用室温的水浸湿后拧干，放在右手背上，干纸巾放在左手背上，用纸扇同时给两只手扇风两分钟，拿掉纸巾后用手背碰碰脸颊：哪只手更凉？如果有两支温度计，一支包湿纸巾、一支包干纸巾，扇风五分钟后读数比较。","safety":["用室温的水，不用热水也不用冰水。","只用电子温度计或室温计；不用水银温度计或玻璃温度计。","把洒出来的水擦干，免得有人滑倒。"],"explain":"可以这样说：“夏天太阳很晒，冬天很冷，可你身体里面的温度一直接近37度。这是怎么做到的？你大脑底部有一个小部位，像家里的温控器一样：测量血液的温度，和合适的数值比较，高了就命令身体降温，低了就命令身体保暖。体温也不是一成不变的：清晨低一些，下午高一些，跑步时会升高，人与人之间也稍有不同。身体变热时做两件事：第一，真皮里的汗腺把带一点盐的水排到皮肤表面，水蒸发时带走皮肤的热，皮肤就凉了，出汗不是排毒，是降温；第二，皮肤里的血管扩张，更多血流到表面散热，所以脸会变红。潮湿的天气汗不容易蒸发，降温效果差，所以要多休息多喝水。身体变冷时正好相反：皮肤血管收缩，热留在里面；小肌肉让汗毛竖起来，起鸡皮疙瘩；肌肉快速发抖，产生热量。生病发烧，多数是身体在对付感染，要告诉大人，多喝水休息，药由大人和医生决定。”","mis":[{"says":"“健康的人体温任何时候都正好是37度。”","answer":"接近37度，但会稍有变化：清晨低一些、下午高一些，运动时升高，人与人之间也稍有不同。"},{"says":"“出汗把身体里的毒素排出去，出汗越多越干净。”","answer":"汗是水和盐，主要作用是靠蒸发降温；清洁血液是肾脏和肝脏的工作。"},{"says":"“发烧是很危险的病，数字越高越危险。”","answer":"发烧大多是身体在对付感染的信号，本身通常无害；告诉家人，多喝水、休息，由家长和医生决定怎么做。"},{"says":"“生病的人是不小心或身体弱。”","answer":"谁都会生病，强壮的、细心的人也会；照顾病人，不责怪。"}],"dinner":{"q":"热的时候你的脸为什么会红，冷的时候为什么会发抖？发烧了怎么办？","listen":"热的时候皮肤出汗，靠蒸发降温，血管扩张所以脸红；冷的时候血管收缩，肌肉发抖产生热量。发烧大多说明身体在对付感染：告诉家人，多喝水、休息，药由家长和医生决定。"},"faith":[]},{"id":"U09.L03","unit":"U09","ar":"الدفاع: كيف يمنع جسمي الميكروبات؟","zh":"防御：身体怎样阻挡微生物？","point":"大多数微生物不会让我们生病，只有少数会。身体首先用屏障（皮肤、黏液、纤毛、眼泪和胃酸）阻挡它们；如果它们穿过屏障，血液会带来吞噬它们的白细胞（炎症）；然后专门的防御系统制造抗体，并记住这种微生物。用肥皂洗手能挡住它们传播的大部分途径。","objectives":[{"zh":"知道微生物是眼睛看不见的极小生物，大多数不会让我们生病，有些还有益，只有少数会致病；能区分细菌（单细胞生物）和病毒（小得多，进入我们的细胞，利用细胞复制自己）。"},{"zh":"能说出身体的第一道屏障：皮肤，鼻子和嘴里的膜和黏液，清扫黏液的纤毛，眼泪，胃里的酸；能解释为什么微生物会从伤口进入，或在我们用不干净的手摸眼睛、鼻子和嘴时进入。"},{"zh":"能描述微生物穿过屏障后会发生什么：几个小时内发红、肿胀、发热，因为血液带来吞噬微生物的白细胞；然后是第一次比较慢的专门防御，制造针对这种微生物的抗体并记住它，第二次就能更快反应。"},{"zh":"能用正确的方法洗手（水、肥皂，搓20秒，包括手背、指缝和指甲下面，然后冲洗、擦干），在该洗的时候洗，并解释为什么只用水不够；知道抗生素对感冒这样的病毒没有作用，只能按处方、按医嘱使用。"},{"zh":"知道专门防御里有两类淋巴细胞：一类激活其他细胞、清除被感染的细胞并形成记忆细胞，另一类制造抗体，让微生物变得无害并帮助其他细胞处理它。","b":true}],"terms":[{"ar":"الفيروس","zh":"病毒","py":"bìngdú","en":"Virus"},{"ar":"الالتهاب","zh":"炎症","py":"yánzhèng","en":"Inflammation"},{"ar":"الخلية البلعمية","zh":"吞噬细胞","py":"tūnshì xìbāo","en":"Phagocyte"},{"ar":"الجسم المضاد","zh":"抗体","py":"kàngtǐ","en":"Antibody"},{"ar":"المضاد الحيوي","zh":"抗生素","py":"kàngshēngsù","en":"Antibiotic"}],"do":"“油和肉桂粉：只用水够吗？”：孩子用一点油搓手掌，大人在手上撒一点肉桂粉，搓开；先只用水冲五秒，不用肥皂，看看还剩什么；再用肥皂搓20秒：手掌、手背、指缝和指甲下面；冲洗擦干后再看；记录只用水后剩下多少，用肥皂后剩下多少，哪里剩得最多。","safety":["手上有肉桂粉时不要摸眼睛或脸；如果碰到眼睛，用大量清水冲洗并告诉大人。","对肉桂或姜黄过敏的孩子用面粉代替。","实验后擦干净洗手池和地面，免得有人踩到油滑倒。"],"explain":"可以这样说：“微生物是你眼睛看不见的极小生物，生活在你的皮肤上、嘴里、肠子里，和你周围的每样东西上。大多数不会让我们生病，有的还有益，比如肠道居民，只有少数会致病。细菌是一种单细胞生物；病毒比细菌小得多，它钻进你身体的细胞，利用细胞复制出很多个自己，感冒和流感就是病毒引起的。那你为什么不是天天生病？首先，身体有屏障：完整的皮肤像一道墙；鼻子和嘴里有黏黏的黏液把它们粘住，纤毛把黏液扫出去，像呼吸那一课学的；眼泪冲洗眼睛，胃酸挡住很多微生物。它们从哪里进来？从皮肤的伤口，或者你用摸过门把手、病人的手的手去摸眼睛、鼻子和嘴。比如一根木刺扎进手指带进了微生物，几个小时后那里会发红、肿、发热、疼，这是血液带来了白细胞，把微生物吞掉，这叫炎症，是身体在工作。然后身体还会制造专门的抗体，并记住这种微生物，下次来了就能更快对付它。”","mis":[{"says":"“所有微生物都是病，必须全部杀死。”","answer":"大多数不会让我们生病，很多是有益的，占住地方让有害的找不到位置；我们在该洗手的时候洗手，是为了挡住有害的，而不是给身体消毒。"},{"says":"“用水冲几秒钟就够了。”","answer":"微生物粘在手上的油脂和污垢上，只用水冲不掉；用肥皂搓20秒才能洗掉。"},{"says":"“抗生素能治好感冒。”","answer":"感冒是病毒引起的，抗生素对病毒没有作用，也不会让病好转；医生只为细菌感染开抗生素。"},{"says":"“木刺周围红肿说明身体输了。”","answer":"发红和发热是血液带来了负责防御的白细胞，这是身体在工作。如果红肿加重、扩大或出现脓，要告诉大人。"},{"says":"“光是冷就会感冒：我没穿外套出门就感冒了。”","answer":"感冒是病毒引起的，通过接触病人、接触物体表面或飞沫传播；冷会让我们疲劳，但不会制造病毒。"}],"dinner":{"q":"你每天都碰到有微生物的东西，却没有生病。为什么？为什么只用水洗手不够？","listen":"大多数微生物不会让我们生病，身体还有屏障：皮肤、黏液、眼泪，然后有吞掉微生物的白细胞，再有身体会记住的抗体。微生物粘在手上的油脂上，所以要用肥皂搓20秒。抗生素治不好感冒。"},"faith":[]},{"id":"U09.L04","unit":"U09","ar":"اللقاحات، وقضية الوحدة: كيف نحمي من لا يستطيع حماية نفسه؟","zh":"疫苗和单元项目：怎样保护不能保护自己的人？","point":"疫苗用微生物的一部分，或者减弱的、失去活性的微生物来训练专门防御，让身体在不生病的情况下产生抗体和记忆；当大多数人接种时，不能接种的人也能受到保护。人类就是这样在1980年消灭了天花；2000年到2023年间，麻疹疫苗避免了大约6000万人死亡。","objectives":[{"zh":"能解释疫苗里含有微生物的一部分、减弱的或失去活性的微生物，或者制造它一部分的指令，专门防御因此得到训练，在不生病的情况下产生抗体和记忆；有些疫苗需要打不止一剂。"},{"zh":"能解释群体保护：大多数人接种后，微生物就不容易传到不能接种的人身上（比如免疫力弱的人，或对疫苗某种成分严重过敏的人），这种保护并不是百分之百。"},{"zh":"能讲天花的故事：这种病夺去了几亿人的生命；拉齐写下了对天花和麻疹的第一份准确的临床描述；1796年琴纳在一个孩子身上试用牛痘，保护了他；1980年宣布天花被消灭；并知道2000年到2023年间麻疹疫苗避免了约6000万人死亡。"},{"zh":"能处理小烫伤和小伤口：用流动的冷水冲烫伤处20分钟，不涂黄油、药膏或油，不挑破水泡；对流血的伤口直接按压；大的、深的或在脸上的烫伤，以及止不住的流血，要找大人或叫急救；照顾病人，不责怪。"},{"zh":"能区分疫苗的种类（减弱的微生物、失去活性的微生物、微生物的一部分，或制造这一部分的指令），知道轻微的副作用通常几天内消失，严重的极少见，群体保护需要的接种比例因病而异。","b":true}],"terms":[{"ar":"اللقاح","zh":"疫苗","py":"yìmiáo","en":"Vaccine"},{"ar":"الحماية الجماعية","zh":"群体免疫","py":"qúntǐ miǎnyì","en":"Herd (community) immunity"},{"ar":"الجدري","zh":"天花","py":"tiānhuā","en":"Smallpox"},{"ar":"الإسعاف الأولي","zh":"急救","py":"jíjiù","en":"First aid"}],"do":"“传播游戏：谁保护谁？”：孩子画一个大圆圈，上面有20个相邻的小圆圈，每个代表一个人，每人只和左右两个邻居见面。第一轮（没有人接种）：给一个人画红色记号表示生病，每一轮每个病人的两个邻居都会生病，数一数要几轮所有人都病了；第二轮：擦掉记号，给分散的15个人画蓝色，表示已接种，不会生病也不会传染，再从一个病人开始，看病能传到多远；比较两轮的结果。","safety":["游戏在纸上或用豆子玩，不碰别人的身体，也不交换放进过嘴里的东西。","不要把班上真实的孩子叫作“病人”或“没接种的人”；圆圈都是想象出来的人。","玩游戏用的豆子不能吃，要远离小孩子。"],"explain":"可以这样说：“还记得吗？身体第一次遇到一种新微生物时，要好几天才能做出抗体，所以会生病，然后才记住它。那如果身体在遇到它之前就先认识它的样子呢？疫苗就是这样做的：里面有微生物的一部分，或者是减弱的、失去活性的微生物，不会让人生病。专门防御拿它来练习，制造抗体和记忆，真的微生物来了，身体马上就认出来。有些疫苗要打不止一剂，记忆才会牢固。有些人不能接种：生病导致免疫力弱的人，或对疫苗里某种东西严重过敏的人。谁来保护他们？他们周围的人。传染病需要一条从人传到人的路，大多数人接种了，路就断了，微生物就不容易传到弱的人身上，这叫群体保护。所以你接种疫苗不只保护自己，还保护爷爷奶奶、邻居家的小宝宝和医院里的病人。不过这种保护不是百分之百，所以还要继续洗手、用手肘挡喷嚏。”","mis":[{"says":"“疫苗会让你得同样的病。”","answer":"疫苗里是微生物的一部分，或减弱的、失去活性的微生物，不会致病；可能让手臂疼或稍微发烧一两天，然后就好了。"},{"says":"“我很强壮，不需要疫苗，我的疫苗只保护我自己。”","answer":"强壮的人也会生病，你的疫苗还和你一起保护周围不能接种的人，比如免疫力弱的人。"},{"says":"“得了传染病的人是不小心，我们要远离他、责怪他。”","answer":"谁都会生病；我们用洗手、用手肘挡喷嚏来保护自己，照顾病人，在医生允许时去看望，不责怪。"},{"says":"“在烫伤处涂黄油或牙膏能降温。”","answer":"急救方法是用流动的冷水冲20分钟；烫伤处不涂黄油、药膏或油。"}],"dinner":{"q":"疫苗怎样预防一种你还没得过的病？为什么你的疫苗能保护别人？如果有人在你面前烫伤了手，你会怎么做？","listen":"疫苗用微生物的一部分或减弱的微生物训练身体，让身体在不生病的情况下产生抗体并记住它；大多数人接种后，微生物就不容易传到弱的人身上。烫伤要在流动的冷水下冲20分钟，不涂黄油，并叫大人。"},"faith":[]},{"id":"U09.L05","unit":"U09","ar":"الدواء: نافع ومحفوظ","zh":"药物：有用，也要保管好","point":"按照医生或药剂师说的、由大人给的药是有用的；剂量过多或给了不是开给他的人，药就可能有害；所以不吃别人的药，药要放在高处、远离小孩子；咖啡因是一种兴奋剂，孩子不需要，水是最好的饮料。","objectives":[{"zh":"知道按照医生或药剂师说的剂量、由信任的大人给的药是有用的；剂量过多或给了不是开给他的人，药就可能有害。"},{"zh":"知道处方是开给某一个人的，所以不吃别人的药，也不把自己的药给别人；抗生素对感冒这样的病毒没有作用（防御一课）。"},{"zh":"知道药品和清洁剂要放在高处，远离小孩子的手和视线；药不能叫作糖果；看到小孩子拿到或吞下药，要马上告诉大人。"},{"zh":"知道咖啡因是某些饮料里的兴奋物质，能量饮料不适合孩子，水是最好的饮料。"},{"zh":"知道怎样确认一种药有效：针对一种病做公平测试，效果在大多数病例中重复出现，并在人身上试验；这些是伊本·西那在《医典》中提出的条件。","b":true}],"terms":[{"ar":"الدواء","zh":"药物","py":"yàowù","en":"Medicine"},{"ar":"الوصفة الطبية","zh":"处方","py":"chǔfāng","en":"Prescription"},{"ar":"تاريخ الانتهاء","zh":"有效期","py":"yǒuxiàoqī","en":"Expiry date"},{"ar":"الكافيين","zh":"咖啡因","py":"kāfēiyīn","en":"Caffeine"},{"ar":"اختبار الدواء","zh":"药物试验","py":"yàowù shìyàn","en":"Testing a medicine"}],"do":"“安全的家地图”：孩子从上往下画出家的平面图：厨房、浴室、卧室、客厅；和家人一起看药品和清洁剂现在放在哪里，在每个地方贴上标签；问一问：小弟弟小妹妹站在椅子上能够到吗？能看到吗？高处、看不到的贴绿色，近处的贴红色；和家人一起选一个又高又能锁上的地方集中放所有的药，并和大人一起把当地的急救电话写在旁边。","safety":["在这个活动中孩子不碰药盒和清洁剂，由大人来移动。","不打开药盒，也不尝药。","地图上不写药名，只写“药品”和“清洁剂”。"],"explain":"可以这样说：“药是帮助身体康复或减轻疼痛的东西。按照医生或药剂师规定的量、由我们信任的大人——妈妈、爸爸或学校的护士——给的时候，药是有用的。剂量要看年龄、体重和病情，所以你不能自己决定。药吃多了，可能不但没有帮助反而有害。不要吃朋友给的药，也不要吃你找到的药盒里的药。处方是医生为某一个人写的：什么药、多少、什么时候吃、吃多久，都是按照这个人的年龄、体重和病情选的。所以即使你的病和哥哥的很像，也不要吃他的药，也不要把你的药给别人。还记得防御那一课吗？抗生素能杀死细菌，对感冒、流感这样的病毒没有作用，所以感冒不吃抗生素，剩下的也不留着下次用。小孩子喜欢用手和嘴去探索，有些药甜甜的、颜色好看，所以药品要放在高处、锁起来，也不要把药叫作糖果。能量饮料里有很多兴奋剂和糖，孩子不需要，渴了就喝水。”","mis":[{"says":"“我的病和哥哥的很像，就吃他的药。”","answer":"处方是开给某一个人的：医生是按哥哥的年龄、体重和病情选的药和剂量；两个人的病可能很像，原因却不一样。"},{"says":"“药吃得越多，好得越快。”","answer":"每种药都有医生或药剂师规定的剂量；多吃不会好得更快，反而可能有害。"},{"says":"“甜甜的药像糖果一样，吃一点没关系。”","answer":"做成甜的是为了好喝，但它是有剂量的药；不叫它糖果，只从大人手里拿来吃。"},{"says":"“能量饮料像食物一样给我能量。”","answer":"能量来自食物和睡眠；能量饮料里有很多兴奋剂和糖，不该出现在孩子的饮食中；水是最好的饮料。"}],"dinner":{"q":"我们家的药品和清洁剂放在哪里？小孩子够得到吗？为什么不吃别人的药？","listen":"放在高处、锁好，远离小孩子的手和视线，不把药叫作糖果；处方是开给本人的，因为医生是按他的年龄、体重和病情选的药和剂量；抗生素对感冒没用；渴了喝水，不喝能量饮料。"},"faith":[]},{"id":"U10.L01","unit":"U10","ar":"كيف أكبر؟","zh":"我是怎样长大的？","point":"身体长大是因为细胞在分裂；长骨在两端附近的生长板处变长，直到青春期结束时生长板变硬；成长需要睡眠（生长激素大多在睡眠中分泌）、营养和运动。身高的差别大多来自遗传，所以孩子只和自己比，不和别人比。","objectives":[{"zh":"能用细胞分裂解释身体的成长：细胞复制里面的东西，包括它的指令，然后分成两个一样的细胞；身体也用同样的分裂来修复伤口、更新皮肤。"},{"zh":"能指出生长板：长骨两端附近的软骨，新的骨头从这里加上去，骨头就变长；青春期结束时它变硬，身高就不再增加；生长板比骨头弱，所以孩子关节附近受伤要看医生。"},{"zh":"能把成长和睡眠、营养、运动联系起来：生长激素是大脑发出的信号，大部分在睡眠中分泌；多样的食物和运动能强健骨骼和肌肉；多吃或多吃维生素不会让人更高。"},{"zh":"能用遗传和环境解释身高的不同：每个细胞里都有指令（DNA），一半来自妈妈，一半来自爸爸，身高的差别大多来自遗传；孩子们长得快慢和早晚不同，所以孩子要和过去的自己比，不和别人比，身高不代表力量或价值。"},{"zh":"知道这些指令装在46条染色体里，组成23对，每对一条来自妈妈、一条来自爸爸；并能通过世界卫生组织的全球研究说明，不同国家的小孩子在有营养和照顾时生长得很相似。","b":true}],"terms":[{"ar":"انقسام الخلية","zh":"细胞分裂","py":"xìbāo fēnliè","en":"Cell division"},{"ar":"صفيحة النمو","zh":"生长板","py":"shēngzhǎngbǎn","en":"Growth plate"},{"ar":"هرمون النمو","zh":"生长激素","py":"shēngzhǎng jīsù","en":"Growth hormone"},{"ar":"الحمض النووي","zh":"脱氧核糖核酸","py":"tuōyǎng hétáng hésuān","en":"DNA"},{"ar":"الوراثة","zh":"遗传","py":"yíchuán","en":"Heredity"},{"ar":"الكروموسوم","zh":"染色体","py":"rǎnsètǐ","en":"Chromosome"}],"do":"“早上更高？一天量两次身高”：经大人同意，在墙或门上贴一条长纸胶带，从地面一直贴到头顶以上；早上刚醒时光脚站好，背和脚跟贴墙，眼睛看前方，大人把书平放在头顶，在胶带上做记号写“早”；睡前用同样的方法再量一次写“晚”；量两个记号之间差几毫米；连续三天重复。","safety":["由大人放书和做记号；不站在椅子上，头上不放重东西。","纸胶带要经大人同意，免得损坏墙漆，不直接在墙上写字。","量身高是私人的事：不和别人比身高，不嘲笑任何人的身高。"],"explain":"可以这样说：“你出生时大约半米长，现在长高了很多。多出来的从哪里来？身体是由细胞构成的。长大时，原来的细胞不是像气球一样吹大，而是数量变多。怎么变多？细胞先把里面的东西，包括它的指令，复制一份，然后分成两个一样的细胞，每个又可以再分裂，这就是细胞分裂。皮肤修补擦伤、更新表皮，也是靠分裂。那怎么长高呢？在每根长骨的两端附近，比如大腿骨、小腿骨、前臂骨，有一层软软的软骨，叫生长板。那里的细胞分裂，新的部分变成骨头，骨头就从两端变长，而不是从中间。生长板一直工作到青春期结束，然后变硬，身高就不再增加，所以大人不会再长高。生长板比硬骨头弱，摔倒后关节附近很疼要去看医生。成长需要睡觉，因为生长激素大多在睡眠中分泌，也需要多样的食物和运动。早上比晚上高一点，是因为白天椎骨之间的软垫被压紧了，晚上又恢复。”","mis":[{"says":"“高的人更强、更好，矮的人是发育慢或有问题。”","answer":"身高的差别大多来自遗传，孩子们长得快慢和早晚不同；医生是拿孩子和他过去的自己比。身高不代表力量或价值。"},{"says":"“我是白天活动和吃饭的时候长高的，睡觉是浪费时间。”","answer":"生长激素大多在睡眠中分泌；而且白天椎骨之间的软垫被压紧，身高会稍微变矮，晚上又恢复。"},{"says":"“吃得越多、吃越多维生素，我就长得越高。”","answer":"多样的食物就够成长用；多吃不会增加身高，只会增加体重。身高大多由遗传决定，还需要睡眠和运动。"},{"says":"“骨头从中间变长，或者像气球一样整个变大。”","answer":"长骨是从两端附近的两块生长板变长的；所以生长板变硬后大人就不会再长高。"}],"dinner":{"q":"你知道为什么早上你会高一点吗？骨头是从哪里变长的？","listen":"长骨从两端附近的生长板变长，直到青春期结束；细胞分裂让身体长大，生长激素大多在睡眠中分泌。晚上稍微矮一点，是因为白天椎骨之间的软垫被压紧了。不拿孩子和别人比。"},"faith":[]},{"id":"U10.L02","unit":"U10","ar":"تغيّرات قادمة: البلوغ","zh":"即将到来的变化：青春期","gated":true,"point":"青春期是孩子的身体变成大人身体的几年：由大脑用激素开始，开始的时间在孩子之间差别很大。每个人都会经历身高突增、汗味变重、长青春痘和长出新的毛发；男孩和女孩各有自己特有的变化；这些都是正常的，没有什么可羞耻的。伊斯兰教中，青春期也是开始承担宗教责任的时候。","objectives":[{"zh":"知道青春期是孩子的身体变成大人身体的几年，由大脑通过信号（激素）开始；女孩通常在8到13或14岁之间开始，男孩在9到14岁之间，持续两到五年；开始的时间差别很大，这都是正常的。"},{"zh":"能描述每个人都会有的变化并做好护理：身高突增；汗腺更活跃、气味更重（每天洗澡，穿干净衣服）；皮脂腺更活跃、长青春痘（温和地洗，不挤）；长出新的毛发。"},{"zh":"男孩版：能用科学名称描述男孩的变化：睾丸先变大，然后是身高突增、肌肉增加、声音变粗、长胡子，遗精是正常的，没有什么可羞耻的；并知道女孩有她们特有的变化，要尊重。女孩版：能用科学名称描述女孩的变化：乳房先开始发育，然后是身高突增，大约两年后子宫开始来月经，大约每个月一次，这是正常的，没有什么可羞耻的，也不妨碍正常生活；并知道男孩有他们特有的变化，要尊重。"},{"zh":"能用激素和生活变化解释青春期情绪起伏和更需要隐私，会向信任的大人求助，不嘲笑别人的变化，不拿自己的身体和别人比。"},{"zh":"知道青春期是承担宗教责任的开始：穆斯林开始对自己的礼拜、斋戒和洁净负责。男孩版：男孩遗精后如发现痕迹，礼拜前要洗大净（全身洗）。女孩版：月经期间不礼拜、不封斋，月经结束后洗大净再礼拜，补斋月里缺的斋，不补礼拜。成年后进入别人房间前要先请求允许，就像大人那样。"},{"zh":"能排出信号链：大脑里的一个部位（下丘脑）给脑垂体发信号，脑垂体把激素送到睾丸（男孩，制造睾酮）或卵巢（女孩，制造雌激素），于是出现各种变化；并知道“激素”这个词是在1905年贝利斯和斯塔林的实验之后提出的。","b":true}],"terms":[{"ar":"البلوغ","zh":"青春期","py":"qīngchūnqī","en":"Puberty"},{"ar":"هرمونات البلوغ","zh":"性激素","py":"xìng jīsù","en":"Sex hormones"},{"ar":"طفرة النمو","zh":"生长突增","py":"shēngzhǎng tūzēng","en":"Growth spurt"},{"ar":"علامات البلوغ","zh":"青春期征象","py":"qīngchūnqī zhēngxiàng","en":"Signs of puberty"},{"ar":"التكليف","zh":"宗教责任","py":"zōngjiào zérèn","en":"Religious accountability (taklif)"}],"do":"“青春期时间轴：什么时候开始？什么时候结束？”：孩子画一条长横线，等距标出8到17岁；用一种颜色在线上方画女孩的条带：8到13岁开始，身高突增的高峰约12岁，第一次月经约12岁（可能早一些或晚一些），约14或15岁停止长高；用另一种颜色在线下方画男孩的条带：9到14岁开始，突增最快在12到15岁，约16岁停止长高；在自己现在的年龄处画一颗星。","safety":["活动只在纸上进行，不比较真实孩子的身体。","不问孩子自己身体上的青春期征象；星星只标年龄。","个人问题私下问家长。"],"explain":"可以这样说：“你已经知道身体是一个细胞一个细胞长大的。接下来几年会有一个更大的变化，叫青春期：孩子的身体变成大人身体的几年。它由大脑开始：大脑往血液里发出化学信号，叫性激素，这几年它们会大大增加，命令身体发生变化。女孩通常在8岁到13、14岁之间开始，男孩在9岁到14岁之间，持续两到五年。比朋友早一点或晚一点开始都是正常的；如果担心，就告诉爸爸妈妈，医生会让他们放心。男孩女孩都会有的变化：身高突增，长得比童年以后任何时候都快；汗腺更活跃，气味更重，所以要每天用温和的肥皂洗澡、每天换干净衣服；皮脂腺分泌更多油脂，脸上会长痘痘，头发也容易油，要温和地洗，不要挤；还会长出新的毛发。男孩：睾丸先变大，然后长高、长肌肉、声音变粗、长胡子，会有遗精，这是正常的。女孩：乳房先开始发育，然后长高，大约两年后开始来月经，这也是正常的。这时可以告诉孩子：有任何问题都可以私下来问我。”","mis":[{"says":"“比朋友早或晚进入青春期，就说明身体有问题。”","answer":"正常的范围很宽：女孩在8到13或14岁之间，男孩在9到14岁之间；担心的话就告诉家人，由医生判断。"},{"says":"男孩：“遗精是一种病，或者是丢脸的事，要瞒着家人。”女孩：“月经是一种病，或者是丢脸的事，要瞒着家人。”","answer":"遗精（女孩：月经）是成长的正常部分，没有什么可羞耻的，也不是病；告诉爸爸或妈妈，并学习相关的洁净规定。"},{"says":"“有体味、长痘痘是因为我不干净或吃糖。”","answer":"主要原因是青春期激素让汗腺和皮脂腺更活跃；每天清洁能减轻，但不能完全避免。"},{"says":"“青春期是一天之内发生的事。”","answer":"青春期要持续两到五年，变化是一步一步来的。"}],"dinner":{"q":"你觉得青春期是什么？有什么想单独问我的吗？","listen":"是身体变成大人身体的几年，由大脑通过激素开始，开始的时间各不相同，都是正常的；要每天护理身体，宗教责任也从这时开始。这不是在饭桌上当着大家问的问题：要选一个安静的时候，诚实地、按孩子的年龄回答他所有的问题。"},"faith":[]},{"id":"U10.L03","unit":"U10","ar":"جسمي أمانة: الخصوصية والحدود","zh":"我的身体是托付给我的：隐私和界限","point":"你的身体属于你，私密部位就是内衣遮住的地方：别人不能看，也不能碰，除非是帮你清洁或治疗。如果有什么事让你不舒服，身体会提醒你：说“不”，离开，告诉一个信任的大人，直到有人相信你。关于身体的秘密不能保守，孩子永远不该被责怪。","objectives":[{"zh":"能说出自己身体的私密部位：内衣遮住的地方，包括生殖器官；知道身体是托付给自己的，即使是爱他的人想碰他，他也可以有礼貌地说“不”。"},{"zh":"能区分安全和不安全的接触：别人不能看或碰他的私密部位，不能要求他碰别人的私密部位，也不能给他看私密部位的图片；只有父母或照顾他的人在帮他清洁或治疗时、医生因健康原因在父母一方在场并解释原因时例外。"},{"zh":"会用“不、离开、告诉”的规则，留意身体的警报（心跳加快、肚子发紧），说出五个信任的大人，并一直说，直到有人相信他。"},{"zh":"能区分很快会揭晓的快乐惊喜和被要求保守的让人不舒服的秘密；知道关于身体的秘密不能保守，要求他保密的人可能是认识的人，孩子永远不该被责怪。"},{"zh":"尊重别人的隐私：进入关着门的房间前先请求允许，不看别人的羞体，不拍照，不嘲笑别人的身体。"},{"zh":"能在屏幕上保护自己：不发送自己身体的照片，也不发送能找到他的信息；在网上认识的人，只有在家人允许并陪同时才能见面；任何让他害怕或要求保密的信息都要告诉大人。","b":true}],"terms":[{"ar":"الأجزاء الخاصة","zh":"隐私部位","py":"yǐnsī bùwèi","en":"Private parts"},{"ar":"الخصوصية","zh":"隐私","py":"yǐnsī","en":"Privacy"},{"ar":"الحدود","zh":"界限","py":"jièxiàn","en":"Boundaries"},{"ar":"الكبير الموثوق","zh":"可信赖的大人","py":"kě xìnlài de dàrén","en":"Trusted adult"},{"ar":"السر المزعج","zh":"不安全的秘密","py":"bù ānquán de mìmì","en":"Unsafe secret"}],"do":"“安全手：我信任的五个大人”：孩子用笔在纸上描出自己的手掌；和家长一起，在每根手指上写一个信任、愿意听他说话的大人的名字，至少有一个是家以外的人（老师、奶奶、姨妈……）；在手掌中间用自己的话写下规则：不、离开、告诉；家长读三个课里的小情境，孩子说出每个情境安全不安全、该怎么做、告诉谁；把这只手挂在看得见的地方，几个月后和家人一起再看一看。","safety":["活动由家长陪同，只用说话和画画；不表演接触。","情境中不把真实的人说成伤害者；情境都是想象的。","如果孩子想起了一件真的让他不舒服的事，家长要平静地听，感谢他、相信他，并向专业人士求助。"],"explain":"可以这样说：“前面几课你知道了身体怎样工作、怎样长大。今天问一个新问题：这个身体是谁的？是你的，是真主托付给你、要你好好保护的。所以你可以决定谁能靠近你。如果有人想抱你或亲你，而你不愿意，即使是你爱的亲人，你也可以用别的方式有礼貌地打招呼：握手、微笑或说句好听的话。你有你的界限，别人也有他的界限，要尊重。你身上有私密部位：就是内衣遮住的地方，包括生殖器官。规则是：任何人都不能看或碰你的私密部位，不能要你碰或看他的私密部位，也不能给你看这样的图片。只有两种情况例外：爸爸妈妈或照顾你的人在你需要时帮你清洁或上药；医生因为健康原因检查你，爸爸或妈妈在旁边，并且告诉你为什么。其他情况，规则就是：不。还记得害怕那一课吗？有事让你不安时，心跳会加快、肚子会发紧、你会想离开，这是身体在提醒你：说不，离开，告诉信任的大人，如果第一个人不相信你，就继续告诉别人。快乐的惊喜只保密一会儿就会揭晓，但让你不舒服的秘密、和身体有关的秘密，不用保守。无论发生什么，告诉我，你都不会有麻烦。”","mis":[{"says":"“伤害孩子的人总是陌生人；认识的人要求什么都没关系。”","answer":"规则对所有人都一样：任何人都不能看或碰你的私密部位，即使是你认识、你爱的人；如果有事让你不舒服，就告诉大人。"},{"says":"“答应了就是答应了：如果我答应保守秘密，就永远不说。”","answer":"快乐的惊喜保密一会儿就会揭晓；让你不舒服的秘密或和身体有关的秘密，不需要遵守承诺，说出来才是对的。"},{"says":"“如果发生了让我不舒服的事，是我的错，说出来会被惩罚。”","answer":"孩子永远不该被责怪，责任在大人身上；说出来的孩子做得对，要感谢他、相信他。"},{"says":"“亲戚要抱我，我就必须抱，不然就是没礼貌。”","answer":"你的身体属于你，你可以用别的方式有礼貌地打招呼，比如握手或微笑；礼貌在于好好说话，而不是勉强身体。"}],"dinner":{"q":"惊喜和让人不舒服的秘密有什么不同？你画的安全手上有哪五个大人？","listen":"惊喜只保密一会儿就会揭晓，大家都高兴；让人不舒服的秘密不用保守，要告诉信任的大人。规则是：不、离开、告诉，对所有人都一样；孩子永远不该被责怪。向他保证：“无论发生什么，告诉我，你都不会有麻烦。”"},"faith":[]},{"id":"U10.L04","unit":"U10","ar":"من البداية إلى الشيخوخة","zh":"从生命开始到老年","point":"人从一个细胞开始，这个细胞由来自妈妈的一个细胞和来自爸爸的一个细胞结合而成；然后在子宫里作为胎儿生长大约四十周，出生后经历人生各个阶段直到老年，骨骼、肌肉、眼睛和耳朵都会变化；运动能延缓这些变化，孝敬能帮助老人。","objectives":[{"zh":"知道人从一个细胞开始，这个细胞由来自妈妈的一个细胞和来自爸爸的一个细胞结合而成，然后不断分裂，胎儿在子宫里生长大约四十周，通过脐带从妈妈那里得到营养和氧气。"},{"zh":"能排出人生的阶段：婴儿期、童年、青春期、成年和老年，并说出每个阶段的特点。"},{"zh":"知道老年时会发生的变化：骨密度降低，肌肉力量减弱，关节变僵硬，眼睛看近处困难，听高音变弱；运动是延缓这些变化最好的方法之一。"},{"zh":"帮助和孝敬老人：面对老人清楚地说话，有耐心，帮他们拿重东西，陪他们散步，不嘲笑，也不按年龄评判任何人。"},{"zh":"能解释科学家怎样发现新生儿认得妈妈的声音：他们设置吸奶嘴的方式来决定宝宝听到哪个声音，结果宝宝更多地选择了妈妈的声音。","b":true}],"terms":[{"ar":"الرحم","zh":"子宫","py":"zǐgōng","en":"Womb (uterus)"},{"ar":"الجنين","zh":"胎儿","py":"tāi'ér","en":"Fetus"},{"ar":"الحبل السري","zh":"脐带","py":"qídài","en":"Umbilical cord"},{"ar":"مراحل العمر","zh":"人生阶段","py":"rénshēng jiēduàn","en":"Life stages"},{"ar":"الشيخوخة","zh":"老年","py":"lǎonián","en":"Old age"}],"do":"“生命的纸条：从一个细胞到爷爷奶奶”：孩子在一条长纸条的开头画一个小点（第一个细胞），然后画子宫里慢慢长大的胎儿，再画新生儿；按顺序贴上阶段卡片：婴儿、儿童、青少年、成年人、老年人；在每个阶段下写一件人在这个阶段能做的事；和家人一起礼貌地问爷爷奶奶或年长的邻居：您喜欢做什么？我怎样帮助您？最后写下这周要为一位老人做的三件事。","safety":["不要求孩子在全班面前谈自己的家庭；采访是自愿的，对象可以是任何他认识的老人。","老花镜只让孩子试戴几秒钟，不长时间戴。","对老人说话要有礼貌，没有允许不给他们拍照。"],"explain":"可以这样说：“我们每个人都是从一个很小很小、眼睛看不见的细胞开始的，这个细胞由来自妈妈的一个细胞和来自爸爸的一个细胞结合而成，所以你既像妈妈又像爸爸。然后这个细胞分裂了很多次，就像成长那一课讲的，来到子宫里。子宫是妈妈肚子里的一个器官，胎儿在里面长大直到出生。胎儿就是还在妈妈子宫里成长的小人儿。胎儿在子宫里怎么吃饭、呼吸？他不用嘴吃，也不呼吸空气，有一根脐带把他和妈妈连在一起，营养和氧气从妈妈的血液通过脐带送给他。出生后脐带被剪断，留下的痕迹就是你的肚脐！大约第十二周，胎儿的大部分器官已经形成，然后越长越大，通常大约四十周、也就是九个月左右出生。他在子宫里就能听到声音，包括妈妈的声音。出生后，人要经历婴儿期、童年、青春期、成年和老年。老了以后，骨头和肌肉变弱，眼睛和耳朵也会变化，运动能让这些变化来得慢一些；我们要清楚地对老人说话、帮他们拿重东西、陪他们走走。”","mis":[{"says":"“胎儿住在妈妈的胃里，吃妈妈吃的东西。”","answer":"胎儿在子宫里，不在胃里；食物由妈妈消化，营养再从妈妈的血液通过脐带送到胎儿的血液。"},{"says":"“宝宝出生前什么也听不到、什么也不知道。”","answer":"胎儿能听到外面的声音，包括妈妈的声音；新生儿认得并会选择妈妈的声音，就像德卡斯珀和法弗的实验那样。"},{"says":"“老人不能学习也不能活动，运动对他们没有用。”","answer":"老人能学习也能活动，运动是延缓骨骼和肌肉变弱最好的方法之一；按年龄评判别人是有害的歧视。"},{"says":"“爷爷听不清我说话，跟他说话没用。”","answer":"随着年龄增长，听高音的能力可能变弱；我们面对他、清楚地说，不用大喊，他就能听懂，也会很高兴。"}],"dinner":{"q":"我们每个人是怎样开始的？人老了身体会有什么变化？我们怎样帮助家里和邻居中的老人？","listen":"从妈妈的一个细胞和爸爸的一个细胞结合成的一个细胞开始，然后在子宫里靠脐带生长大约九个月；老了以后骨骼、肌肉、听力和视力变弱，运动能延缓这些变化；我们面对老人清楚地说话，帮他们拿重东西，陪他们散步，去看望他们。"},"faith":[]},{"id":"U10.L05","unit":"U10","ar":"أجسام مختلفة","zh":"不一样的身体","point":"我们的身体各不相同：有的人有行动、听力或视力方面的残疾，有的人有慢性病，比如哮喘、糖尿病、严重过敏和癫痫；这些都不会传染，辅助器具、消除障碍和尊重能让每个同学和我们一起学习、一起玩。","objectives":[{"zh":"知道几种残疾（行动、听力和视力）以及各自的辅助器具：轮椅和拐杖，助听器和手语，眼镜、白手杖和盲文。"},{"zh":"知道同学可能患有的慢性病在身体里发生了什么：哮喘（气道肿胀变窄）、1型糖尿病（胰腺不能制造调节血糖的信号）、严重过敏（防御系统对某种食物反应强烈）、癫痫（大脑信号一阵阵紊乱造成的发作）。"},{"zh":"知道这些情况不会传染，也不是本人的错；知道怎样帮忙：保持冷静，马上叫大人，不和有过敏的同学分享食物，癫痫发作时不往他嘴里放东西，也不按住他。"},{"zh":"尊重有残疾或慢性病的同学：先问再帮，直接和他本人说话而不是和陪同的人说，不嘲笑，也不用让人难受的方式可怜他，邀请他一起玩。"},{"zh":"能解释残疾是身体状况和周围环境共同造成的，消除障碍后影响就会减小；例子是路易·布莱叶在大约十五岁时发明的盲文。","b":true}],"terms":[{"ar":"الإعاقة","zh":"残疾","py":"cánjí","en":"Disability"},{"ar":"أدوات العون","zh":"辅助器具","py":"fǔzhù qìjù","en":"Assistive products"},{"ar":"لغة الإشارة","zh":"手语","py":"shǒuyǔ","en":"Sign language"},{"ar":"طريقة برايل","zh":"盲文","py":"mángwén","en":"Braille"},{"ar":"المرض المزمن","zh":"慢性病","py":"mànxìngbìng","en":"Chronic condition"}],"do":"“我们的学校属于每个人：寻找障碍”：和老师一起在学校走廊里走一走，想象自己坐在轮椅上：哪里有台阶却没有坡道？哪里的门太窄？在每个障碍处贴红色标签，在每个帮助处（坡道、电梯、宽门）贴绿色标签；闭上眼睛摸一摸有凸点的卡片：认得几个字母？跟老师学用本国手语表达“谢谢”和“朋友”；最后和小组一起给校长写一条消除某个障碍的建议。","safety":["不坐同学的轮椅，也不拿它玩。","想象是为了学习，不是为了取笑；不开玩笑地模仿残疾。","闭上眼睛时要有同学牵着你的手，并在安全的地方进行。"],"explain":"可以这样说：“我们的身体各不相同。有些人生活中有残疾：在行动、听力、视力或其他方面长期有困难。每种困难都有辅助器具，帮助人做那些有困难的事：行动方面有轮椅和拐杖；听力方面有助听器和手语，手语是用双手和表情表达的完整语言，很多聋人用它交流；视力方面有眼镜、白手杖和盲文，盲文是用凸起的小点写成、用指尖读的文字。辅助器具是主人的一部分，没有他的允许不要碰。残疾只在身体里吗？想一想：坐轮椅的同学面对没有坡道的台阶上不去，面对坡道就能轻松上去。所以残疾会因为周围有障碍还是有帮助而变大或变小。世界卫生组织估计，世界上大约每六个人里就有一个人有严重的残疾。消除障碍，路就属于每个人。还有些同学有慢性病，比如哮喘、1型糖尿病、严重过敏和癫痫，它们都不会传染，也不是谁的错。”","mis":[{"says":"“和有癫痫或糖尿病的同学玩，我可能会被传染。”","answer":"这些情况不会传染，接触、一起玩或分享食物都不会；癫痫不会像感冒那样传染。"},{"says":"“坐轮椅的人不能像我们一样玩和学习。”","answer":"他能学习也能玩，还有很多轮椅运动；障碍往往在台阶和窄门上，而不在他身上。"},{"says":"“我的同学得糖尿病是因为吃了太多糖。”","answer":"1型糖尿病不是吃东西或生活习惯造成的；是胰腺不再制造调节血糖的信号，不是他的错。"},{"says":"“同学癫痫发作时，我要往他嘴里放东西，并用力按住他。”","answer":"不往他嘴里放任何东西，也不按住他；把可能伤到他的东西移开，如果他躺着就轻轻让他侧躺，并叫大人。"}],"dinner":{"q":"人们会用哪些辅助器具？同学哮喘或癫痫发作时我们怎样帮忙？我们怎样做身体和我们不一样的人的好朋友？","listen":"轮椅和拐杖、助听器和手语、眼镜、白手杖和盲文；哮喘发作时保持冷静、拿喷雾、叫大人，癫痫发作时叫大人、不往嘴里放东西、不按住他；这些都不会传染；先问再帮，直接和同学本人说话，不嘲笑。"},"faith":[]},{"id":"U11.L01","unit":"U11","ar":"جسمي فريق واحد: حين أركض","zh":"我的身体是一个团队：当我跑步时","point":"我们跑步时，身体的各个系统像一个团队一样一起工作：大脑和神经发起动作，呼吸和心脏把更多氧气送到肌肉，皮肤通过出汗散发肌肉产生的热，口渴和肾脏保住水分；然后在恢复期里一切都回到正常范围。","objectives":[{"zh":"能跟踪跑步开始时的链条：大脑做决定，神经把信息送到肌肉，工作的肌肉需要更多氧气和糖，于是呼吸变快变深，心跳加快，工作的肌肉里打开更多毛细血管。"},{"zh":"能解释热量和水的链条：工作的肌肉释放热量，下丘脑命令出汗并让血液靠近皮肤；出汗带走身体的水，于是感到口渴，肾脏把水留住，尿变少、变深。"},{"zh":"能解释恢复：停下以后，心跳、呼吸和体温在几分钟内回到正常范围，食物和水补充缺少的东西，睡眠进行修复；并把它用到日常习惯里：每天活动一小时，玩之前、玩的时候和玩之后都喝水，睡足觉。"},{"zh":"能在跑步前、跑步后和休息后做公平的测量（同样的方法、同样的时间），用所有系统而不是一个系统来解读自己的数字，并知道单个器官解释不了整个身体发生的事。"},{"zh":"知道体内平衡：身体把体温、水分和氧气保持在很窄的范围里，运动让某样东西超出范围时，身体会把它拉回来；并能用克罗格的实验解释，工作的肌肉比休息的肌肉打开更多的毛细血管。","b":true}],"terms":[{"ar":"جهاز الجسم","zh":"人体系统","py":"réntǐ xìtǒng","en":"Body system"},{"ar":"التعافي","zh":"恢复","py":"huīfù","en":"Recovery"},{"ar":"الاتزان الداخلي","zh":"体内平衡","py":"tǐnèi pínghéng","en":"Homeostasis"}],"do":"“之前和之后：我跳的时候身体有什么变化？”：孩子安静坐两分钟，数手腕脉搏30秒乘以2，再数呼吸30秒乘以2，写下皮肤是暖还是正常；经大人同意，原地跳或原地跑两分钟；一停下马上用同样的方法数脉搏和呼吸，观察：脸红了吗？出汗了吗？口渴吗？坐着休息五分钟后数第三次；喝水，晚上记录尿的颜色。","safety":["有哮喘、心脏病或容易头晕的孩子，要经家长和医生同意才参加；一旦喘不过气或头晕就马上停下。","在空旷的地方、穿合适的鞋跳，远离边缘和家具；天热时在阴凉处。","不比赛，也不和别人比数字：每个身体有自己的数字。"],"explain":"可以这样说：“在前面十个单元里，你一个一个认识了身体的器官。一组一起完成同一项工作的器官，叫一个系统：神经系统、呼吸系统、循环系统、消化系统等等。今天我们在两分钟的跑步里看到它们全部在工作。一切从大脑开始：你决定跑，信息就从大脑沿着神经传到腿部肌肉，肌肉收缩拉动骨头，就像肌肉那一课讲的。迈一步，里面至少有两个系统。工作的肌肉需要能量，能量是细胞用氧气从糖里释放出来的，就像细胞那一课讲的。所以肌肉要更多氧气，也排出更多二氧化碳。大脑里的感受器测到血里的变化，就命令呼吸更快更深，心跳加快，把血快速送过去。肌肉里还发生一件很美妙的事：休息时关着的许多毛细血管现在打开、变宽，血能到达更多细胞。肌肉工作还会产热，所以你会出汗、脸变红；出汗带走水，你就口渴，肾脏也会把水留住。停下来休息几分钟，一切又回到原来的样子。”","mis":[{"says":"“身体每个系统各干各的：肺管呼吸，心脏管血，互不相关。”","answer":"各个系统像一个团队一起工作：肌肉需要肺里来的氧气，心脏运送它，大脑同时调节两者；一个出问题，其他的也会累。"},{"says":"“跑完步我喘气是因为肺累了、变弱了。”","answer":"喘气说明肌肉要更多氧气、排出更多二氧化碳，所以大脑让呼吸加快；休息后就会平静下来。"},{"says":"“出汗说明身体弱或生病了。”","answer":"出汗是在肌肉产热时给身体降温；这是身体在正常工作，我们要补充流失的水。"},{"says":"“玩完了才喝水，口渴就够提醒我了。”","answer":"建议在玩之前和玩的时候都喝水，特别是天热时；口渴的信号稍微来得晚，尿色深说明身体需要水。"}],"dinner":{"q":"今天你跑步时，心跳、呼吸和皮肤发生了什么？你为什么会口渴？","listen":"工作的肌肉要氧气，所以呼吸和心跳加快；肌肉产热，出汗让皮肤降温；出汗带走水，所以口渴，肾脏把水留住；休息后一切回到正常。各个系统是一个团队。"},"faith":[]},{"id":"U11.L02","unit":"U11","ar":"الدخان والجسم كله","zh":"烟雾和整个身体","point":"烟雾从肺进入，却能到达全身：它伤害纤毛和肺泡；一氧化碳减少血液里的氧气，让心脏疲劳；尼古丁很快到达大脑，让心跳加快并造成成瘾。二手烟、水烟和电子烟都不安全。","objectives":[{"zh":"能解释烟雾的伤害怎样从肺扩展到全身：它伤害纤毛和肺泡，烟里的一氧化碳减少红细胞携带的氧气，于是心脏和肌肉都会疲劳。"},{"zh":"能解释成瘾：尼古丁很快到达大脑，释放肾上腺素，让心跳加快、血压升高、血管收缩，然后身体一次又一次地要它；孩子可能几天内就成瘾，所以没有“只抽一支”，也没有“想停就能停”。"},{"zh":"知道别人的烟也会伤害自己，没有安全的量，特别是对孩子；水烟也是烟，水不能净化它；电子烟释放的是含尼古丁和有害物质的气雾，不是水蒸气。"},{"zh":"能有礼貌地拒绝烟并走开，保护自己不吸二手烟，用爱和尊重与吸烟的亲人交谈，不嘲笑，也不说教。"},{"zh":"能描述科学家怎样发现吸烟会导致肺癌：1950年多尔和希尔比较了肺癌病人和其他病人，然后跟踪调查了三万四千多名医生五十年。","b":true}],"terms":[{"ar":"النيكوتين","zh":"尼古丁","py":"nígǔdīng","en":"Nicotine"},{"ar":"أول أكسيد الكربون","zh":"一氧化碳","py":"yīyǎnghuàtàn","en":"Carbon monoxide"},{"ar":"الإدمان","zh":"成瘾","py":"chéngyǐn","en":"Addiction"},{"ar":"دخان الآخرين","zh":"二手烟","py":"èrshǒuyān","en":"Secondhand smoke"},{"ar":"دراسة المتابعة","zh":"队列研究","py":"duìliè yánjiū","en":"Cohort study"}],"do":"“细吸管：呼吸怎样变得困难？（模型）”：孩子坐着正常呼吸一分钟，感受肺的感觉；轻轻捏住鼻子，只用一根吸管坐着呼吸二十秒；一感到头晕或憋闷就马上停下，恢复正常呼吸；写下：用吸管呼吸是什么感觉？如果气道每天都这么窄会怎样？","safety":["有哮喘、心脏病或肺病的孩子不做这个活动，只观看或看图。","只坐着做二十秒，不在跑步时或天热时做；一头晕就马上停。","每个孩子用自己的吸管，不交换；不用真的烟，也不靠近烟。"],"explain":"可以这样说：“在'我呼吸的空气'那一课里你知道了，烟雾会伤害清洁气道的纤毛和让氧气通过的肺泡。可是肺并不是终点。烟草的烟里有七千多种化学物质，其中一些从肺泡进入血液，而血液流遍全身，就像心脏那一课讲的。所以医生说吸烟几乎伤害身体的所有器官，不只是肺。身体的系统是一个团队，伤害一个，就会波及其他。烟里有一种无色无味的有毒气体，叫一氧化碳。它进入血液后，占据红细胞里原本给氧气的位置，红细胞带的氧气就少了。还记得跑步那一课吗？肌肉和心脏本身都需要氧气，血里的氧气少了，心脏要拼命才能送够，肌肉也更快疲劳，所以吸烟的人运动时比别人更喘。烟草里还有尼古丁，它很快到达大脑，让心跳加快，身体会一次又一次地要它，这就是成瘾，孩子几天就可能上瘾，所以最容易的办法是从不开始。别人抽烟，旁边的人也会吸进去；水烟和电子烟也不安全。”","mis":[{"says":"“烟只伤害肺。”","answer":"它从肺进入，然后到达血液、心脏、血管和大脑；吸烟几乎伤害身体的所有器官。"},{"says":"“抽一支没关系，我想停就能停。”","answer":"尼古丁在孩子身上可能几天内就造成成瘾，之后很难戒掉；所以最容易的是从不开始。"},{"says":"“电子烟是带香味的水蒸气，没有害处。”","answer":"它大多含有尼古丁，气雾里有有毒物质和金属颗粒；不是水蒸气。"},{"says":"“只要我自己不抽，别人的烟就伤害不了我。”","answer":"二手烟没有安全的量，在孩子身上会引起胸部和耳朵感染以及哮喘发作。"}],"dinner":{"q":"烟是从肺进去的，为什么医生说它会伤害心脏和大脑？如果有人给你一支烟，你会怎么说？","listen":"烟里的物质从肺进入血液：一氧化碳减少氧气，让心脏疲劳；尼古丁很快到达大脑，造成成瘾。二手烟没有安全的量。回答是：“不，谢谢”，然后走开；我们爱吸烟的人，不嘲笑他。"},"faith":[]},{"id":"U11.L03","unit":"U11","ar":"الإنسان والحيوان","zh":"人和动物","point":"人和很多动物都有做同样工作、但形状不同的系统：鱼的心脏有两个腔，我们的有四个；鱼用鳃呼吸；长颈鹿的脖子和我们一样有七块颈椎；狗的嗅觉比我们灵敏得多。比较能让我们学到东西，但它有局限；动物是托付给我们的，要怜悯它们，摸过它们后要洗手。","objectives":[{"zh":"知道人和很多动物都有做同样工作的系统：心脏和血液、呼吸、消化、骨骼和肌肉、神经和感官，只是形状不同。"},{"zh":"能比较：鱼的心脏有两个腔，两栖动物有三个，鸟类和哺乳动物（包括人）有四个；鱼用鳃获取氧气；长颈鹿的脖子和人一样有七块颈椎。"},{"zh":"知道每种身体都适合它的生活方式：狗的鼻子里有多达3亿个嗅觉感受器，我们大约只有600万个；牛的胃分成四个部分，里面的微生物能消化我们消化不了的草。"},{"zh":"怜悯动物，并在和动物相处时保持健康：喂它、给它水、不伤害它，摸过以后要洗手，因为动物看起来健康也可能带有微生物。"},{"zh":"知道比较不同身体是一种古老的学习方法，比如贾希兹的《动物书》；也知道它有局限：动物的身体可能和人的不同，正如伊本·西那所说。","b":true}],"terms":[{"ar":"الفقاريات","zh":"脊椎动物","py":"jǐzhuī dòngwù","en":"Vertebrates"},{"ar":"الثدييات","zh":"哺乳动物","py":"bǔrǔ dòngwù","en":"Mammals"},{"ar":"الخياشيم","zh":"鳃","py":"sāi","en":"Gills"},{"ar":"المجترات","zh":"反刍动物","py":"fǎnchú dòngwù","en":"Ruminants"},{"ar":"التشريح المقارن","zh":"比较解剖学","py":"bǐjiào jiěpōuxué","en":"Comparative anatomy"}],"do":"“比较表：人、鱼、鸟和牛”：孩子在表里填写：心脏（几个腔）、呼吸（肺还是鳃）、消化（简单的胃还是分成几部分）、脊柱；用积木表示心脏的腔：鱼两个，鸟、牛和人四个；再用积木表示颈椎：人用七块小积木，长颈鹿用七块长积木；在相同的地方和不同的地方各做一种记号；最后在家里或学校写下照顾一只动物的三条规则。","safety":["不解剖动物，实验中也不伤害活的动物。","在学校摸过动物，要用水和肥皂洗手。","对动物过敏的孩子用图片参加。"],"explain":"可以这样说：“在这门课里，你一个系统一个系统地认识了自己的身体。动物也有这样的系统吗？很多都有：心脏和血液、呼吸、消化、骨骼和肌肉、神经和感官，只是形状不一样。人属于脊椎动物，就是有脊柱的动物，像鱼、青蛙和鸟。脊椎动物里有哺乳动物，就是给孩子喂奶的动物，像人、牛、长颈鹿和狗。记得吗？你的心脏有四个腔，鸟和哺乳动物也是四个；青蛙等两栖动物的心脏有三个腔，鱼的心脏只有两个。鱼用鳃获取氧气，鳃长在头的两侧，能吸取溶在水里的氧气，鱼的血液只走一圈：从心脏到鳃，再到全身。长颈鹿的脖子有几块颈椎？七块，和你一模一样！只是每一块都长得多。同样的设计，可以做成不同的大小。狗的鼻子里有多达3亿个嗅觉感受器，所以它能闻到我们闻不到的气味。我们要善待动物，给它们吃喝，不伤害它们，摸过以后要洗手。”","mis":[{"says":"“所有动物的心脏都和我的一模一样。”","answer":"心脏做同样的工作，但腔的数目不同：鱼两个，两栖动物三个，鸟和哺乳动物四个。"},{"says":"“长颈鹿的脖子长，是因为它的颈椎比我多得多。”","answer":"它和你一样有七块颈椎，只是每一块都长得多。"},{"says":"“我的猫很干净，跟它玩完不用洗手。”","answer":"动物看起来健康也可能带有微生物；摸过以后要洗手，同时爱它、照顾它。"},{"says":"“药在老鼠身上有效，就一定在人身上有效。”","answer":"动物的身体可能和人的不同；所以药也要在人身上试验，正如伊本·西那提出的条件。"}],"dinner":{"q":"我的身体和猫或小鸟的身体有什么相同的地方？有什么不同？我们怎样善待动物，又保护自己的健康？","listen":"我们都有心脏、骨骼和神经；小鸟的心脏和我们一样有四个腔，鱼只有两个并用鳃呼吸，长颈鹿的脖子和我们一样有七块颈椎，狗的嗅觉灵敏得多；我们给动物吃喝，不伤害它们，摸过以后洗手。"},"faith":[]},{"id":"U11.L04","unit":"U11","ar":"كيف أحكم على معلومة صحية؟ علماء أخطؤوا","zh":"怎样判断一条健康信息？犯过错的科学家","point":"相信一条健康说法，不能因为说的人有名或者它传得很广，而要看证据：谁说的？他怎么知道的？做过公平的比较吗？其他有学问的人怎么说？伟大的科学家也犯过错，是证据纠正了他们；正确的想法有时一开始被拒绝，后来才被证据接受。","objectives":[{"zh":"对任何健康说法都问四个问题：谁说的？他怎么知道的？做过公平的比较吗？其他有学问的人怎么说？并知道名气大和传得广都不是证据。"},{"zh":"知道伟大的科学家也会犯错，科学用证据纠正自己：盖伦说心脏的中隔上有小孔，后来的人包括伊本·西那都照着这样说，后来伊本·纳菲斯指出中隔是实心的，血液要经过肺。"},{"zh":"知道正确的想法一开始可能被拒绝：塞麦尔维斯比较了两个病房，让医生洗手后死亡减少了，可大多数医生拒绝他，直到细菌的证据出现；所以判断靠证据，不靠支持的人多。"},{"zh":"负责任地对待健康信息：不转发没有核实的消息，去问医生或信任的大人，知道“天然”不等于“安全”，不知道时就说“我不知道”，并准确地把学到的教给别人。"},{"zh":"能分清“在它之后发生”和“因为它而发生”，知道什么是盲法试验；并能用乌干达的“明智的健康选择”研究说明，和他同龄的孩子能学会判断健康说法。","b":true}],"terms":[{"ar":"الادعاء الصحي","zh":"健康声明","py":"jiànkāng shēngmíng","en":"Health claim"},{"ar":"الدليل","zh":"证据","py":"zhèngjù","en":"Evidence"},{"ar":"المقارنة العادلة","zh":"公平比较","py":"gōngpíng bǐjiào","en":"Fair comparison"},{"ar":"التجربة العمياء","zh":"盲法试验","py":"mángfǎ shìyàn","en":"Blind test"}],"do":"“信息实验室：相信、不相信、先核实”：孩子读第一条消息，问四个问题：谁说的？他怎么知道的？做过公平的比较吗？有学问的人怎么说？在每个问题旁做记号：消息里有没有答案？然后判断：相信、不相信，还是先核实，并用一句话写下理由；其余四条消息也这样做；最后和家人一起找一条家里真的收到过的健康消息，礼貌地用同样的问题检验它。","safety":["不试喝消息里说的任何饮料、药或偏方；药由医生和家长决定。","不嘲笑发了不可靠消息的人；和他一起礼貌地提问。","不打开陌生链接，也不提供个人信息。"],"explain":"可以这样说：“在十个单元里你学会了身体怎样工作。最后一个问题：你怎么判断听到的健康说法？健康说法就是说某样东西对健康有好处或有坏处，比如一种饮料、一种食物或一种习惯。它可能对，也可能错。相信之前先问四个问题：谁说的？他怎么知道的？做过公平的比较吗？其他有学问的人怎么说？让我们相信的东西叫证据：别人也能重复的观察、测量和比较。伟大的科学家会犯错吗？会。大约一千八百年前，希腊医生盖伦说心脏左右两边之间的中隔上有小孔，血从小孔流过。后来的医生都照着说，包括伊本·西那，他的《医典》被教了好几百年，错误也就跟着书传了下去。大约八百年前，开罗的伊本·纳菲斯说：中隔是实心的，没有通道，血液从右边流到肺，再回到左边。科学就是这样用证据纠正自己的。有时正确的想法一开始还会被拒绝，像塞麦尔维斯让医生洗手。所以判断要看证据，不看名气，也不看转发的人多。”","mis":[{"says":"“有名的医生说的，或者很多人转发的，就是真的。”","answer":"名气和转发多都不是证据；要问：他怎么知道的？做过公平的比较吗？其他有学问的人怎么说？"},{"says":"“伟大的科学家不会犯错，古书里写的都对。”","answer":"盖伦和伊本·西那都很伟大，却在心脏中隔的问题上犯了错，伊本·纳菲斯用证据纠正了它；科学会纠正自己。"},{"says":"“只要是天然的，就是安全的、无害的。”","answer":"有些天然产品没有证明有效，有些还有害；要问证据，药由医生和家长决定。"},{"says":"“我喝了那种饮料感冒就好了，所以是饮料治好了我。”","answer":"感冒几天就会自己好；“在它之后发生”不等于“因为它而发生”。公平的比较才能回答这个问题。"}],"dinner":{"q":"如果我们收到一条健康消息，你会问哪四个问题？是谁纠正了盖伦关于心脏的错误？","listen":"谁说的？他怎么知道的？做过公平的比较吗？有学问的人怎么说？伊本·纳菲斯纠正了盖伦说心脏中隔有小孔的说法，伊本·西那也曾照搬过这个说法；判断靠证据，不靠名气，也不靠转发多。"},"faith":[]}]};
